     contains

     !> SLAQSP: equilibrates a symmetric matrix A using the scaling factors
     !> in the vector S.

     pure subroutine la_slaqsp(uplo,n,ap,s,scond,amax,equed)
        use la_constants_sp
        ! -- lapack auxiliary routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(out) :: equed
           character,intent(in) :: uplo
           integer(ilp),intent(in) :: n
           real(sp),intent(in) :: amax,scond
           ! Array Arguments
           real(sp),intent(inout) :: ap(*)
           real(sp),intent(in) :: s(*)
        ! =====================================================================
           ! Parameters
           real(sp),parameter :: thresh = 0.1e+0_sp

           ! Local Scalars
           integer(ilp) :: i,j,jc
           real(sp) :: cj,large,small
           ! Executable Statements
           ! quick return if possible
           if (n <= 0) then
              equed = 'N'
              return
           end if
           ! initialize large and small.
           small = la_slamch('SAFE MINIMUM')/la_slamch('PRECISION')
           large = one/small
           if (scond >= thresh .and. amax >= small .and. amax <= large) then
              ! no equilibration
              equed = 'N'
           else
              ! replace a by diag(s) * a * diag(s).
              if (la_lsame(uplo,'U')) then
                 ! upper triangle of a is stored.
                 jc = 1
                 do j = 1,n
                    cj = s(j)
                    do i = 1,j
                       ap(jc + i - 1) = cj*s(i)*ap(jc + i - 1)
                    end do
                    jc = jc + j
                 end do
              else
                 ! lower triangle of a is stored.
                 jc = 1
                 do j = 1,n
                    cj = s(j)
                    do i = j,n
                       ap(jc + i - j) = cj*s(i)*ap(jc + i - j)
                    end do
                    jc = jc + n - j + 1
                 end do
              end if
              equed = 'Y'
           end if
           return
     end subroutine la_slaqsp
