     !> SPBTRS: solves a system of linear equations A*X = B with a symmetric
     !> positive definite band matrix A using the Cholesky factorization
     !> A = U**T*U or A = L*L**T computed by SPBTRF.

     pure subroutine la_spbtrs(uplo,n,kd,nrhs,ab,ldab,b,ldb,info)
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: uplo
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: kd,ldab,ldb,n,nrhs
           ! Array Arguments
           real(sp),intent(in) :: ab(ldab,*)
           real(sp),intent(inout) :: b(ldb,*)
        ! =====================================================================
           ! Local Scalars
           logical(lk) :: upper
           integer(ilp) :: j
           ! Intrinsic Functions
           intrinsic :: max
           ! Executable Statements
           ! test the input parameters.
           info = 0
           upper = la_lsame(uplo,'U')
           if (.not. upper .and. .not. la_lsame(uplo,'L')) then
              info = -1
           else if (n < 0) then
              info = -2
           else if (kd < 0) then
              info = -3
           else if (nrhs < 0) then
              info = -4
           else if (ldab < kd + 1) then
              info = -6
           else if (ldb < max(1,n)) then
              info = -8
           end if
           if (info /= 0) then
              call la_xerbla('SPBTRS',-info)
              return
           end if
           ! quick return if possible
           if (n == 0 .or. nrhs == 0) return
           if (upper) then
              ! solve a*x = b where a = u**t *u.
              do j = 1,nrhs
                 ! solve u**t *x = b, overwriting b with x.
                 call la_stbsv('UPPER','TRANSPOSE','NON-UNIT',n,kd,ab,ldab,b(1,j), &
                           1)
                 ! solve u*x = b, overwriting b with x.
                 call la_stbsv('UPPER','NO TRANSPOSE','NON-UNIT',n,kd,ab,ldab,b(1,j) &
                           ,1)
              end do
           else
              ! solve a*x = b where a = l*l**t.
              do j = 1,nrhs
                 ! solve l*x = b, overwriting b with x.
                 call la_stbsv('LOWER','NO TRANSPOSE','NON-UNIT',n,kd,ab,ldab,b(1,j) &
                           ,1)
                 ! solve l**t *x = b, overwriting b with x.
                 call la_stbsv('LOWER','TRANSPOSE','NON-UNIT',n,kd,ab,ldab,b(1,j), &
                           1)
              end do
           end if
           return
     end subroutine la_spbtrs
