           amax = s(1)
           do i = 2,n
              s(i) = a(i,i)
              smin = min(smin,s(i))
              amax = max(amax,s(i))
           end do
           if (smin <= zero) then
              ! find the first non-positive diagonal element and return.
              do i = 1,n
                 if (s(i) <= zero) then
                    info = i
                    return
                 end if
              end do
           else
              ! set the scale factors to the reciprocals
              ! of the diagonal elements.
              do i = 1,n
                 s(i) = base**int(tmp*log(s(i)),KIND=ilp)
              end do
              ! compute scond = min(s(i)) / max(s(i)).
              scond = sqrt(smin)/sqrt(amax)
           end if
           return
     end subroutine la_xpoequb
#endif
#ifdef LA_WITH_QP
     !> QPOEQUB: computes row and column scalings intended to equilibrate a
     !> symmetric positive definite matrix A and reduce its condition number
     !> (with respect to the two-norm).  S contains the scale factors,
     !> S(i) = 1/sqrt(A(i,i)), chosen so that the scaled matrix B with
     !> elements B(i,j) = S(i)*A(i,j)*S(j) has ones on the diagonal.  This
     !> choice of S puts the condition number of B within a factor N of the
     !> smallest possible condition number over all possible diagonal
     !> scalings.
     !> This routine differs from QPOEQU by restricting the scaling factors
     !> to a power of the radix.  Barring over- and underflow, scaling by
     !> these factors introduces no additional rounding errors.  However, the
     !> scaled diagonal entries are no longer approximately 1 but lie
     !> between sqrt(radix) and 1/sqrt(radix).

     pure subroutine la_qpoequb(n,a,lda,s,scond,amax,info)
        use la_constants_qp
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: lda,n
           real(qp),intent(out) :: amax,scond
           ! Array Arguments
           real(qp),intent(in) :: a(lda,*)
           real(qp),intent(out) :: s(*)
        ! =====================================================================

           ! Local Scalars
           integer(ilp) :: i
           real(qp) :: smin,base,tmp
           ! Intrinsic Functions
           intrinsic :: max,min,sqrt,log,int
           ! Executable Statements
           ! test the input parameters.
           ! positive definite only performs 1 pass of equilibration.
           info = 0
           if (n < 0) then
              info = -1
           else if (lda < max(1,n)) then
              info = -3
           end if
           if (info /= 0) then
              call la_xerbla('QPOEQUB',-info)
              return
           end if
           ! quick return if possible.
           if (n == 0) then
              scond = one
              amax = zero
              return
           end if
           base = la_qlamch('B')
           tmp = -0.5e+0_qp/log(base)
           ! find the minimum and maximum diagonal elements.
           s(1) = a(1,1)
           smin = s(1)
           amax = s(1)
           do i = 2,n
              s(i) = a(i,i)
              smin = min(smin,s(i))
              amax = max(amax,s(i))
           end do
           if (smin <= zero) then
              ! find the first non-positive diagonal element and return.
              do i = 1,n
                 if (s(i) <= zero) then
                    info = i
                    return
                 end if
              end do
           else
              ! set the scale factors to the reciprocals
              ! of the diagonal elements.
              do i = 1,n
                 s(i) = base**int(tmp*log(s(i)),KIND=ilp)
              end do
              ! compute scond = min(s(i)) / max(s(i)).
              scond = sqrt(smin)/sqrt(amax)
           end if
           return
     end subroutine la_qpoequb
#endif

     !> SPOTRS: solves a system of linear equations A*X = B with a symmetric
     !> positive definite matrix A using the Cholesky factorization
     !> A = U**T*U or A = L*L**T computed by SPOTRF.

     pure subroutine la_spotrs(uplo,n,nrhs,a,lda,b,ldb,info)
        use la_constants_sp
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: uplo
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: lda,ldb,n,nrhs
           ! Array Arguments
           real(sp),intent(in) :: a(lda,*)
           real(sp),intent(inout) :: b(ldb,*)
        ! =====================================================================

           ! Local Scalars
           logical(lk) :: upper
           ! Intrinsic Functions
           intrinsic :: max
           ! Executable Statements
           ! test the input parameters.
           info = 0
           upper = la_lsame(uplo,'U')
           if (.not. upper .and. .not. la_lsame(uplo,'L')) then
              info = -1
           else if (n < 0) then
              info = -2
           else if (nrhs < 0) then
              info = -3
           else if (lda < max(1,n)) then
              info = -5
           else if (ldb < max(1,n)) then
              info = -7
           end if
           if (info /= 0) then
              call la_xerbla('SPOTRS',-info)
              return
           end if
           ! quick return if possible
           if (n == 0 .or. nrhs == 0) return
           if (upper) then
              ! solve a*x = b where a = u**t *u.
              ! solve u**t *x = b, overwriting b with x.
              call la_strsm('LEFT','UPPER','TRANSPOSE','NON-UNIT',n,nrhs,one,a,lda,b, &
                         ldb)
              ! solve u*x = b, overwriting b with x.
              call la_strsm('LEFT','UPPER','NO TRANSPOSE','NON-UNIT',n,nrhs,one,a,lda, &
                         b,ldb)
           else
              ! solve a*x = b where a = l*l**t.
              ! solve l*x = b, overwriting b with x.
              call la_strsm('LEFT','LOWER','NO TRANSPOSE','NON-UNIT',n,nrhs,one,a,lda, &
                         b,ldb)
              ! solve l**t *x = b, overwriting b with x.
              call la_strsm('LEFT','LOWER','TRANSPOSE','NON-UNIT',n,nrhs,one,a,lda,b, &
                         ldb)
           end if
           return
     end subroutine la_spotrs
