     !> SLA_PORCOND: Estimates the Skeel condition number of  op(A) * op2(C)
     !> where op2 is determined by CMODE as follows
     !> CMODE =  1    op2(C) = C
     !> CMODE =  0    op2(C) = I
     !> CMODE = -1    op2(C) = inv(C)
     !> The Skeel condition number  cond(A) = norminf( |inv(A)||A| )
     !> is computed by computing scaling factors R such that
     !> diag(R)*A*op2(C) is row equilibrated and computing the standard
     !> infinity-norm condition number.

     real(sp) function la_sla_porcond(uplo,n,a,lda,af,ldaf,cmode,c,info,work,iwork)
        use la_constants_sp

        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: uplo
           integer(ilp),intent(in) :: n,lda,ldaf,cmode
           integer(ilp),intent(out) :: info
           real(sp),intent(in) :: a(lda,*),af(ldaf,*),c(*)
           real(sp),intent(out) :: work(*)
           ! Array Arguments
           integer(ilp),intent(out) :: iwork(*)
        ! =====================================================================
           ! Local Scalars
           integer(ilp) :: kase,i,j
           real(sp) :: ainvnm,tmp
           logical(lk) :: up
           ! Array Arguments
           integer(ilp) :: isave(3)
           ! Intrinsic Functions
           intrinsic :: abs,max
           ! Executable Statements
           la_sla_porcond = zero
           info = 0
           if (n < 0) then
              info = -2
           end if
           if (info /= 0) then
              call la_xerbla('SLA_PORCOND',-info)
              return
           end if
           if (n == 0) then
              la_sla_porcond = one
              return
           end if
           up = .false.
           if (la_lsame(uplo,'U')) up = .true.
           ! compute the equilibration matrix r such that
           ! inv(r)*a*c has unit 1-norm.
           if (up) then
              do i = 1,n
                 tmp = zero
                 if (cmode == 1) then
                    do j = 1,i
                       tmp = tmp + abs(a(j,i)*c(j))
                    end do
                    do j = i + 1,n
                       tmp = tmp + abs(a(i,j)*c(j))
                    end do
                 else if (cmode == 0) then
                    do j = 1,i
                       tmp = tmp + abs(a(j,i))
                    end do
                    do j = i + 1,n
                       tmp = tmp + abs(a(i,j))
                    end do
                 else
                    do j = 1,i
                       tmp = tmp + abs(a(j,i)/c(j))
                    end do
                    do j = i + 1,n
                       tmp = tmp + abs(a(i,j)/c(j))
                    end do
                 end if
                 work(2*n + i) = tmp
              end do
           else
              do i = 1,n
                 tmp = zero
                 if (cmode == 1) then
                    do j = 1,i
                       tmp = tmp + abs(a(i,j)*c(j))
                    end do
                    do j = i + 1,n
                       tmp = tmp + abs(a(j,i)*c(j))
                    end do
                 else if (cmode == 0) then
                    do j = 1,i
                       tmp = tmp + abs(a(i,j))
                    end do
                    do j = i + 1,n
                       tmp = tmp + abs(a(j,i))
                    end do
                 else
                    do j = 1,i
                       tmp = tmp + abs(a(i,j)/c(j))
                    end do
                    do j = i + 1,n
                       tmp = tmp + abs(a(j,i)/c(j))
                    end do
                 end if
                 work(2*n + i) = tmp
              end do
           end if
           ! estimate the norm of inv(op(a)).
           ainvnm = zero
           kase = 0
           10 continue
           call la_slacn2(n,work(n + 1),work,iwork,ainvnm,kase,isave)
           if (kase /= 0) then
              if (kase == 2) then
                 ! multiply by r.
                 do i = 1,n
                    work(i) = work(i)*work(2*n + i)
                 end do
                 if (up) then
                    call la_spotrs('UPPER',n,1,af,ldaf,work,n,info)
                 else
                    call la_spotrs('LOWER',n,1,af,ldaf,work,n,info)
                 end if
                 ! multiply by inv(c).
                 if (cmode == 1) then
                    do i = 1,n
                       work(i) = work(i)/c(i)
                    end do
                 else if (cmode == -1) then
                    do i = 1,n
                       work(i) = work(i)*c(i)
                    end do
                 end if
              else
                 ! multiply by inv(c**t).
                 if (cmode == 1) then
                    do i = 1,n
                       work(i) = work(i)/c(i)
                    end do
                 else if (cmode == -1) then
                    do i = 1,n
                       work(i) = work(i)*c(i)
                    end do
                 end if
                 if (up) then
                    call la_spotrs('UPPER',n,1,af,ldaf,work,n,info)
                 else
                    call la_spotrs('LOWER',n,1,af,ldaf,work,n,info)
                 end if
                 ! multiply by r.
                 do i = 1,n
                    work(i) = work(i)*work(2*n + i)
                 end do
              end if
              go to 10
           end if
           ! compute the estimate of the reciprocal condition number.
           if (ainvnm /= 0.0_sp) la_sla_porcond = (1.0_sp/ainvnm)
           return
     end function la_sla_porcond
