           if (la_lsame(uplo,'U')) up = .true.
           ! compute the equilibration matrix r such that
           ! inv(r)*a*c has unit 1-norm.
           if (up) then
              do i = 1,n
                 tmp = zero
                 if (cmode == 1) then
                    do j = 1,i
                       tmp = tmp + abs(a(j,i)*c(j))
                    end do
                    do j = i + 1,n
                       tmp = tmp + abs(a(i,j)*c(j))
                    end do
                 else if (cmode == 0) then
                    do j = 1,i
                       tmp = tmp + abs(a(j,i))
                    end do
                    do j = i + 1,n
                       tmp = tmp + abs(a(i,j))
                    end do
                 else
                    do j = 1,i
                       tmp = tmp + abs(a(j,i)/c(j))
                    end do
                    do j = i + 1,n
                       tmp = tmp + abs(a(i,j)/c(j))
                    end do
                 end if
                 work(2*n + i) = tmp
              end do
           else
              do i = 1,n
                 tmp = zero
                 if (cmode == 1) then
                    do j = 1,i
                       tmp = tmp + abs(a(i,j)*c(j))
                    end do
                    do j = i + 1,n
                       tmp = tmp + abs(a(j,i)*c(j))
                    end do
                 else if (cmode == 0) then
                    do j = 1,i
                       tmp = tmp + abs(a(i,j))
                    end do
                    do j = i + 1,n
                       tmp = tmp + abs(a(j,i))
                    end do
                 else
                    do j = 1,i
                       tmp = tmp + abs(a(i,j)/c(j))
                    end do
                    do j = i + 1,n
                       tmp = tmp + abs(a(j,i)/c(j))
                    end do
                 end if
                 work(2*n + i) = tmp
              end do
           end if
           ! estimate the norm of inv(op(a)).
           ainvnm = zero
           kase = 0
           10 continue
           call la_qlacn2(n,work(n + 1),work,iwork,ainvnm,kase,isave)
           if (kase /= 0) then
              if (kase == 2) then
                 ! multiply by r.
                 do i = 1,n
                    work(i) = work(i)*work(2*n + i)
                 end do
                 if (up) then
                    call la_qpotrs('UPPER',n,1,af,ldaf,work,n,info)
                 else
                    call la_qpotrs('LOWER',n,1,af,ldaf,work,n,info)
                 end if
                 ! multiply by inv(c).
                 if (cmode == 1) then
                    do i = 1,n
                       work(i) = work(i)/c(i)
                    end do
                 else if (cmode == -1) then
                    do i = 1,n
                       work(i) = work(i)*c(i)
                    end do
                 end if
              else
                 ! multiply by inv(c**t).
                 if (cmode == 1) then
                    do i = 1,n
                       work(i) = work(i)/c(i)
                    end do
                 else if (cmode == -1) then
                    do i = 1,n
                       work(i) = work(i)*c(i)
                    end do
                 end if
                 if (up) then
                    call la_qpotrs('UPPER',n,1,af,ldaf,work,n,info)
                 else
                    call la_qpotrs('LOWER',n,1,af,ldaf,work,n,info)
                 end if
                 ! multiply by r.
                 do i = 1,n
                    work(i) = work(i)*work(2*n + i)
                 end do
              end if
              go to 10
           end if
           ! compute the estimate of the reciprocal condition number.
           if (ainvnm /= zero) la_qla_porcond = (one/ainvnm)
           return
     end function la_qla_porcond
#endif

     !> SPBCON: estimates the reciprocal of the condition number (in the
     !> 1-norm) of a real symmetric positive definite band matrix using the
     !> Cholesky factorization A = U**T*U or A = L*L**T computed by SPBTRF.
     !> An estimate is obtained for norm(inv(A)), and the reciprocal of the
     !> condition number is computed as RCOND = 1 / (ANORM * norm(inv(A))).

     pure subroutine la_spbcon(uplo,n,kd,ab,ldab,anorm,rcond,work,iwork,info)
        use la_constants_sp,only:zero,one

        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: uplo
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: kd,ldab,n
           real(sp),intent(in) :: anorm
           real(sp),intent(out) :: rcond
           ! Array Arguments
           integer(ilp),intent(out) :: iwork(*)
           real(sp),intent(in) :: ab(ldab,*)
           real(sp),intent(out) :: work(*)
        ! =====================================================================

           ! Local Scalars
           logical(lk) :: upper
           character :: normin
           integer(ilp) :: ix,kase
           real(sp) :: ainvnm,scale,scalel,scaleu,smlnum
           ! Local Arrays
           integer(ilp) :: isave(3)
           ! Intrinsic Functions
           intrinsic :: abs
           ! Executable Statements
           ! test the input parameters.
           info = 0
           upper = la_lsame(uplo,'U')
           if (.not. upper .and. .not. la_lsame(uplo,'L')) then
              info = -1
           else if (n < 0) then
              info = -2
           else if (kd < 0) then
              info = -3
           else if (ldab < kd + 1) then
              info = -5
           else if (anorm < zero) then
              info = -6
           end if
           if (info /= 0) then
              call la_xerbla('SPBCON',-info)
              return
           end if
           ! quick return if possible
           rcond = zero
           if (n == 0) then
              rcond = one
              return
           else if (anorm == zero) then
              return
           end if
           smlnum = la_slamch('SAFE MINIMUM')
           ! estimate the 1-norm of the inverse.
           kase = 0
           normin = 'N'
           10 continue
           call la_slacn2(n,work(n + 1),work,iwork,ainvnm,kase,isave)
           if (kase /= 0) then
              if (upper) then
                 ! multiply by inv(u**t).
                 call la_slatbs('UPPER','TRANSPOSE','NON-UNIT',normin,n,kd,ab,ldab, &
                           work,scalel,work(2*n + 1),info)
                 normin = 'Y'
                 ! multiply by inv(u).
                 call la_slatbs('UPPER','NO TRANSPOSE','NON-UNIT',normin,n,kd,ab,ldab, &
                           work,scaleu,work(2*n + 1),info)
              else
                 ! multiply by inv(l).
                 call la_slatbs('LOWER','NO TRANSPOSE','NON-UNIT',normin,n,kd,ab,ldab, &
                           work,scalel,work(2*n + 1),info)
                 normin = 'Y'
                 ! multiply by inv(l**t).
                 call la_slatbs('LOWER','TRANSPOSE','NON-UNIT',normin,n,kd,ab,ldab, &
                           work,scaleu,work(2*n + 1),info)
              end if
              ! multiply by 1/scale if doing so will not cause overflow.
              scale = scalel*scaleu
              if (scale /= one) then
                 ix = la_isamax(n,work,1)
                 if (scale < abs(work(ix))*smlnum .or. scale == zero) go to 20
                 call la_srscl(n,scale,work,1)
              end if
              go to 10
           end if
           ! compute the estimate of the reciprocal condition number.
           if (ainvnm /= zero) rcond = (one/ainvnm)/anorm
           20 continue
           return
     end subroutine la_spbcon
