                           ),lda)
                 call la_spotrf2(uplo,n2,a(n1 + 1,n1 + 1),lda,iinfo)
                 if (iinfo /= 0) then
                    info = iinfo + n1
                    return
                 end if
              ! compute the cholesky factorization a = l*l**t
              else
                 ! update and scale a21
                 call la_strsm('R','L','T','N',n2,n1,one,a(1,1),lda,a(n1 + 1,1), &
                           lda)
                 ! update and factor a22
