              end if
              ! compute the cholesky factorization a = u**t*u
              if (upper) then
                 ! update and scale a12
                 call la_dtrsm('L','U','T','N',n1,n2,one,a(1,1),lda,a(1,n1 + 1), &
                           lda)
                 ! update and factor a22
                 call la_dsyrk(uplo,'T',n2,n1,-one,a(1,n1 + 1),lda,one,a(n1 + 1,n1 + 1 &
                           ),lda)
                 call la_dpotrf2(uplo,n2,a(n1 + 1,n1 + 1),lda,iinfo)
                 if (iinfo /= 0) then
                    info = iinfo + n1
                    return
                 end if
              ! compute the cholesky factorization a = l*l**t
              else
                 ! update and scale a21
                 call la_dtrsm('R','L','T','N',n2,n1,one,a(1,1),lda,a(n1 + 1,1), &
                           lda)
                 ! update and factor a22
                 call la_dsyrk(uplo,'N',n2,n1,-one,a(n1 + 1,1),lda,one,a(n1 + 1,n1 + 1 &
                           ),lda)
