     !> SPPCON: estimates the reciprocal of the condition number (in the
     !> 1-norm) of a real symmetric positive definite packed matrix using
     !> the Cholesky factorization A = U**T*U or A = L*L**T computed by
     !> SPPTRF.
     !> An estimate is obtained for norm(inv(A)), and the reciprocal of the
     !> condition number is computed as RCOND = 1 / (ANORM * norm(inv(A))).

     pure subroutine la_sppcon(uplo,n,ap,anorm,rcond,work,iwork,info)
        use la_constants_sp,only:zero,one
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: uplo
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: n
           real(sp),intent(in) :: anorm
           real(sp),intent(out) :: rcond
           ! Array Arguments
           integer(ilp),intent(out) :: iwork(*)
           real(sp),intent(in) :: ap(*)
           real(sp),intent(out) :: work(*)
        ! =====================================================================

           ! Local Scalars
           logical(lk) :: upper
           character :: normin
           integer(ilp) :: ix,kase
           real(sp) :: ainvnm,scale,scalel,scaleu,smlnum
           ! Local Arrays
           integer(ilp) :: isave(3)
           ! Intrinsic Functions
           intrinsic :: abs
           ! Executable Statements
           ! test the input parameters.
           info = 0
           upper = la_lsame(uplo,'U')
           if (.not. upper .and. .not. la_lsame(uplo,'L')) then
              info = -1
           else if (n < 0) then
              info = -2
           else if (anorm < zero) then
              info = -4
           end if
           if (info /= 0) then
              call la_xerbla('SPPCON',-info)
              return
           end if
           ! quick return if possible
           rcond = zero
           if (n == 0) then
              rcond = one
              return
           else if (anorm == zero) then
              return
           end if
           smlnum = la_slamch('SAFE MINIMUM')
           ! estimate the 1-norm of the inverse.
           kase = 0
           normin = 'N'
           10 continue
           call la_slacn2(n,work(n + 1),work,iwork,ainvnm,kase,isave)
           if (kase /= 0) then
              if (upper) then
                 ! multiply by inv(u**t).
                 call la_slatps('UPPER','TRANSPOSE','NON-UNIT',normin,n,ap,work,scalel, &
                            work(2*n + 1),info)
                 normin = 'Y'
                 ! multiply by inv(u).
                 call la_slatps('UPPER','NO TRANSPOSE','NON-UNIT',normin,n,ap,work, &
                           scaleu,work(2*n + 1),info)
              else
                 ! multiply by inv(l).
                 call la_slatps('LOWER','NO TRANSPOSE','NON-UNIT',normin,n,ap,work, &
                           scalel,work(2*n + 1),info)
                 normin = 'Y'
                 ! multiply by inv(l**t).
                 call la_slatps('LOWER','TRANSPOSE','NON-UNIT',normin,n,ap,work,scaleu, &
                            work(2*n + 1),info)
              end if
              ! multiply by 1/scale if doing so will not cause overflow.
              scale = scalel*scaleu
              if (scale /= one) then
                 ix = la_isamax(n,work,1)
                 if (scale < abs(work(ix))*smlnum .or. scale == zero) go to 20
                 call la_srscl(n,scale,work,1)
              end if
              go to 10
           end if
           ! compute the estimate of the reciprocal condition number.
           if (ainvnm /= zero) rcond = (one/ainvnm)/anorm
           20 continue
           return
     end subroutine la_sppcon
     !> DPPCON: estimates the reciprocal of the condition number (in the
     !> 1-norm) of a real symmetric positive definite packed matrix using
     !> the Cholesky factorization A = U**T*U or A = L*L**T computed by
     !> DPPTRF.
     !> An estimate is obtained for norm(inv(A)), and the reciprocal of the
     !> condition number is computed as RCOND = 1 / (ANORM * norm(inv(A))).

     pure subroutine la_dppcon(uplo,n,ap,anorm,rcond,work,iwork,info)
        use la_constants_dp,only:zero,one
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: uplo
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: n
           real(dp),intent(in) :: anorm
           real(dp),intent(out) :: rcond
           ! Array Arguments
           integer(ilp),intent(out) :: iwork(*)
           real(dp),intent(in) :: ap(*)
           real(dp),intent(out) :: work(*)
        ! =====================================================================

           ! Local Scalars
           logical(lk) :: upper
           character :: normin
           integer(ilp) :: ix,kase
           real(dp) :: ainvnm,scale,scalel,scaleu,smlnum
           ! Local Arrays
           integer(ilp) :: isave(3)
           ! Intrinsic Functions
           intrinsic :: abs
           ! Executable Statements
           ! test the input parameters.
           info = 0
