              info = -4
           end if
           if (info /= 0) then
              call la_xerbla('DPPCON',-info)
              return
           end if
           ! quick return if possible
           rcond = zero
           if (n == 0) then
              rcond = one
              return
           else if (anorm == zero) then
              return
           end if
           smlnum = la_dlamch('SAFE MINIMUM')
           ! estimate the 1-norm of the inverse.
           kase = 0
           normin = 'N'
           10 continue
           call la_dlacn2(n,work(n + 1),work,iwork,ainvnm,kase,isave)
           if (kase /= 0) then
              if (upper) then
                 ! multiply by inv(u**t).
                 call la_dlatps('UPPER','TRANSPOSE','NON-UNIT',normin,n,ap,work,scalel, &
                            work(2*n + 1),info)
                 normin = 'Y'
                 ! multiply by inv(u).
                 call la_dlatps('UPPER','NO TRANSPOSE','NON-UNIT',normin,n,ap,work, &
                           scaleu,work(2*n + 1),info)
              else
                 ! multiply by inv(l).
                 call la_dlatps('LOWER','NO TRANSPOSE','NON-UNIT',normin,n,ap,work, &
                           scalel,work(2*n + 1),info)
                 normin = 'Y'
                 ! multiply by inv(l**t).
