     !> SPPTRI: computes the inverse of a real symmetric positive definite
     !> matrix A using the Cholesky factorization A = U**T*U or A = L*L**T
     !> computed by SPPTRF.

     pure subroutine la_spptri(uplo,n,ap,info)
        use la_constants_sp
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: uplo
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: n
           ! Array Arguments
           real(sp),intent(inout) :: ap(*)
        ! =====================================================================

           ! Local Scalars
           logical(lk) :: upper
           integer(ilp) :: j,jc,jj,jjn
           real(sp) :: ajj
           ! Executable Statements
           ! test the input parameters.
           info = 0
           upper = la_lsame(uplo,'U')
           if (.not. upper .and. .not. la_lsame(uplo,'L')) then
              info = -1
           else if (n < 0) then
              info = -2
           end if
           if (info /= 0) then
              call la_xerbla('SPPTRI',-info)
              return
           end if
           ! quick return if possible
           if (n == 0) return
           ! invert the triangular cholesky factor u or l.
           call la_stptri(uplo,'NON-UNIT',n,ap,info)
           if (info > 0) return
           if (upper) then
              ! compute the product inv(u) * inv(u)**t.
              jj = 0
              do j = 1,n
                 jc = jj + 1
                 jj = jj + j
                 if (j > 1) call la_sspr('UPPER',j - 1,one,ap(jc),1,ap)
                 ajj = ap(jj)
                 call la_sscal(j,ajj,ap(jc),1)
              end do
           else
              ! compute the product inv(l)**t * inv(l).
              jj = 1
              do j = 1,n
                 jjn = jj + n - j + 1
                 ap(jj) = la_sdot(n - j + 1,ap(jj),1,ap(jj),1)
                 if (j < n) call la_stpmv('LOWER','TRANSPOSE','NON-UNIT',n - j,ap(jjn),ap( &
                           jj + 1),1)
                 jj = jjn
              end do
           end if
           return
     end subroutine la_spptri
     !> DPPTRI: computes the inverse of a real symmetric positive definite
     !> matrix A using the Cholesky factorization A = U**T*U or A = L*L**T
     !> computed by DPPTRF.

