              ! compute the product inv(l)**t * inv(l).
              jj = 1
              do j = 1,n
                 jjn = jj + n - j + 1
                 ap(jj) = la_qdot(n - j + 1,ap(jj),1,ap(jj),1)
                 if (j < n) call la_qtpmv('LOWER','TRANSPOSE','NON-UNIT',n - j,ap(jjn),ap( &
                           jj + 1),1)
                 jj = jjn
              end do
           end if
