     !> SPSTF2: computes the Cholesky factorization with complete
     !> pivoting of a real symmetric positive semidefinite matrix A.
     !> The factorization has the form
     !> P**T * A * P = U**T * U ,  if UPLO = 'U',
     !> P**T * A * P = L  * L**T,  if UPLO = 'L',
     !> where U is an upper triangular matrix and L is lower triangular, and
     !> P is stored as vector PIV.
     !> This algorithm does not attempt to check that A is positive
     !> semidefinite. This version of the algorithm calls level 2 BLAS.

     pure subroutine la_spstf2(uplo,n,a,lda,piv,rank,tol,work,info)
        use la_constants_sp
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           real(sp),intent(in) :: tol
           integer(ilp),intent(out) :: info,rank
           integer(ilp),intent(in) :: lda,n
           character,intent(in) :: uplo
           ! Array Arguments
           real(sp),intent(inout) :: a(lda,*)
           real(sp),intent(out) :: work(2*n)
           integer(ilp),intent(out) :: piv(n)
        ! =====================================================================

           ! Local Scalars
           real(sp) :: ajj,sstop,stemp
           integer(ilp) :: i,itemp,j,pvt
           logical(lk) :: upper
           ! Intrinsic Functions
           intrinsic :: max,sqrt,maxloc
           ! Executable Statements
           ! test the input parameters
           info = 0
           upper = la_lsame(uplo,'U')
           if (.not. upper .and. .not. la_lsame(uplo,'L')) then
              info = -1
           else if (n < 0) then
              info = -2
           else if (lda < max(1,n)) then
              info = -4
           end if
           if (info /= 0) then
              call la_xerbla('SPSTF2',-info)
              return
           end if
           ! quick return if possible
           if (n == 0) return
           ! initialize piv
           do i = 1,n
              piv(i) = i
           end do
           ! compute stopping value
           pvt = 1
           ajj = a(pvt,pvt)
           do i = 2,n
              if (a(i,i) > ajj) then
                 pvt = i
                 ajj = a(pvt,pvt)
              end if
           end do
           if (ajj <= zero .or. la_sisnan(ajj)) then
              rank = 0
              info = 1
              go to 170
           end if
           ! compute stopping value if not supplied
           if (tol < zero) then
              sstop = n*la_slamch('EPSILON')*ajj
           else
              sstop = tol
           end if
           ! set first half of work to zero, holds dot products
           do i = 1,n
              work(i) = 0
           end do
           if (upper) then
              ! compute the cholesky factorization p**t * a * p = u**t * u
              loop_130: do j = 1,n
              ! find pivot, test for exit, else swap rows and columns
              ! update dot products, compute possible pivots which are
              ! stored in the second half of work
                 do i = j,n
                    if (j > 1) then
                       work(i) = work(i) + a(j - 1,i)**2
                    end if
                    work(n + i) = a(i,i) - work(i)
                 end do
                 if (j > 1) then
                    itemp = maxloc(work((n + j):(2*n)),1)
                    pvt = itemp + j - 1
                    ajj = work(n + pvt)
                    if (ajj <= sstop .or. la_sisnan(ajj)) then
                       a(j,j) = ajj
                       go to 160
                    end if
                 end if
                 if (j /= pvt) then
                    ! pivot ok, so can now swap pivot rows and columns
                    a(pvt,pvt) = a(j,j)
                    call la_sswap(j - 1,a(1,j),1,a(1,pvt),1)
                    if (pvt < n) call la_sswap(n - pvt,a(j,pvt + 1),lda,a(pvt,pvt + 1),lda)

                    call la_sswap(pvt - j - 1,a(j,j + 1),lda,a(j + 1,pvt),1)
                    ! swap dot products and piv
                    stemp = work(j)
                    work(j) = work(pvt)
                    work(pvt) = stemp
                    itemp = piv(pvt)
                    piv(pvt) = piv(j)
                    piv(j) = itemp
                 end if
                 ajj = sqrt(ajj)
                 a(j,j) = ajj
                 ! compute elements j+1:n of row j
                 if (j < n) then
                    call la_sgemv('TRANS',j - 1,n - j,-one,a(1,j + 1),lda,a(1,j),1, &
                              one,a(j,j + 1),lda)
                    call la_sscal(n - j,one/ajj,a(j,j + 1),lda)
                 end if
              end do loop_130
           else
              ! compute the cholesky factorization p**t * a * p = l * l**t
              loop_150: do j = 1,n
              ! find pivot, test for exit, else swap rows and columns
              ! update dot products, compute possible pivots which are
              ! stored in the second half of work
                 do i = j,n
                    if (j > 1) then
                       work(i) = work(i) + a(i,j - 1)**2
                    end if
                    work(n + i) = a(i,i) - work(i)
                 end do
                 if (j > 1) then
                    itemp = maxloc(work((n + j):(2*n)),1)
                    pvt = itemp + j - 1
                    ajj = work(n + pvt)
                    if (ajj <= sstop .or. la_sisnan(ajj)) then
                       a(j,j) = ajj
                       go to 160
                    end if
                 end if
                 if (j /= pvt) then
                    ! pivot ok, so can now swap pivot rows and columns
                    a(pvt,pvt) = a(j,j)
                    call la_sswap(j - 1,a(j,1),lda,a(pvt,1),lda)
                    if (pvt < n) call la_sswap(n - pvt,a(pvt + 1,j),1,a(pvt + 1,pvt),1)

                    call la_sswap(pvt - j - 1,a(j + 1,j),1,a(pvt,j + 1),lda)
                    ! swap dot products and piv
                    stemp = work(j)
                    work(j) = work(pvt)
                    work(pvt) = stemp
                    itemp = piv(pvt)
                    piv(pvt) = piv(j)
                    piv(j) = itemp
                 end if
                 ajj = sqrt(ajj)
                 a(j,j) = ajj
                 ! compute elements j+1:n of column j
                 if (j < n) then
                    call la_sgemv('NO TRANS',n - j,j - 1,-one,a(j + 1,1),lda,a(j,1), &
                              lda,one,a(j + 1,j),1)
                    call la_sscal(n - j,one/ajj,a(j + 1,j),1)
                 end if
              end do loop_150
           end if
           ! ran to completion, a has full rank
           rank = n
           go to 170
           160 continue
           ! rank is number of steps completed.  set info = 1 to signal
           ! that the factorization cannot be used to solve a system.
           rank = j - 1
           info = 1
           170 continue
           return
     end subroutine la_spstf2
