                    if (j > 1) then
                       work(i) = work(i) + a(j - 1,i)**2
                    end if
                    work(n + i) = a(i,i) - work(i)
                 end do
                 if (j > 1) then
                    itemp = maxloc(work((n + j):(2*n)),1)
                    pvt = itemp + j - 1
                    ajj = work(n + pvt)
                    if (ajj <= qstop .or. la_qisnan(ajj)) then
                       a(j,j) = ajj
                       go to 160
                    end if
                 end if
                 if (j /= pvt) then
                    ! pivot ok, so can now swap pivot rows and columns
                    a(pvt,pvt) = a(j,j)
                    call la_qswap(j - 1,a(1,j),1,a(1,pvt),1)
                    if (pvt < n) call la_qswap(n - pvt,a(j,pvt + 1),lda,a(pvt,pvt + 1),lda)

                    call la_qswap(pvt - j - 1,a(j,j + 1),lda,a(j + 1,pvt),1)
                    ! swap dot products and piv
                    qtemp = work(j)
                    work(j) = work(pvt)
                    work(pvt) = qtemp
                    itemp = piv(pvt)
                    piv(pvt) = piv(j)
                    piv(j) = itemp
                 end if
                 ajj = sqrt(ajj)
                 a(j,j) = ajj
                 ! compute elements j+1:n of row j
                 if (j < n) then
                    call la_qgemv('TRANS',j - 1,n - j,-one,a(1,j + 1),lda,a(1,j),1, &
                              one,a(j,j + 1),lda)
                    call la_qscal(n - j,one/ajj,a(j,j + 1),lda)
                 end if
              end do loop_130
           else
              ! compute the cholesky factorization p**t * a * p = l * l**t
              loop_150: do j = 1,n
              ! find pivot, test for exit, else swap rows and columns
              ! update dot products, compute possible pivots which are
              ! stored in the second half of work
                 do i = j,n
                    if (j > 1) then
                       work(i) = work(i) + a(i,j - 1)**2
                    end if
                    work(n + i) = a(i,i) - work(i)
                 end do
                 if (j > 1) then
                    itemp = maxloc(work((n + j):(2*n)),1)
                    pvt = itemp + j - 1
                    ajj = work(n + pvt)
                    if (ajj <= qstop .or. la_qisnan(ajj)) then
                       a(j,j) = ajj
                       go to 160
                    end if
                 end if
                 if (j /= pvt) then
                    ! pivot ok, so can now swap pivot rows and columns
                    a(pvt,pvt) = a(j,j)
                    call la_qswap(j - 1,a(j,1),lda,a(pvt,1),lda)
                    if (pvt < n) call la_qswap(n - pvt,a(pvt + 1,j),1,a(pvt + 1,pvt),1)

                    call la_qswap(pvt - j - 1,a(j + 1,j),1,a(pvt,j + 1),lda)
                    ! swap dot products and piv
                    qtemp = work(j)
                    work(j) = work(pvt)
                    work(pvt) = qtemp
                    itemp = piv(pvt)
                    piv(pvt) = piv(j)
                    piv(j) = itemp
                 end if
                 ajj = sqrt(ajj)
                 a(j,j) = ajj
                 ! compute elements j+1:n of column j
                 if (j < n) then
                    call la_qgemv('NO TRANS',n - j,j - 1,-one,a(j + 1,1),lda,a(j,1), &
                              lda,one,a(j + 1,j),1)
                    call la_qscal(n - j,one/ajj,a(j + 1,j),1)
                 end if
              end do loop_150
           end if
           ! ran to completion, a has full rank
           rank = n
           go to 170
           160 continue
           ! rank is number of steps completed.  set info = 1 to signal
           ! that the factorization cannot be used to solve a system.
           rank = j - 1
           info = 1
           170 continue
           return
     end subroutine la_qpstf2
