                    ! stored in the second half of work
                       do i = j,n
                          if (j > k) then
                             work(i) = work(i) + a(j - 1,i)**2
                          end if
                          work(n + i) = a(i,i) - work(i)
                       end do
                       if (j > 1) then
                          itemp = maxloc(work((n + j):(2*n)),1)
                          pvt = itemp + j - 1
                          ajj = work(n + pvt)
                          if (ajj <= xstop .or. la_xisnan(ajj)) then
                             a(j,j) = ajj
                             go to 190
                          end if
                       end if
                       if (j /= pvt) then
                          ! pivot ok, so can now swap pivot rows and columns
                          a(pvt,pvt) = a(j,j)
                          call la_xswap(j - 1,a(1,j),1,a(1,pvt),1)
                          if (pvt < n) call la_xswap(n - pvt,a(j,pvt + 1),lda,a(pvt,pvt + 1), &
                                     lda)
                          call la_xswap(pvt - j - 1,a(j,j + 1),lda,a(j + 1,pvt),1)
                          ! swap dot products and piv
                          xtemp = work(j)
                          work(j) = work(pvt)
                          work(pvt) = xtemp
                          itemp = piv(pvt)
                          piv(pvt) = piv(j)
                          piv(j) = itemp
                       end if
                       ajj = sqrt(ajj)
                       a(j,j) = ajj
                       ! compute elements j+1:n of row j.
                       if (j < n) then
                          call la_xgemv('TRANS',j - k,n - j,-one,a(k,j + 1),lda,a(k,j), &
                                    1,one,a(j,j + 1),lda)
                          call la_xscal(n - j,one/ajj,a(j,j + 1),lda)
                       end if
                    end do loop_130
                    ! update trailing matrix, j already incremented
                    if (k + jb <= n) then
                       call la_xsyrk('UPPER','TRANS',n - j + 1,jb,-one,a(k,j),lda,one, &
                                 a(j,j),lda)
                    end if
                 end do loop_140
              else
              ! compute the cholesky factorization p**t * a * p = l * l**t
                 loop_180: do k = 1,n,nb
                    ! account for last block not being nb wide
                    jb = min(nb,n - k + 1)
                    ! set relevant part of first half of work to zero,
                    ! holds dot products
                    do i = k,n
                       work(i) = 0
                    end do
                    loop_170: do j = k,k + jb - 1
                    ! find pivot, test for exit, else swap rows and columns
                    ! update dot products, compute possible pivots which are
                    ! stored in the second half of work
                       do i = j,n
                          if (j > k) then
                             work(i) = work(i) + a(i,j - 1)**2
                          end if
                          work(n + i) = a(i,i) - work(i)
                       end do
                       if (j > 1) then
                          itemp = maxloc(work((n + j):(2*n)),1)
                          pvt = itemp + j - 1
                          ajj = work(n + pvt)
                          if (ajj <= xstop .or. la_xisnan(ajj)) then
                             a(j,j) = ajj
                             go to 190
                          end if
                       end if
                       if (j /= pvt) then
                          ! pivot ok, so can now swap pivot rows and columns
                          a(pvt,pvt) = a(j,j)
                          call la_xswap(j - 1,a(j,1),lda,a(pvt,1),lda)
                          if (pvt < n) call la_xswap(n - pvt,a(pvt + 1,j),1,a(pvt + 1,pvt), &
                                    1)
                          call la_xswap(pvt - j - 1,a(j + 1,j),1,a(pvt,j + 1),lda)
                          ! swap dot products and piv
                          xtemp = work(j)
                          work(j) = work(pvt)
                          work(pvt) = xtemp
                          itemp = piv(pvt)
                          piv(pvt) = piv(j)
                          piv(j) = itemp
                       end if
                       ajj = sqrt(ajj)
                       a(j,j) = ajj
                       ! compute elements j+1:n of column j.
                       if (j < n) then
                          call la_xgemv('NO TRANS',n - j,j - k,-one,a(j + 1,k),lda,a(j,k &
                                    ),lda,one,a(j + 1,j),1)
                          call la_xscal(n - j,one/ajj,a(j + 1,j),1)
                       end if
                    end do loop_170
                    ! update trailing matrix, j already incremented
                    if (k + jb <= n) then
                       call la_xsyrk('LOWER','NO TRANS',n - j + 1,jb,-one,a(j,k),lda, &
                                 one,a(j,j),lda)
                    end if
                 end do loop_180
              end if
           end if
           ! ran to completion, a has full rank
           rank = n
           go to 200
           190 continue
           ! rank is the number of steps completed.  set info = 1 to signal
           ! that the factorization cannot be used to solve a system.
           rank = j - 1
           info = 1
           200 continue
           return
     end subroutine la_xpstrf
