#ifdef LA_WITH_QP
     !> QPSTRF: computes the Cholesky factorization with complete
     !> pivoting of a real symmetric positive semidefinite matrix A.
     !> The factorization has the form
     !> P**T * A * P = U**T * U ,  if UPLO = 'U',
     !> P**T * A * P = L  * L**T,  if UPLO = 'L',
     !> where U is an upper triangular matrix and L is lower triangular, and
     !> P is stored as vector PIV.
     !> This algorithm does not attempt to check that A is positive
     !> semidefinite. This version of the algorithm calls level 3 BLAS.

     pure subroutine la_qpstrf(uplo,n,a,lda,piv,rank,tol,work,info)
        use la_constants_qp
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           real(qp),intent(in) :: tol
           integer(ilp),intent(out) :: info,rank
           integer(ilp),intent(in) :: lda,n
           character,intent(in) :: uplo
           ! Array Arguments
           real(qp),intent(inout) :: a(lda,*)
           real(qp),intent(out) :: work(2*n)
           integer(ilp),intent(out) :: piv(n)
        ! =====================================================================

           ! Local Scalars
           real(qp) :: ajj,qstop,qtemp
           integer(ilp) :: i,itemp,j,jb,k,nb,pvt
           logical(lk) :: upper
           ! Intrinsic Functions
           intrinsic :: max,min,sqrt,maxloc
           ! Executable Statements
           ! test the input parameters.
           info = 0
           upper = la_lsame(uplo,'U')
           if (.not. upper .and. .not. la_lsame(uplo,'L')) then
              info = -1
           else if (n < 0) then
              info = -2
           else if (lda < max(1,n)) then
              info = -4
           end if
           if (info /= 0) then
              call la_xerbla('QPSTRF',-info)
              return
           end if
           ! quick return if possible
           if (n == 0) return
           ! get block size
           nb = la_ilaenv(1,'QPOTRF',uplo,n,-1,-1,-1)
           if (nb <= 1 .or. nb >= n) then
              ! use unblocked code
              call la_qpstf2(uplo,n,a(1,1),lda,piv,rank,tol,work,info)
              go to 200
           else
           ! initialize piv
              do i = 1,n
                 piv(i) = i
              end do
           ! compute stopping value
              pvt = 1
              ajj = a(pvt,pvt)
              do i = 2,n
                 if (a(i,i) > ajj) then
                    pvt = i
                    ajj = a(pvt,pvt)
                 end if
              end do
              if (ajj <= zero .or. la_qisnan(ajj)) then
                 rank = 0
                 info = 1
                 go to 200
              end if
           ! compute stopping value if not supplied
              if (tol < zero) then
                 qstop = n*la_qlamch('EPSILON')*ajj
              else
                 qstop = tol
              end if
              if (upper) then
                 ! compute the cholesky factorization p**t * a * p = u**t * u
                 loop_140: do k = 1,n,nb
                    ! account for last block not being nb wide
                    jb = min(nb,n - k + 1)
                    ! set relevant part of first half of work to zero,
                    ! holds dot products
                    do i = k,n
                       work(i) = 0
                    end do
                    loop_130: do j = k,k + jb - 1
                    ! find pivot, test for exit, else swap rows and columns
                    ! update dot products, compute possible pivots which are
                    ! stored in the second half of work
                       do i = j,n
                          if (j > k) then
                             work(i) = work(i) + a(j - 1,i)**2
                          end if
                          work(n + i) = a(i,i) - work(i)
                       end do
                       if (j > 1) then
                          itemp = maxloc(work((n + j):(2*n)),1)
                          pvt = itemp + j - 1
                          ajj = work(n + pvt)
                          if (ajj <= qstop .or. la_qisnan(ajj)) then
                             a(j,j) = ajj
                             go to 190
                          end if
                       end if
                       if (j /= pvt) then
                          ! pivot ok, so can now swap pivot rows and columns
                          a(pvt,pvt) = a(j,j)
                          call la_qswap(j - 1,a(1,j),1,a(1,pvt),1)
                          if (pvt < n) call la_qswap(n - pvt,a(j,pvt + 1),lda,a(pvt,pvt + 1), &
                                     lda)
                          call la_qswap(pvt - j - 1,a(j,j + 1),lda,a(j + 1,pvt),1)
                          ! swap dot products and piv
                          qtemp = work(j)
                          work(j) = work(pvt)
                          work(pvt) = qtemp
                          itemp = piv(pvt)
                          piv(pvt) = piv(j)
                          piv(j) = itemp
                       end if
                       ajj = sqrt(ajj)
                       a(j,j) = ajj
                       ! compute elements j+1:n of row j.
                       if (j < n) then
                          call la_qgemv('TRANS',j - k,n - j,-one,a(k,j + 1),lda,a(k,j), &
                                    1,one,a(j,j + 1),lda)
                          call la_qscal(n - j,one/ajj,a(j,j + 1),lda)
                       end if
                    end do loop_130
                    ! update trailing matrix, j already incremented
                    if (k + jb <= n) then
                       call la_qsyrk('UPPER','TRANS',n - j + 1,jb,-one,a(k,j),lda,one, &
                                 a(j,j),lda)
                    end if
                 end do loop_140
              else
              ! compute the cholesky factorization p**t * a * p = l * l**t
                 loop_180: do k = 1,n,nb
                    ! account for last block not being nb wide
                    jb = min(nb,n - k + 1)
                    ! set relevant part of first half of work to zero,
                    ! holds dot products
                    do i = k,n
                       work(i) = 0
                    end do
                    loop_170: do j = k,k + jb - 1
                    ! find pivot, test for exit, else swap rows and columns
                    ! update dot products, compute possible pivots which are
                    ! stored in the second half of work
                       do i = j,n
                          if (j > k) then
                             work(i) = work(i) + a(i,j - 1)**2
                          end if
                          work(n + i) = a(i,i) - work(i)
                       end do
                       if (j > 1) then
                          itemp = maxloc(work((n + j):(2*n)),1)
                          pvt = itemp + j - 1
                          ajj = work(n + pvt)
                          if (ajj <= qstop .or. la_qisnan(ajj)) then
                             a(j,j) = ajj
                             go to 190
                          end if
                       end if
                       if (j /= pvt) then
                          ! pivot ok, so can now swap pivot rows and columns
                          a(pvt,pvt) = a(j,j)
                          call la_qswap(j - 1,a(j,1),lda,a(pvt,1),lda)
                          if (pvt < n) call la_qswap(n - pvt,a(pvt + 1,j),1,a(pvt + 1,pvt), &
                                    1)
                          call la_qswap(pvt - j - 1,a(j + 1,j),1,a(pvt,j + 1),lda)
                          ! swap dot products and piv
                          qtemp = work(j)
                          work(j) = work(pvt)
                          work(pvt) = qtemp
                          itemp = piv(pvt)
                          piv(pvt) = piv(j)
                          piv(j) = itemp
                       end if
                       ajj = sqrt(ajj)
                       a(j,j) = ajj
                       ! compute elements j+1:n of column j.
                       if (j < n) then
                          call la_qgemv('NO TRANS',n - j,j - k,-one,a(j + 1,k),lda,a(j,k &
                                    ),lda,one,a(j + 1,j),1)
                          call la_qscal(n - j,one/ajj,a(j + 1,j),1)
                       end if
                    end do loop_170
                    ! update trailing matrix, j already incremented
                    if (k + jb <= n) then
                       call la_qsyrk('LOWER','NO TRANS',n - j + 1,jb,-one,a(j,k),lda, &
                                 one,a(j,j),lda)
                    end if
                 end do loop_180
              end if
           end if
           ! ran to completion, a has full rank
           rank = n
           go to 200
           190 continue
           ! rank is the number of steps completed.  set info = 1 to signal
           ! that the factorization cannot be used to solve a system.
           rank = j - 1
           info = 1
           200 continue
           return
     end subroutine la_qpstrf
