     !> SPTTRS: solves a tridiagonal system of the form
     !> A * X = B
     !> using the L*D*L**T factorization of A computed by SPTTRF.  D is a
     !> diagonal matrix specified in the vector D, L is a unit bidiagonal
     !> matrix whose subdiagonal is specified in the vector E, and X and B
     !> are N by NRHS matrices.

     pure subroutine la_spttrs(n,nrhs,d,e,b,ldb,info)
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: ldb,n,nrhs
           ! Array Arguments
           real(sp),intent(inout) :: b(ldb,*)
           real(sp),intent(in) :: d(*),e(*)
        ! =====================================================================
           ! Local Scalars
           integer(ilp) :: j,jb,nb
           ! Intrinsic Functions
           intrinsic :: max,min
           ! Executable Statements
           ! test the input arguments.
           info = 0
           if (n < 0) then
              info = -1
           else if (nrhs < 0) then
              info = -2
           else if (ldb < max(1,n)) then
              info = -6
           end if
           if (info /= 0) then
              call la_xerbla('SPTTRS',-info)
              return
           end if
           ! quick return if possible
           if (n == 0 .or. nrhs == 0) return
           ! determine the number of right-hand sides to solve at a time.
           if (nrhs == 1) then
              nb = 1
           else
              nb = max(1,la_ilaenv(1,'SPTTRS',' ',n,nrhs,-1,-1))
           end if
           if (nb >= nrhs) then
              call la_sptts2(n,nrhs,d,e,b,ldb)
           else
              do j = 1,nrhs,nb
                 jb = min(nrhs - j + 1,nb)
                 call la_sptts2(n,jb,d,e,b(1,j),ldb)
              end do
           end if
           return
     end subroutine la_spttrs
