           ! the block size must not exceed the semi-bandwidth kd, and must not
           ! exceed the limit set by the size of the local array work.
           nb = min(nb,nbmax)
           if (nb <= 1 .or. nb > kd) then
              ! use unblocked code
              call la_qpbtf2(uplo,n,kd,ab,ldab,info)
           else
              ! use blocked code
              if (la_lsame(uplo,'U')) then
                 ! compute the cholesky factorization of a symmetric band
                 ! matrix, given the upper triangle of the matrix in band
                 ! storage.
                 ! zero the upper triangle of the work array.
                 do j = 1,nb
                    do i = 1,j - 1
                       work(i,j) = zero
                    end do
                 end do
                 ! process the band matrix one diagonal block at a time.
                 loop_70: do i = 1,n,nb
                    ib = min(nb,n - i + 1)
                    ! factorize the diagonal block
                    call la_qpotf2(uplo,ib,ab(kd + 1,i),ldab - 1,ii)
                    if (ii /= 0) then
                       info = i + ii - 1
                       go to 150
                    end if
                    if (i + ib <= n) then
                       ! update the relevant part of the trailing submatrix.
                       ! if a11 denotes the diagonal block which has just been
                       ! factorized, then we need to update the remaining
                       ! blocks in the diagram:
                          ! a11   a12   a13
                                ! a22   a23
                                      ! a33
                       ! the numbers of rows and columns in the partitioning
                       ! are ib, i2, i3 respectively. the blocks a12, a22 and
                       ! a23 are empty if ib = kd. the upper triangle of a13
                       ! lies outside the band.
                       i2 = min(kd - ib,n - i - ib + 1)
                       i3 = min(ib,n - i - kd + 1)
                       if (i2 > 0) then
                          ! update a12
                          call la_qtrsm('LEFT','UPPER','TRANSPOSE','NON-UNIT',ib,i2,one, &
                                     ab(kd + 1,i),ldab - 1,ab(kd + 1 - ib,i + ib),ldab - 1)
                          ! update a22
                          call la_qsyrk('UPPER','TRANSPOSE',i2,ib,-one,ab(kd + 1 - ib,i + ib &
                                    ),ldab - 1,one,ab(kd + 1,i + ib),ldab - 1)
                       end if
                       if (i3 > 0) then
                          ! copy the lower triangle of a13 into the work array.
                          do jj = 1,i3
                             do ii = jj,ib
                                work(ii,jj) = ab(ii - jj + 1,jj + i + kd - 1)
                             end do
                          end do
                          ! update a13 (in the work array).
                          call la_qtrsm('LEFT','UPPER','TRANSPOSE','NON-UNIT',ib,i3,one, &
                                     ab(kd + 1,i),ldab - 1,work,ldwork)
                          ! update a23
                          if (i2 > 0) call la_qgemm('TRANSPOSE','NO TRANSPOSE',i2,i3,ib,- &
                          one,ab(kd + 1 - ib,i + ib),ldab - 1,work,ldwork,one,ab(1 + ib,i + kd), &
                                    ldab - 1)
                          ! update a33
                          call la_qsyrk('UPPER','TRANSPOSE',i3,ib,-one,work,ldwork,one, &
                                     ab(kd + 1,i + kd),ldab - 1)
                          ! copy the lower triangle of a13 back into place.
                          do jj = 1,i3
                             do ii = jj,ib
                                ab(ii - jj + 1,jj + i + kd - 1) = work(ii,jj)
                             end do
                          end do
                       end if
                    end if
                 end do loop_70
              else
                 ! compute the cholesky factorization of a symmetric band
                 ! matrix, given the lower triangle of the matrix in band
                 ! storage.
                 ! zero the lower triangle of the work array.
                 do j = 1,nb
                    do i = j + 1,nb
                       work(i,j) = zero
                    end do
                 end do
                 ! process the band matrix one diagonal block at a time.
                 loop_140: do i = 1,n,nb
                    ib = min(nb,n - i + 1)
                    ! factorize the diagonal block
                    call la_qpotf2(uplo,ib,ab(1,i),ldab - 1,ii)
                    if (ii /= 0) then
                       info = i + ii - 1
                       go to 150
                    end if
                    if (i + ib <= n) then
                       ! update the relevant part of the trailing submatrix.
                       ! if a11 denotes the diagonal block which has just been
                       ! factorized, then we need to update the remaining
                       ! blocks in the diagram:
                          ! a11
                          ! a21   a22
                          ! a31   a32   a33
                       ! the numbers of rows and columns in the partitioning
                       ! are ib, i2, i3 respectively. the blocks a21, a22 and
                       ! a32 are empty if ib = kd. the lower triangle of a31
                       ! lies outside the band.
                       i2 = min(kd - ib,n - i - ib + 1)
                       i3 = min(ib,n - i - kd + 1)
                       if (i2 > 0) then
                          ! update a21
                          call la_qtrsm('RIGHT','LOWER','TRANSPOSE','NON-UNIT',i2,ib, &
                                    one,ab(1,i),ldab - 1,ab(1 + ib,i),ldab - 1)
                          ! update a22
                          call la_qsyrk('LOWER','NO TRANSPOSE',i2,ib,-one,ab(1 + ib,i), &
                                    ldab - 1,one,ab(1,i + ib),ldab - 1)
                       end if
                       if (i3 > 0) then
                          ! copy the upper triangle of a31 into the work array.
                          do jj = 1,ib
                             do ii = 1,min(jj,i3)
                                work(ii,jj) = ab(kd + 1 - jj + ii,jj + i - 1)
                             end do
                          end do
                          ! update a31 (in the work array).
                          call la_qtrsm('RIGHT','LOWER','TRANSPOSE','NON-UNIT',i3,ib, &
                                    one,ab(1,i),ldab - 1,work,ldwork)
                          ! update a32
                          if (i2 > 0) call la_qgemm('NO TRANSPOSE','TRANSPOSE',i3,i2,ib,- &
                          one,work,ldwork,ab(1 + ib,i),ldab - 1,one,ab(1 + kd - ib,i + ib),ldab - &
                                    1)
                          ! update a33
                          call la_qsyrk('LOWER','NO TRANSPOSE',i3,ib,-one,work,ldwork, &
                                    one,ab(1,i + kd),ldab - 1)
                          ! copy the upper triangle of a31 back into place.
                          do jj = 1,ib
                             do ii = 1,min(jj,i3)
                                ab(kd + 1 - jj + ii,jj + i - 1) = work(ii,jj)
                             end do
                          end do
                       end if
                    end if
                 end do loop_140
              end if
           end if
           return
           150 continue
           return
     end subroutine la_qpbtrf
#endif

     !> SPFTRI: computes the inverse of a real (symmetric) positive definite
     !> matrix A using the Cholesky factorization A = U**T*U or A = L*L**T
     !> computed by SPFTRF.

     pure subroutine la_spftri(transr,uplo,n,a,info)
        use la_constants_sp
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: transr,uplo
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: n
           ! Array Arguments
           real(sp),intent(inout) :: a(0:*)
        ! =====================================================================

           ! Local Scalars
           logical(lk) :: lower,nisodd,normaltransr
           integer(ilp) :: n1,n2,k
           ! Intrinsic Functions
           intrinsic :: mod
           ! Executable Statements
           ! test the input parameters.
           info = 0
           normaltransr = la_lsame(transr,'N')
           lower = la_lsame(uplo,'L')
           if (.not. normaltransr .and. .not. la_lsame(transr,'T')) then
              info = -1
           else if (.not. lower .and. .not. la_lsame(uplo,'U')) then
              info = -2
           else if (n < 0) then
              info = -3
           end if
           if (info /= 0) then
              call la_xerbla('SPFTRI',-info)
              return
           end if
           ! quick return if possible
           if (n == 0) return
           ! invert the triangular cholesky factor u or l.
           call la_stftri(transr,uplo,'N',n,a,info)
           if (info > 0) return
           ! if n is odd, set nisodd = .true.
           ! if n is even, set k = n/2 and nisodd = .false.
           if (mod(n,2) == 0) then
              k = n/2
              nisodd = .false.
           else
              nisodd = .true.
           end if
           ! set n1 and n2 depending on lower
           if (lower) then
              n2 = n/2
              n1 = n - n2
           else
              n1 = n/2
              n2 = n - n1
           end if
           ! start execution of triangular matrix multiply: inv(u)*inv(u)^c or
           ! inv(l)^c*inv(l). there are eight cases.
           if (nisodd) then
              ! n is odd
              if (normaltransr) then
                 ! n is odd and transr = 'n'
                 if (lower) then
                    ! srpa for lower, normal and n is odd ( a(0:n-1,0:n1-1) )
                    ! t1 -> a(0,0), t2 -> a(0,1), s -> a(n1,0)
                    ! t1 -> a(0), t2 -> a(n), s -> a(n1)
                    call la_slauum('L',n1,a(0),n,info)
                    call la_ssyrk('L','T',n1,n2,one,a(n1),n,one,a(0),n)
                    call la_strmm('L','U','N','N',n2,n1,one,a(n),n,a(n1),n)

                    call la_slauum('U',n2,a(n),n,info)
                 else
                    ! srpa for upper, normal and n is odd ( a(0:n-1,0:n2-1)
                    ! t1 -> a(n1+1,0), t2 -> a(n1,0), s -> a(0,0)
                    ! t1 -> a(n2), t2 -> a(n1), s -> a(0)
                    call la_slauum('L',n1,a(n2),n,info)
                    call la_ssyrk('L','N',n1,n2,one,a(0),n,one,a(n2),n)
                    call la_strmm('R','U','T','N',n1,n2,one,a(n1),n,a(0),n)

                    call la_slauum('U',n2,a(n1),n,info)
                 end if
              else
                 ! n is odd and transr = 't'
                 if (lower) then
                    ! srpa for lower, transpose, and n is odd
                    ! t1 -> a(0), t2 -> a(1), s -> a(0+n1*n1)
                    call la_slauum('U',n1,a(0),n1,info)
                    call la_ssyrk('U','N',n1,n2,one,a(n1*n1),n1,one,a(0),n1)

                    call la_strmm('R','L','N','N',n1,n2,one,a(1),n1,a(n1*n1),n1 &
                              )
                    call la_slauum('L',n2,a(1),n1,info)
                 else
                    ! srpa for upper, transpose, and n is odd
                    ! t1 -> a(0+n2*n2), t2 -> a(0+n1*n2), s -> a(0)
                    call la_slauum('U',n1,a(n2*n2),n2,info)
                    call la_ssyrk('U','T',n1,n2,one,a(0),n2,one,a(n2*n2),n2)

                    call la_strmm('L','L','T','N',n2,n1,one,a(n1*n2),n2,a(0),n2 &
                              )
                    call la_slauum('L',n2,a(n1*n2),n2,info)
                 end if
              end if
           else
              ! n is even
              if (normaltransr) then
                 ! n is even and transr = 'n'
                 if (lower) then
                    ! srpa for lower, normal, and n is even ( a(0:n,0:k-1) )
                    ! t1 -> a(1,0), t2 -> a(0,0), s -> a(k+1,0)
                    ! t1 -> a(1), t2 -> a(0), s -> a(k+1)
                    call la_slauum('L',k,a(1),n + 1,info)
                    call la_ssyrk('L','T',k,k,one,a(k + 1),n + 1,one,a(1),n + 1)

                    call la_strmm('L','U','N','N',k,k,one,a(0),n + 1,a(k + 1),n + 1)

                    call la_slauum('U',k,a(0),n + 1,info)
                 else
                    ! srpa for upper, normal, and n is even ( a(0:n,0:k-1) )
                    ! t1 -> a(k+1,0) ,  t2 -> a(k,0),   s -> a(0,0)
                    ! t1 -> a(k+1), t2 -> a(k), s -> a(0)
                    call la_slauum('L',k,a(k + 1),n + 1,info)
                    call la_ssyrk('L','N',k,k,one,a(0),n + 1,one,a(k + 1),n + 1)

                    call la_strmm('R','U','T','N',k,k,one,a(k),n + 1,a(0),n + 1)

                    call la_slauum('U',k,a(k),n + 1,info)
                 end if
              else
                 ! n is even and transr = 't'
                 if (lower) then
                    ! srpa for lower, transpose, and n is even (see paper)
                    ! t1 -> b(0,1), t2 -> b(0,0), s -> b(0,k+1),
                    ! t1 -> a(0+k), t2 -> a(0+0), s -> a(0+k*(k+1)); lda=k
                    call la_slauum('U',k,a(k),k,info)
                    call la_ssyrk('U','N',k,k,one,a(k*(k + 1)),k,one,a(k),k)

                    call la_strmm('R','L','N','N',k,k,one,a(0),k,a(k*(k + 1)),k &
                              )
                    call la_slauum('L',k,a(0),k,info)
                 else
                    ! srpa for upper, transpose, and n is even (see paper)
                    ! t1 -> b(0,k+1),     t2 -> b(0,k),   s -> b(0,0),
                    ! t1 -> a(0+k*(k+1)), t2 -> a(0+k*k), s -> a(0+0)); lda=k
                    call la_slauum('U',k,a(k*(k + 1)),k,info)
                    call la_ssyrk('U','T',k,k,one,a(0),k,one,a(k*(k + 1)),k)

                    call la_strmm('L','L','T','N',k,k,one,a(k*k),k,a(0),k)

                    call la_slauum('L',k,a(k*k),k,info)
                 end if
              end if
           end if
           return
     end subroutine la_spftri
     !> DPFTRI: computes the inverse of a (real) symmetric positive definite
     !> matrix A using the Cholesky factorization A = U**T*U or A = L*L**T
     !> computed by DPFTRF.

     pure subroutine la_dpftri(transr,uplo,n,a,info)
        use la_constants_dp
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: transr,uplo
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: n
           ! Array Arguments
           real(dp),intent(inout) :: a(0:*)
        ! =====================================================================

           ! Local Scalars
           logical(lk) :: lower,nisodd,normaltransr
           integer(ilp) :: n1,n2,k
           ! Intrinsic Functions
           intrinsic :: mod
           ! Executable Statements
           ! test the input parameters.
           info = 0
           normaltransr = la_lsame(transr,'N')
           lower = la_lsame(uplo,'L')
           if (.not. normaltransr .and. .not. la_lsame(transr,'T')) then
              info = -1
           else if (.not. lower .and. .not. la_lsame(uplo,'U')) then
              info = -2
           else if (n < 0) then
              info = -3
           end if
           if (info /= 0) then
              call la_xerbla('DPFTRI',-info)
              return
           end if
           ! quick return if possible
           if (n == 0) return
           ! invert the triangular cholesky factor u or l.
           call la_dtftri(transr,uplo,'N',n,a,info)
           if (info > 0) return
           ! if n is odd, set nisodd = .true.
           ! if n is even, set k = n/2 and nisodd = .false.
           if (mod(n,2) == 0) then
              k = n/2
              nisodd = .false.
           else
              nisodd = .true.
           end if
           ! set n1 and n2 depending on lower
           if (lower) then
              n2 = n/2
              n1 = n - n2
           else
              n1 = n/2
              n2 = n - n1
           end if
           ! start execution of triangular matrix multiply: inv(u)*inv(u)^c or
           ! inv(l)^c*inv(l). there are eight cases.
           if (nisodd) then
              ! n is odd
              if (normaltransr) then
                 ! n is odd and transr = 'n'
                 if (lower) then
                    ! srpa for lower, normal and n is odd ( a(0:n-1,0:n1-1) )
                    ! t1 -> a(0,0), t2 -> a(0,1), s -> a(n1,0)
                    ! t1 -> a(0), t2 -> a(n), s -> a(n1)
                    call la_dlauum('L',n1,a(0),n,info)
                    call la_dsyrk('L','T',n1,n2,one,a(n1),n,one,a(0),n)
                    call la_dtrmm('L','U','N','N',n2,n1,one,a(n),n,a(n1),n)

                    call la_dlauum('U',n2,a(n),n,info)
                 else
                    ! srpa for upper, normal and n is odd ( a(0:n-1,0:n2-1)
                    ! t1 -> a(n1+1,0), t2 -> a(n1,0), s -> a(0,0)
                    ! t1 -> a(n2), t2 -> a(n1), s -> a(0)
                    call la_dlauum('L',n1,a(n2),n,info)
                    call la_dsyrk('L','N',n1,n2,one,a(0),n,one,a(n2),n)
                    call la_dtrmm('R','U','T','N',n1,n2,one,a(n1),n,a(0),n)

                    call la_dlauum('U',n2,a(n1),n,info)
                 end if
              else
                 ! n is odd and transr = 't'
                 if (lower) then
                    ! srpa for lower, transpose, and n is odd
                    ! t1 -> a(0), t2 -> a(1), s -> a(0+n1*n1)
                    call la_dlauum('U',n1,a(0),n1,info)
                    call la_dsyrk('U','N',n1,n2,one,a(n1*n1),n1,one,a(0),n1)

                    call la_dtrmm('R','L','N','N',n1,n2,one,a(1),n1,a(n1*n1),n1 &
                              )
                    call la_dlauum('L',n2,a(1),n1,info)
                 else
                    ! srpa for upper, transpose, and n is odd
                    ! t1 -> a(0+n2*n2), t2 -> a(0+n1*n2), s -> a(0)
                    call la_dlauum('U',n1,a(n2*n2),n2,info)
                    call la_dsyrk('U','T',n1,n2,one,a(0),n2,one,a(n2*n2),n2)

                    call la_dtrmm('L','L','T','N',n2,n1,one,a(n1*n2),n2,a(0),n2 &
                              )
                    call la_dlauum('L',n2,a(n1*n2),n2,info)
                 end if
              end if
           else
              ! n is even
              if (normaltransr) then
                 ! n is even and transr = 'n'
                 if (lower) then
                    ! srpa for lower, normal, and n is even ( a(0:n,0:k-1) )
                    ! t1 -> a(1,0), t2 -> a(0,0), s -> a(k+1,0)
                    ! t1 -> a(1), t2 -> a(0), s -> a(k+1)
                    call la_dlauum('L',k,a(1),n + 1,info)
                    call la_dsyrk('L','T',k,k,one,a(k + 1),n + 1,one,a(1),n + 1)

                    call la_dtrmm('L','U','N','N',k,k,one,a(0),n + 1,a(k + 1),n + 1)

                    call la_dlauum('U',k,a(0),n + 1,info)
                 else
                    ! srpa for upper, normal, and n is even ( a(0:n,0:k-1) )
                    ! t1 -> a(k+1,0) ,  t2 -> a(k,0),   s -> a(0,0)
                    ! t1 -> a(k+1), t2 -> a(k), s -> a(0)
                    call la_dlauum('L',k,a(k + 1),n + 1,info)
                    call la_dsyrk('L','N',k,k,one,a(0),n + 1,one,a(k + 1),n + 1)

                    call la_dtrmm('R','U','T','N',k,k,one,a(k),n + 1,a(0),n + 1)

                    call la_dlauum('U',k,a(k),n + 1,info)
                 end if
              else
                 ! n is even and transr = 't'
                 if (lower) then
                    ! srpa for lower, transpose, and n is even (see paper)
                    ! t1 -> b(0,1), t2 -> b(0,0), s -> b(0,k+1),
                    ! t1 -> a(0+k), t2 -> a(0+0), s -> a(0+k*(k+1)); lda=k
                    call la_dlauum('U',k,a(k),k,info)
                    call la_dsyrk('U','N',k,k,one,a(k*(k + 1)),k,one,a(k),k)

                    call la_dtrmm('R','L','N','N',k,k,one,a(0),k,a(k*(k + 1)),k &
                              )
                    call la_dlauum('L',k,a(0),k,info)
                 else
                    ! srpa for upper, transpose, and n is even (see paper)
                    ! t1 -> b(0,k+1),     t2 -> b(0,k),   s -> b(0,0),
                    ! t1 -> a(0+k*(k+1)), t2 -> a(0+k*k), s -> a(0+0)); lda=k
                    call la_dlauum('U',k,a(k*(k + 1)),k,info)
                    call la_dsyrk('U','T',k,k,one,a(0),k,one,a(k*(k + 1)),k)

                    call la_dtrmm('L','L','T','N',k,k,one,a(k*k),k,a(0),k)

                    call la_dlauum('L',k,a(k*k),k,info)
                 end if
              end if
           end if
           return
     end subroutine la_dpftri
#ifdef LA_WITH_XDP
