           ! start execution of triangular matrix multiply: inv(u)*inv(u)^c or
           ! inv(l)^c*inv(l). there are eight cases.
           if (nisodd) then
              ! n is odd
              if (normaltransr) then
                 ! n is odd and transr = 'n'
                 if (lower) then
                    ! srpa for lower, normal and n is odd ( a(0:n-1,0:n1-1) )
                    ! t1 -> a(0,0), t2 -> a(0,1), s -> a(n1,0)
                    ! t1 -> a(0), t2 -> a(n), s -> a(n1)
                    call la_xlauum('L',n1,a(0),n,info)
                    call la_xsyrk('L','T',n1,n2,one,a(n1),n,one,a(0),n)
                    call la_xtrmm('L','U','N','N',n2,n1,one,a(n),n,a(n1),n)

                    call la_xlauum('U',n2,a(n),n,info)
                 else
                    ! srpa for upper, normal and n is odd ( a(0:n-1,0:n2-1)
                    ! t1 -> a(n1+1,0), t2 -> a(n1,0), s -> a(0,0)
                    ! t1 -> a(n2), t2 -> a(n1), s -> a(0)
                    call la_xlauum('L',n1,a(n2),n,info)
                    call la_xsyrk('L','N',n1,n2,one,a(0),n,one,a(n2),n)
                    call la_xtrmm('R','U','T','N',n1,n2,one,a(n1),n,a(0),n)

                    call la_xlauum('U',n2,a(n1),n,info)
                 end if
              else
                 ! n is odd and transr = 't'
                 if (lower) then
                    ! srpa for lower, transpose, and n is odd
                    ! t1 -> a(0), t2 -> a(1), s -> a(0+n1*n1)
                    call la_xlauum('U',n1,a(0),n1,info)
                    call la_xsyrk('U','N',n1,n2,one,a(n1*n1),n1,one,a(0),n1)

                    call la_xtrmm('R','L','N','N',n1,n2,one,a(1),n1,a(n1*n1),n1 &
                              )
                    call la_xlauum('L',n2,a(1),n1,info)
                 else
                    ! srpa for upper, transpose, and n is odd
                    ! t1 -> a(0+n2*n2), t2 -> a(0+n1*n2), s -> a(0)
                    call la_xlauum('U',n1,a(n2*n2),n2,info)
                    call la_xsyrk('U','T',n1,n2,one,a(0),n2,one,a(n2*n2),n2)

                    call la_xtrmm('L','L','T','N',n2,n1,one,a(n1*n2),n2,a(0),n2 &
                              )
                    call la_xlauum('L',n2,a(n1*n2),n2,info)
                 end if
              end if
           else
              ! n is even
              if (normaltransr) then
                 ! n is even and transr = 'n'
                 if (lower) then
                    ! srpa for lower, normal, and n is even ( a(0:n,0:k-1) )
                    ! t1 -> a(1,0), t2 -> a(0,0), s -> a(k+1,0)
                    ! t1 -> a(1), t2 -> a(0), s -> a(k+1)
                    call la_xlauum('L',k,a(1),n + 1,info)
                    call la_xsyrk('L','T',k,k,one,a(k + 1),n + 1,one,a(1),n + 1)

                    call la_xtrmm('L','U','N','N',k,k,one,a(0),n + 1,a(k + 1),n + 1)

                    call la_xlauum('U',k,a(0),n + 1,info)
                 else
                    ! srpa for upper, normal, and n is even ( a(0:n,0:k-1) )
                    ! t1 -> a(k+1,0) ,  t2 -> a(k,0),   s -> a(0,0)
                    ! t1 -> a(k+1), t2 -> a(k), s -> a(0)
                    call la_xlauum('L',k,a(k + 1),n + 1,info)
                    call la_xsyrk('L','N',k,k,one,a(0),n + 1,one,a(k + 1),n + 1)

                    call la_xtrmm('R','U','T','N',k,k,one,a(k),n + 1,a(0),n + 1)

                    call la_xlauum('U',k,a(k),n + 1,info)
                 end if
              else
                 ! n is even and transr = 't'
                 if (lower) then
                    ! srpa for lower, transpose, and n is even (see paper)
                    ! t1 -> b(0,1), t2 -> b(0,0), s -> b(0,k+1),
                    ! t1 -> a(0+k), t2 -> a(0+0), s -> a(0+k*(k+1)); lda=k
                    call la_xlauum('U',k,a(k),k,info)
                    call la_xsyrk('U','N',k,k,one,a(k*(k + 1)),k,one,a(k),k)

                    call la_xtrmm('R','L','N','N',k,k,one,a(0),k,a(k*(k + 1)),k &
                              )
                    call la_xlauum('L',k,a(0),k,info)
                 else
                    ! srpa for upper, transpose, and n is even (see paper)
                    ! t1 -> b(0,k+1),     t2 -> b(0,k),   s -> b(0,0),
                    ! t1 -> a(0+k*(k+1)), t2 -> a(0+k*k), s -> a(0+0)); lda=k
                    call la_xlauum('U',k,a(k*(k + 1)),k,info)
                    call la_xsyrk('U','T',k,k,one,a(0),k,one,a(k*(k + 1)),k)

                    call la_xtrmm('L','L','T','N',k,k,one,a(k*k),k,a(0),k)

                    call la_xlauum('L',k,a(k*k),k,info)
                 end if
              end if
           end if
           return
     end subroutine la_xpftri
#endif
#ifdef LA_WITH_QP
     !> QPFTRI: computes the inverse of a (real) symmetric positive definite
     !> matrix A using the Cholesky factorization A = U**T*U or A = L*L**T
     !> computed by QPFTRF.

     pure subroutine la_qpftri(transr,uplo,n,a,info)
        use la_constants_qp
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: transr,uplo
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: n
           ! Array Arguments
           real(qp),intent(inout) :: a(0:*)
        ! =====================================================================

           ! Local Scalars
           logical(lk) :: lower,nisodd,normaltransr
           integer(ilp) :: n1,n2,k
           ! Intrinsic Functions
           intrinsic :: mod
           ! Executable Statements
           ! test the input parameters.
           info = 0
           normaltransr = la_lsame(transr,'N')
           lower = la_lsame(uplo,'L')
           if (.not. normaltransr .and. .not. la_lsame(transr,'T')) then
              info = -1
           else if (.not. lower .and. .not. la_lsame(uplo,'U')) then
              info = -2
           else if (n < 0) then
              info = -3
           end if
           if (info /= 0) then
              call la_xerbla('QPFTRI',-info)
              return
           end if
           ! quick return if possible
           if (n == 0) return
           ! invert the triangular cholesky factor u or l.
           call la_qtftri(transr,uplo,'N',n,a,info)
           if (info > 0) return
           ! if n is odd, set nisodd = .true.
           ! if n is even, set k = n/2 and nisodd = .false.
           if (mod(n,2) == 0) then
              k = n/2
              nisodd = .false.
           else
              nisodd = .true.
           end if
           ! set n1 and n2 depending on lower
           if (lower) then
              n2 = n/2
              n1 = n - n2
           else
              n1 = n/2
              n2 = n - n1
           end if
           ! start execution of triangular matrix multiply: inv(u)*inv(u)^c or
           ! inv(l)^c*inv(l). there are eight cases.
           if (nisodd) then
              ! n is odd
              if (normaltransr) then
                 ! n is odd and transr = 'n'
                 if (lower) then
                    ! srpa for lower, normal and n is odd ( a(0:n-1,0:n1-1) )
                    ! t1 -> a(0,0), t2 -> a(0,1), s -> a(n1,0)
                    ! t1 -> a(0), t2 -> a(n), s -> a(n1)
                    call la_qlauum('L',n1,a(0),n,info)
                    call la_qsyrk('L','T',n1,n2,one,a(n1),n,one,a(0),n)
                    call la_qtrmm('L','U','N','N',n2,n1,one,a(n),n,a(n1),n)

                    call la_qlauum('U',n2,a(n),n,info)
                 else
                    ! srpa for upper, normal and n is odd ( a(0:n-1,0:n2-1)
                    ! t1 -> a(n1+1,0), t2 -> a(n1,0), s -> a(0,0)
                    ! t1 -> a(n2), t2 -> a(n1), s -> a(0)
                    call la_qlauum('L',n1,a(n2),n,info)
                    call la_qsyrk('L','N',n1,n2,one,a(0),n,one,a(n2),n)
                    call la_qtrmm('R','U','T','N',n1,n2,one,a(n1),n,a(0),n)

                    call la_qlauum('U',n2,a(n1),n,info)
                 end if
              else
                 ! n is odd and transr = 't'
                 if (lower) then
                    ! srpa for lower, transpose, and n is odd
                    ! t1 -> a(0), t2 -> a(1), s -> a(0+n1*n1)
                    call la_qlauum('U',n1,a(0),n1,info)
                    call la_qsyrk('U','N',n1,n2,one,a(n1*n1),n1,one,a(0),n1)

                    call la_qtrmm('R','L','N','N',n1,n2,one,a(1),n1,a(n1*n1),n1 &
                              )
                    call la_qlauum('L',n2,a(1),n1,info)
                 else
                    ! srpa for upper, transpose, and n is odd
                    ! t1 -> a(0+n2*n2), t2 -> a(0+n1*n2), s -> a(0)
                    call la_qlauum('U',n1,a(n2*n2),n2,info)
                    call la_qsyrk('U','T',n1,n2,one,a(0),n2,one,a(n2*n2),n2)

                    call la_qtrmm('L','L','T','N',n2,n1,one,a(n1*n2),n2,a(0),n2 &
                              )
                    call la_qlauum('L',n2,a(n1*n2),n2,info)
                 end if
              end if
           else
              ! n is even
              if (normaltransr) then
                 ! n is even and transr = 'n'
                 if (lower) then
                    ! srpa for lower, normal, and n is even ( a(0:n,0:k-1) )
                    ! t1 -> a(1,0), t2 -> a(0,0), s -> a(k+1,0)
                    ! t1 -> a(1), t2 -> a(0), s -> a(k+1)
                    call la_qlauum('L',k,a(1),n + 1,info)
                    call la_qsyrk('L','T',k,k,one,a(k + 1),n + 1,one,a(1),n + 1)

                    call la_qtrmm('L','U','N','N',k,k,one,a(0),n + 1,a(k + 1),n + 1)

                    call la_qlauum('U',k,a(0),n + 1,info)
                 else
                    ! srpa for upper, normal, and n is even ( a(0:n,0:k-1) )
                    ! t1 -> a(k+1,0) ,  t2 -> a(k,0),   s -> a(0,0)
                    ! t1 -> a(k+1), t2 -> a(k), s -> a(0)
                    call la_qlauum('L',k,a(k + 1),n + 1,info)
                    call la_qsyrk('L','N',k,k,one,a(0),n + 1,one,a(k + 1),n + 1)

                    call la_qtrmm('R','U','T','N',k,k,one,a(k),n + 1,a(0),n + 1)

                    call la_qlauum('U',k,a(k),n + 1,info)
                 end if
              else
                 ! n is even and transr = 't'
                 if (lower) then
                    ! srpa for lower, transpose, and n is even (see paper)
                    ! t1 -> b(0,1), t2 -> b(0,0), s -> b(0,k+1),
                    ! t1 -> a(0+k), t2 -> a(0+0), s -> a(0+k*(k+1)); lda=k
                    call la_qlauum('U',k,a(k),k,info)
                    call la_qsyrk('U','N',k,k,one,a(k*(k + 1)),k,one,a(k),k)

                    call la_qtrmm('R','L','N','N',k,k,one,a(0),k,a(k*(k + 1)),k &
                              )
                    call la_qlauum('L',k,a(0),k,info)
                 else
                    ! srpa for upper, transpose, and n is even (see paper)
                    ! t1 -> b(0,k+1),     t2 -> b(0,k),   s -> b(0,0),
                    ! t1 -> a(0+k*(k+1)), t2 -> a(0+k*k), s -> a(0+0)); lda=k
                    call la_qlauum('U',k,a(k*(k + 1)),k,info)
                    call la_qsyrk('U','T',k,k,one,a(0),k,one,a(k*(k + 1)),k)

                    call la_qtrmm('L','L','T','N',k,k,one,a(k*k),k,a(0),k)

                    call la_qlauum('L',k,a(k*k),k,info)
                 end if
              end if
           end if
           return
     end subroutine la_qpftri
#endif

     !> SPOTRF: computes the Cholesky factorization of a real symmetric
     !> positive definite matrix A.
     !> The factorization has the form
     !> A = U**T * U,  if UPLO = 'U', or
     !> A = L  * L**T,  if UPLO = 'L',
     !> where U is an upper triangular matrix and L is lower triangular.
     !> This is the block version of the algorithm, calling Level 3 BLAS.

     pure subroutine la_spotrf(uplo,n,a,lda,info)
        use la_constants_sp
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: uplo
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: lda,n
           ! Array Arguments
           real(sp),intent(inout) :: a(lda,*)
        ! =====================================================================

           ! Local Scalars
           logical(lk) :: upper
           integer(ilp) :: j,jb,nb
           ! Intrinsic Functions
           intrinsic :: max,min
           ! Executable Statements
           ! test the input parameters.
           info = 0
           upper = la_lsame(uplo,'U')
           if (.not. upper .and. .not. la_lsame(uplo,'L')) then
              info = -1
           else if (n < 0) then
              info = -2
           else if (lda < max(1,n)) then
              info = -4
           end if
           if (info /= 0) then
              call la_xerbla('SPOTRF',-info)
              return
           end if
           ! quick return if possible
           if (n == 0) return
           ! determine the block size for this environment.
           nb = la_ilaenv(1,'SPOTRF',uplo,n,-1,-1,-1)
           if (nb <= 1 .or. nb >= n) then
              ! use unblocked code.
              call la_spotrf2(uplo,n,a,lda,info)
           else
              ! use blocked code.
              if (upper) then
                 ! compute the cholesky factorization a = u**t*u.
                 do j = 1,n,nb
                    ! update and factorize the current diagonal block and test
                    ! for non-positive-definiteness.
                    jb = min(nb,n - j + 1)
                    call la_ssyrk('UPPER','TRANSPOSE',jb,j - 1,-one,a(1,j),lda,one,a( &
                               j,j),lda)
                    call la_spotrf2('UPPER',jb,a(j,j),lda,info)
                    if (info /= 0) go to 30
                    if (j + jb <= n) then
                       ! compute the current block row.
                       call la_sgemm('TRANSPOSE','NO TRANSPOSE',jb,n - j - jb + 1,j - 1,-one,a( &
                                 1,j),lda,a(1,j + jb),lda,one,a(j,j + jb),lda)
                       call la_strsm('LEFT','UPPER','TRANSPOSE','NON-UNIT',jb,n - j - jb + 1, &
                                 one,a(j,j),lda,a(j,j + jb),lda)
                    end if
                 end do
              else
                 ! compute the cholesky factorization a = l*l**t.
                 do j = 1,n,nb
                    ! update and factorize the current diagonal block and test
                    ! for non-positive-definiteness.
                    jb = min(nb,n - j + 1)
                    call la_ssyrk('LOWER','NO TRANSPOSE',jb,j - 1,-one,a(j,1),lda,one, &
                               a(j,j),lda)
                    call la_spotrf2('LOWER',jb,a(j,j),lda,info)
                    if (info /= 0) go to 30
                    if (j + jb <= n) then
                       ! compute the current block column.
                       call la_sgemm('NO TRANSPOSE','TRANSPOSE',n - j - jb + 1,jb,j - 1,-one,a( &
                                 j + jb,1),lda,a(j,1),lda,one,a(j + jb,j),lda)
                       call la_strsm('RIGHT','LOWER','TRANSPOSE','NON-UNIT',n - j - jb + 1,jb, &
                                 one,a(j,j),lda,a(j + jb,j),lda)
                    end if
                 end do
              end if
           end if
           go to 40
           30 continue
           info = info + j - 1
           40 continue
           return
     end subroutine la_spotrf
     !> DPOTRF: computes the Cholesky factorization of a real symmetric
