                       call la_dgemm('TRANSPOSE','NO TRANSPOSE',jb,n - j - jb + 1,j - 1,-one,a( &
                                 1,j),lda,a(1,j + jb),lda,one,a(j,j + jb),lda)
                       call la_dtrsm('LEFT','UPPER','TRANSPOSE','NON-UNIT',jb,n - j - jb + 1, &
                                 one,a(j,j),lda,a(j,j + jb),lda)
                    end if
