                    if (info /= 0) go to 30
                    if (j + jb <= n) then
                       ! compute the current block column.
                       call la_dgemm('NO TRANSPOSE','TRANSPOSE',n - j - jb + 1,jb,j - 1,-one,a( &
                                 j + jb,1),lda,a(j,1),lda,one,a(j + jb,j),lda)
                       call la_dtrsm('RIGHT','LOWER','TRANSPOSE','NON-UNIT',n - j - jb + 1,jb, &
                                 one,a(j,j),lda,a(j + jb,j),lda)
                    end if
                 end do
              end if
           end if
           go to 40
           30 continue
           info = info + j - 1
