                       call la_xgemm('TRANSPOSE','NO TRANSPOSE',jb,n - j - jb + 1,j - 1,-one,a( &
                                 1,j),lda,a(1,j + jb),lda,one,a(j,j + jb),lda)
                       call la_xtrsm('LEFT','UPPER','TRANSPOSE','NON-UNIT',jb,n - j - jb + 1, &
                                 one,a(j,j),lda,a(j,j + jb),lda)
                    end if
                 end do
              else
                 ! compute the cholesky factorization a = l*l**t.
                 do j = 1,n,nb
                    ! update and factorize the current diagonal block and test
                    ! for non-positive-definiteness.
                    jb = min(nb,n - j + 1)
                    call la_xsyrk('LOWER','NO TRANSPOSE',jb,j - 1,-one,a(j,1),lda,one, &
                               a(j,j),lda)
                    call la_xpotrf2('LOWER',jb,a(j,j),lda,info)
                    if (info /= 0) go to 30
                    if (j + jb <= n) then
                       ! compute the current block column.
                       call la_xgemm('NO TRANSPOSE','TRANSPOSE',n - j - jb + 1,jb,j - 1,-one,a( &
                                 j + jb,1),lda,a(j,1),lda,one,a(j + jb,j),lda)
                       call la_xtrsm('RIGHT','LOWER','TRANSPOSE','NON-UNIT',n - j - jb + 1,jb, &
                                 one,a(j,j),lda,a(j + jb,j),lda)
                    end if
                 end do
              end if
           end if
           go to 40
           30 continue
           info = info + j - 1
           40 continue
           return
     end subroutine la_xpotrf
#endif
#ifdef LA_WITH_QP
     !> QPOTRF: computes the Cholesky factorization of a real symmetric
     !> positive definite matrix A.
     !> The factorization has the form
     !> A = U**T * U,  if UPLO = 'U', or
     !> A = L  * L**T,  if UPLO = 'L',
     !> where U is an upper triangular matrix and L is lower triangular.
     !> This is the block version of the algorithm, calling Level 3 BLAS.

     pure subroutine la_qpotrf(uplo,n,a,lda,info)
        use la_constants_qp
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: uplo
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: lda,n
           ! Array Arguments
           real(qp),intent(inout) :: a(lda,*)
        ! =====================================================================

           ! Local Scalars
           logical(lk) :: upper
           integer(ilp) :: j,jb,nb
           ! Intrinsic Functions
           intrinsic :: max,min
           ! Executable Statements
           ! test the input parameters.
           info = 0
           upper = la_lsame(uplo,'U')
           if (.not. upper .and. .not. la_lsame(uplo,'L')) then
              info = -1
           else if (n < 0) then
              info = -2
           else if (lda < max(1,n)) then
              info = -4
           end if
           if (info /= 0) then
              call la_xerbla('QPOTRF',-info)
              return
           end if
           ! quick return if possible
           if (n == 0) return
           ! determine the block size for this environment.
           nb = la_ilaenv(1,'QPOTRF',uplo,n,-1,-1,-1)
           if (nb <= 1 .or. nb >= n) then
              ! use unblocked code.
              call la_qpotrf2(uplo,n,a,lda,info)
           else
              ! use blocked code.
              if (upper) then
                 ! compute the cholesky factorization a = u**t*u.
                 do j = 1,n,nb
                    ! update and factorize the current diagonal block and test
                    ! for non-positive-definiteness.
                    jb = min(nb,n - j + 1)
                    call la_qsyrk('UPPER','TRANSPOSE',jb,j - 1,-one,a(1,j),lda,one,a( &
                               j,j),lda)
                    call la_qpotrf2('UPPER',jb,a(j,j),lda,info)
                    if (info /= 0) go to 30
                    if (j + jb <= n) then
                       ! compute the current block row.
                       call la_qgemm('TRANSPOSE','NO TRANSPOSE',jb,n - j - jb + 1,j - 1,-one,a( &
                                 1,j),lda,a(1,j + jb),lda,one,a(j,j + jb),lda)
                       call la_qtrsm('LEFT','UPPER','TRANSPOSE','NON-UNIT',jb,n - j - jb + 1, &
                                 one,a(j,j),lda,a(j,j + jb),lda)
                    end if
                 end do
              else
                 ! compute the cholesky factorization a = l*l**t.
                 do j = 1,n,nb
                    ! update and factorize the current diagonal block and test
                    ! for non-positive-definiteness.
                    jb = min(nb,n - j + 1)
                    call la_qsyrk('LOWER','NO TRANSPOSE',jb,j - 1,-one,a(j,1),lda,one, &
                               a(j,j),lda)
                    call la_qpotrf2('LOWER',jb,a(j,j),lda,info)
                    if (info /= 0) go to 30
                    if (j + jb <= n) then
                       ! compute the current block column.
                       call la_qgemm('NO TRANSPOSE','TRANSPOSE',n - j - jb + 1,jb,j - 1,-one,a( &
                                 j + jb,1),lda,a(j,1),lda,one,a(j + jb,j),lda)
                       call la_qtrsm('RIGHT','LOWER','TRANSPOSE','NON-UNIT',n - j - jb + 1,jb, &
                                 one,a(j,j),lda,a(j + jb,j),lda)
                    end if
                 end do
              end if
           end if
           go to 40
           30 continue
           info = info + j - 1
           40 continue
           return
     end subroutine la_qpotrf
#endif

     !> SPTRFS: improves the computed solution to a system of linear
     !> equations when the coefficient matrix is symmetric positive definite
     !> and tridiagonal, and provides error bounds and backward error
     !> estimates for the solution.

     pure subroutine la_sptrfs(n,nrhs,d,e,df,ef,b,ldb,x,ldx,ferr,berr,work,info)
        use la_constants_sp,only:zero,one,two,three

        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: ldb,ldx,n,nrhs
           ! Array Arguments
           real(sp),intent(in) :: b(ldb,*),d(*),df(*),e(*),ef(*)
           real(sp),intent(out) :: berr(*),ferr(*),work(*)
           real(sp),intent(inout) :: x(ldx,*)
        ! =====================================================================
           ! Parameters
           integer(ilp),parameter :: itmax = 5

           ! Local Scalars
           integer(ilp) :: count,i,ix,j,nz
           real(sp) :: bi,cx,dx,eps,ex,lstres,s,safe1,safe2,safmin
           ! Intrinsic Functions
           intrinsic :: abs,max
           ! Executable Statements
           ! test the input parameters.
           info = 0
           if (n < 0) then
              info = -1
           else if (nrhs < 0) then
              info = -2
           else if (ldb < max(1,n)) then
              info = -8
           else if (ldx < max(1,n)) then
              info = -10
           end if
           if (info /= 0) then
              call la_xerbla('SPTRFS',-info)
              return
           end if
           ! quick return if possible
           if (n == 0 .or. nrhs == 0) then
              do j = 1,nrhs
                 ferr(j) = zero
                 berr(j) = zero
              end do
              return
           end if
           ! nz = maximum number of nonzero elements in each row of a, plus 1
           nz = 4
           eps = la_slamch('EPSILON')
           safmin = la_slamch('SAFE MINIMUM')
           safe1 = nz*safmin
           safe2 = safe1/eps
           ! do for each right hand side
           loop_90: do j = 1,nrhs
              count = 1
              lstres = three
              20 continue
              ! loop until stopping criterion is satisfied.
              ! compute residual r = b - a * x.  also compute
              ! abs(a)*abs(x) + abs(b) for use in the backward error bound.
              if (n == 1) then
                 bi = b(1,j)
                 dx = d(1)*x(1,j)
                 work(n + 1) = bi - dx
                 work(1) = abs(bi) + abs(dx)
              else
                 bi = b(1,j)
                 dx = d(1)*x(1,j)
                 ex = e(1)*x(2,j)
                 work(n + 1) = bi - dx - ex
                 work(1) = abs(bi) + abs(dx) + abs(ex)
                 do i = 2,n - 1
                    bi = b(i,j)
                    cx = e(i - 1)*x(i - 1,j)
                    dx = d(i)*x(i,j)
                    ex = e(i)*x(i + 1,j)
                    work(n + i) = bi - cx - dx - ex
                    work(i) = abs(bi) + abs(cx) + abs(dx) + abs(ex)
                 end do
                 bi = b(n,j)
                 cx = e(n - 1)*x(n - 1,j)
                 dx = d(n)*x(n,j)
                 work(n + n) = bi - cx - dx
                 work(n) = abs(bi) + abs(cx) + abs(dx)
              end if
              ! compute componentwise relative backward error from formula
              ! max(i) ( abs(r(i)) / ( abs(a)*abs(x) + abs(b) )(i) )
              ! where abs(z) is the componentwise absolute value of the matrix
              ! or vector z.  if the i-th component of the denominator is less
              ! than safe2, then safe1 is added to the i-th components of the
              ! numerator and denominator before dividing.
              s = zero
              do i = 1,n
                 if (work(i) > safe2) then
                    s = max(s,abs(work(n + i))/work(i))
                 else
                    s = max(s, (abs(work(n + i)) + safe1)/(work(i) + safe1))
                 end if
              end do
              berr(j) = s
              ! test stopping criterion. continue iterating if
                 ! 1) the residual berr(j) is larger than machine epsilon, and
                 ! 2) berr(j) decreased by at least a factor of 2 during the
                    ! last iteration, and
                 ! 3) at most itmax iterations tried.
              if (berr(j) > eps .and. two*berr(j) <= lstres .and. count <= itmax) then
                 ! update solution and try again.
                 call la_spttrs(n,1,df,ef,work(n + 1),n,info)
                 call la_saxpy(n,one,work(n + 1),1,x(1,j),1)
                 lstres = berr(j)
                 count = count + 1
                 go to 20
              end if
              ! bound error from formula
              ! norm(x - xtrue) / norm(x) .le. ferr =
              ! norm( abs(inv(a))*
                 ! ( abs(r) + nz*eps*( abs(a)*abs(x)+abs(b) ))) / norm(x)
              ! where
                ! norm(z) is the magnitude of the largest component of z
                ! inv(a) is the inverse of a
                ! abs(z) is the componentwise absolute value of the matrix or
                   ! vector z
                ! nz is the maximum number of nonzeros in any row of a, plus 1
                ! eps is machine epsilon
              ! the i-th component of abs(r)+nz*eps*(abs(a)*abs(x)+abs(b))
              ! is incremented by safe1 if the i-th component of
              ! abs(a)*abs(x) + abs(b) is less than safe2.
              do i = 1,n
                 if (work(i) > safe2) then
                    work(i) = abs(work(n + i)) + nz*eps*work(i)
                 else
                    work(i) = abs(work(n + i)) + nz*eps*work(i) + safe1
                 end if
              end do
              ix = la_isamax(n,work,1)
              ferr(j) = work(ix)
              ! estimate the norm of inv(a).
              ! solve m(a) * x = e, where m(a) = (m(i,j)) is given by
                 ! m(i,j) =  abs(a(i,j)), i = j,
                 ! m(i,j) = -abs(a(i,j)), i .ne. j,
              ! and e = [ 1, 1, ..., 1 ]**t.  note m(a) = m(l)*d*m(l)**t.
              ! solve m(l) * x = e.
              work(1) = one
              do i = 2,n
                 work(i) = one + work(i - 1)*abs(ef(i - 1))
              end do
              ! solve d * m(l)**t * x = b.
              work(n) = work(n)/df(n)
              do i = n - 1,1,-1
                 work(i) = work(i)/df(i) + work(i + 1)*abs(ef(i))
              end do
              ! compute norm(inv(a)) = max(x(i)), 1<=i<=n.
              ix = la_isamax(n,work,1)
              ferr(j) = ferr(j)*abs(work(ix))
              ! normalize error.
              lstres = zero
              do i = 1,n
                 lstres = max(lstres,abs(x(i,j)))
              end do
              if (lstres /= zero) ferr(j) = ferr(j)/lstres
           end do loop_90
           return
     end subroutine la_sptrfs
     !> DPTRFS: improves the computed solution to a system of linear
     !> equations when the coefficient matrix is symmetric positive definite
     !> and tridiagonal, and provides error bounds and backward error
     !> estimates for the solution.

     pure subroutine la_dptrfs(n,nrhs,d,e,df,ef,b,ldb,x,ldx,ferr,berr,work,info)
        use la_constants_dp,only:zero,one,two,three

        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: ldb,ldx,n,nrhs
           ! Array Arguments
           real(dp),intent(in) :: b(ldb,*),d(*),df(*),e(*),ef(*)
           real(dp),intent(out) :: berr(*),ferr(*),work(*)
           real(dp),intent(inout) :: x(ldx,*)
        ! =====================================================================
           ! Parameters
           integer(ilp),parameter :: itmax = 5

           ! Local Scalars
           integer(ilp) :: count,i,ix,j,nz
           real(dp) :: bi,cx,dx,eps,ex,lstres,s,safe1,safe2,safmin
           ! Intrinsic Functions
           intrinsic :: abs,max
           ! Executable Statements
           ! test the input parameters.
           info = 0
           if (n < 0) then
              info = -1
           else if (nrhs < 0) then
              info = -2
           else if (ldb < max(1,n)) then
              info = -8
           else if (ldx < max(1,n)) then
              info = -10
           end if
           if (info /= 0) then
              call la_xerbla('DPTRFS',-info)
              return
           end if
