                    if (info > 0) return
                    call la_strsm('R','L','T','N',n2,n1,one,a(0),n,a(n1),n)

                    call la_ssyrk('U','N',n2,n1,-one,a(n1),n,one,a(n),n)
                    call la_spotrf('U',n2,a(n),n,info)
                    if (info > 0) info = info + n1
