                    call la_dpotrf('U',k,a(k),n + 1,info)
                    if (info > 0) info = info + k
                 end if
              else
                 ! n is even and transr = 't'
                 if (lower) then
                    ! srpa for lower, transpose and n is even (see paper)
                    ! t1 -> b(0,1), t2 -> b(0,0), s -> b(0,k+1)
                    ! t1 -> a(0+k), t2 -> a(0+0), s -> a(0+k*(k+1)); lda=k
                    call la_dpotrf('U',k,a(0 + k),k,info)
                    if (info > 0) return
                    call la_dtrsm('L','U','T','N',k,k,one,a(k),n1,a(k*(k + 1)), &
                              k)
                    call la_dsyrk('L','T',k,k,-one,a(k*(k + 1)),k,one,a(0),k)

                    call la_dpotrf('L',k,a(0),k,info)
