                    call la_xpotrf('U',k,a(k*(k + 1)),k,info)
                    if (info > 0) return
                    call la_xtrsm('R','U','N','N',k,k,one,a(k*(k + 1)),k,a(0),k &
                              )
                    call la_xsyrk('L','N',k,k,-one,a(0),k,one,a(k*k),k)
                    call la_xpotrf('L',k,a(k*k),k,info)
                    if (info > 0) info = info + k
                 end if
              end if
           end if
           return
     end subroutine la_xpftrf
#endif
#ifdef LA_WITH_QP
     !> QPFTRF: computes the Cholesky factorization of a real symmetric
     !> positive definite matrix A.
     !> The factorization has the form
     !> A = U**T * U,  if UPLO = 'U', or
     !> A = L  * L**T,  if UPLO = 'L',
     !> where U is an upper triangular matrix and L is lower triangular.
     !> This is the block version of the algorithm, calling Level 3 BLAS.

     pure subroutine la_qpftrf(transr,uplo,n,a,info)
        use la_constants_qp
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: transr,uplo
           integer(ilp),intent(in) :: n
           integer(ilp),intent(out) :: info
           ! Array Arguments
           real(qp),intent(inout) :: a(0:*)
        ! =====================================================================

           ! Local Scalars
           logical(lk) :: lower,nisodd,normaltransr
           integer(ilp) :: n1,n2,k
           ! Intrinsic Functions
           intrinsic :: mod
           ! Executable Statements
           ! test the input parameters.
           info = 0
           normaltransr = la_lsame(transr,'N')
           lower = la_lsame(uplo,'L')
           if (.not. normaltransr .and. .not. la_lsame(transr,'T')) then
              info = -1
           else if (.not. lower .and. .not. la_lsame(uplo,'U')) then
              info = -2
           else if (n < 0) then
              info = -3
           end if
           if (info /= 0) then
              call la_xerbla('QPFTRF',-info)
              return
           end if
           ! quick return if possible
           if (n == 0) return
           ! if n is odd, set nisodd = .true.
           ! if n is even, set k = n/2 and nisodd = .false.
           if (mod(n,2) == 0) then
              k = n/2
              nisodd = .false.
           else
              nisodd = .true.
           end if
           ! set n1 and n2 depending on lower
           if (lower) then
              n2 = n/2
              n1 = n - n2
           else
              n1 = n/2
              n2 = n - n1
           end if
           ! start execution: there are eight cases
           if (nisodd) then
              ! n is odd
              if (normaltransr) then
                 ! n is odd and transr = 'n'
                 if (lower) then
                   ! srpa for lower, normal and n is odd ( a(0:n-1,0:n1-1) )
                   ! t1 -> a(0,0), t2 -> a(0,1), s -> a(n1,0)
                   ! t1 -> a(0), t2 -> a(n), s -> a(n1)
                    call la_qpotrf('L',n1,a(0),n,info)
                    if (info > 0) return
                    call la_qtrsm('R','L','T','N',n2,n1,one,a(0),n,a(n1),n)

                    call la_qsyrk('U','N',n2,n1,-one,a(n1),n,one,a(n),n)
                    call la_qpotrf('U',n2,a(n),n,info)
                    if (info > 0) info = info + n1
                 else
                   ! srpa for upper, normal and n is odd ( a(0:n-1,0:n2-1)
                   ! t1 -> a(n1+1,0), t2 -> a(n1,0), s -> a(0,0)
                   ! t1 -> a(n2), t2 -> a(n1), s -> a(0)
                    call la_qpotrf('L',n1,a(n2),n,info)
                    if (info > 0) return
                    call la_qtrsm('L','L','N','N',n1,n2,one,a(n2),n,a(0),n)

                    call la_qsyrk('U','T',n2,n1,-one,a(0),n,one,a(n1),n)
                    call la_qpotrf('U',n2,a(n1),n,info)
                    if (info > 0) info = info + n1
                 end if
              else
                 ! n is odd and transr = 't'
                 if (lower) then
                    ! srpa for lower, transpose and n is odd
                    ! t1 -> a(0,0) , t2 -> a(1,0) , s -> a(0,n1)
                    ! t1 -> a(0+0) , t2 -> a(1+0) , s -> a(0+n1*n1); lda=n1
                    call la_qpotrf('U',n1,a(0),n1,info)
                    if (info > 0) return
                    call la_qtrsm('L','U','T','N',n1,n2,one,a(0),n1,a(n1*n1),n1 &
                              )
                    call la_qsyrk('L','T',n2,n1,-one,a(n1*n1),n1,one,a(1),n1)

                    call la_qpotrf('L',n2,a(1),n1,info)
                    if (info > 0) info = info + n1
                 else
                    ! srpa for upper, transpose and n is odd
                    ! t1 -> a(0,n1+1), t2 -> a(0,n1), s -> a(0,0)
                    ! t1 -> a(n2*n2), t2 -> a(n1*n2), s -> a(0); lda = n2
                    call la_qpotrf('U',n1,a(n2*n2),n2,info)
                    if (info > 0) return
                    call la_qtrsm('R','U','N','N',n2,n1,one,a(n2*n2),n2,a(0),n2 &
                              )
                    call la_qsyrk('L','N',n2,n1,-one,a(0),n2,one,a(n1*n2),n2)

                    call la_qpotrf('L',n2,a(n1*n2),n2,info)
                    if (info > 0) info = info + n1
                 end if
              end if
           else
              ! n is even
              if (normaltransr) then
                 ! n is even and transr = 'n'
                 if (lower) then
                    ! srpa for lower, normal, and n is even ( a(0:n,0:k-1) )
                    ! t1 -> a(1,0), t2 -> a(0,0), s -> a(k+1,0)
                    ! t1 -> a(1), t2 -> a(0), s -> a(k+1)
                    call la_qpotrf('L',k,a(1),n + 1,info)
                    if (info > 0) return
                    call la_qtrsm('R','L','T','N',k,k,one,a(1),n + 1,a(k + 1),n + 1)

                    call la_qsyrk('U','N',k,k,-one,a(k + 1),n + 1,one,a(0),n + 1)

                    call la_qpotrf('U',k,a(0),n + 1,info)
                    if (info > 0) info = info + k
                 else
                    ! srpa for upper, normal, and n is even ( a(0:n,0:k-1) )
                    ! t1 -> a(k+1,0) ,  t2 -> a(k,0),   s -> a(0,0)
                    ! t1 -> a(k+1), t2 -> a(k), s -> a(0)
                    call la_qpotrf('L',k,a(k + 1),n + 1,info)
                    if (info > 0) return
                    call la_qtrsm('L','L','N','N',k,k,one,a(k + 1),n + 1,a(0),n + 1)

                    call la_qsyrk('U','T',k,k,-one,a(0),n + 1,one,a(k),n + 1)

                    call la_qpotrf('U',k,a(k),n + 1,info)
                    if (info > 0) info = info + k
                 end if
              else
                 ! n is even and transr = 't'
                 if (lower) then
                    ! srpa for lower, transpose and n is even (see paper)
                    ! t1 -> b(0,1), t2 -> b(0,0), s -> b(0,k+1)
                    ! t1 -> a(0+k), t2 -> a(0+0), s -> a(0+k*(k+1)); lda=k
                    call la_qpotrf('U',k,a(0 + k),k,info)
                    if (info > 0) return
                    call la_qtrsm('L','U','T','N',k,k,one,a(k),n1,a(k*(k + 1)), &
                              k)
                    call la_qsyrk('L','T',k,k,-one,a(k*(k + 1)),k,one,a(0),k)

                    call la_qpotrf('L',k,a(0),k,info)
                    if (info > 0) info = info + k
                 else
                    ! srpa for upper, transpose and n is even (see paper)
                    ! t1 -> b(0,k+1),     t2 -> b(0,k),   s -> b(0,0)
                    ! t1 -> a(0+k*(k+1)), t2 -> a(0+k*k), s -> a(0+0)); lda=k
                    call la_qpotrf('U',k,a(k*(k + 1)),k,info)
                    if (info > 0) return
                    call la_qtrsm('R','U','N','N',k,k,one,a(k*(k + 1)),k,a(0),k &
                              )
                    call la_qsyrk('L','N',k,k,-one,a(0),k,one,a(k*k),k)
                    call la_qpotrf('L',k,a(k*k),k,info)
                    if (info > 0) info = info + k
                 end if
              end if
           end if
           return
     end subroutine la_qpftrf
#endif

     !> CLA_PORPVGRW: computes the reciprocal pivot growth factor
     !> norm(A)/norm(U). The "max absolute element" norm is used. If this is
     !> much less than 1, the stability of the LU factorization of the
     !> (equilibrated) matrix A could be poor. This also means that the
     !> solution X, estimated condition numbers, and error bounds could be
     !> unreliable.

     real(sp) function la_cla_porpvgrw(uplo,ncols,a,lda,af,ldaf,work)
        use la_constants_sp
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: uplo
           integer(ilp),intent(in) :: ncols,lda,ldaf
           ! Array Arguments
           complex(sp),intent(in) :: a(lda,*),af(ldaf,*)
           real(sp),intent(out) :: work(*)
        ! =====================================================================
           ! Local Scalars
           integer(ilp) :: i,j
           real(sp) :: amax,umax,rpvgrw
           logical(lk) :: upper
           complex(sp) :: zdum
           ! Intrinsic Functions
           intrinsic :: abs,max,min,real,aimag
           ! Statement Functions
           real(sp) :: cabs1
           ! Statement Function Definitions
           cabs1(zdum) = abs(real(zdum,KIND=sp)) + abs(aimag(zdum))
           ! Executable Statements
           upper = la_lsame('UPPER',uplo)
           ! la_spotrf will have factored only the ncolsxncols leading minor, so
           ! we restrict the growth search to that minor and use only the first
           ! 2*ncols workspace entries.
           rpvgrw = one
           do i = 1,2*ncols
              work(i) = zero
           end do
           ! find the max magnitude entry of each column.
           if (upper) then
              do j = 1,ncols
                 do i = 1,j
                    work(ncols + j) = max(cabs1(a(i,j)),work(ncols + j))
                 end do
              end do
           else
              do j = 1,ncols
                 do i = j,ncols
                    work(ncols + j) = max(cabs1(a(i,j)),work(ncols + j))
                 end do
              end do
           end if
           ! now find the max magnitude entry of each column of the factor in
           ! af.  no pivoting, so no permutations.
           if (la_lsame('UPPER',uplo)) then
              do j = 1,ncols
                 do i = 1,j
                    work(j) = max(cabs1(af(i,j)),work(j))
                 end do
              end do
           else
              do j = 1,ncols
                 do i = j,ncols
                    work(j) = max(cabs1(af(i,j)),work(j))
                 end do
              end do
           end if
           ! compute the *inverse* of the max element growth factor.  dividing
           ! by zero would imply the largest entry of the factor's column is
           ! zero.  than can happen when either the column of a is zero or
           ! massive pivots made the factor underflow to zero.  neither counts
           ! as growth in itself, so simply ignore terms with zero
           ! denominators.
           if (la_lsame('UPPER',uplo)) then
              do i = 1,ncols
                 umax = work(i)
                 amax = work(ncols + i)
                 if (umax /= 0.0_sp) then
                    rpvgrw = min(amax/umax,rpvgrw)
                 end if
              end do
           else
              do i = 1,ncols
                 umax = work(i)
                 amax = work(ncols + i)
                 if (umax /= 0.0_sp) then
                    rpvgrw = min(amax/umax,rpvgrw)
                 end if
              end do
           end if
           la_cla_porpvgrw = rpvgrw
     end function la_cla_porpvgrw
