           complex(qp),intent(in) :: ab(ldab,*)
           complex(qp),intent(out) :: work(*)
        ! =====================================================================

           ! Local Scalars
           logical(lk) :: upper
           character :: normin
           integer(ilp) :: ix,kase
           real(qp) :: ainvnm,scale,scalel,scaleu,smlnum
           complex(qp) :: zdum
           ! Local Arrays
           integer(ilp) :: isave(3)
           ! Intrinsic Functions
           intrinsic :: abs,real,aimag
           ! Statement Functions
           real(qp) :: cabs1
           ! Statement Function Definitions
           cabs1(zdum) = abs(real(zdum,KIND=qp)) + abs(aimag(zdum))
           ! Executable Statements
           ! test the input parameters.
           info = 0
           upper = la_lsame(uplo,'U')
           if (.not. upper .and. .not. la_lsame(uplo,'L')) then
              info = -1
           else if (n < 0) then
              info = -2
           else if (kd < 0) then
              info = -3
           else if (ldab < kd + 1) then
              info = -5
           else if (anorm < zero) then
              info = -6
           end if
           if (info /= 0) then
              call la_xerbla('WPBCON',-info)
              return
           end if
           ! quick return if possible
           rcond = zero
           if (n == 0) then
              rcond = one
              return
           else if (anorm == zero) then
              return
           end if
           smlnum = la_qlamch('SAFE MINIMUM')
           ! estimate the 1-norm of the inverse.
           kase = 0
           normin = 'N'
           10 continue
           call la_wlacn2(n,work(n + 1),work,ainvnm,kase,isave)
           if (kase /= 0) then
              if (upper) then
                 ! multiply by inv(u**h).
                 call la_wlatbs('UPPER','CONJUGATE TRANSPOSE','NON-UNIT',normin,n,kd,ab, &
                            ldab,work,scalel,rwork,info)
                 normin = 'Y'
                 ! multiply by inv(u).
                 call la_wlatbs('UPPER','NO TRANSPOSE','NON-UNIT',normin,n,kd,ab,ldab, &
                           work,scaleu,rwork,info)
              else
                 ! multiply by inv(l).
                 call la_wlatbs('LOWER','NO TRANSPOSE','NON-UNIT',normin,n,kd,ab,ldab, &
                           work,scalel,rwork,info)
                 normin = 'Y'
                 ! multiply by inv(l**h).
                 call la_wlatbs('LOWER','CONJUGATE TRANSPOSE','NON-UNIT',normin,n,kd,ab, &
                            ldab,work,scaleu,rwork,info)
              end if
              ! multiply by 1/scale if doing so will not cause overflow.
              scale = scalel*scaleu
              if (scale /= one) then
                 ix = la_iwamax(n,work,1)
                 if (scale < cabs1(work(ix))*smlnum .or. scale == zero) go to 20
                 call la_wqrscl(n,scale,work,1)
              end if
              go to 10
           end if
           ! compute the estimate of the reciprocal condition number.
           if (ainvnm /= zero) rcond = (one/ainvnm)/anorm
           20 continue
           return
     end subroutine la_wpbcon
#endif

     !> CPBEQU: computes row and column scalings intended to equilibrate a
     !> Hermitian positive definite band matrix A and reduce its condition
     !> number (with respect to the two-norm).  S contains the scale factors,
     !> S(i) = 1/sqrt(A(i,i)), chosen so that the scaled matrix B with
     !> elements B(i,j) = S(i)*A(i,j)*S(j) has ones on the diagonal.  This
     !> choice of S puts the condition number of B within a factor N of the
     !> smallest possible condition number over all possible diagonal
     !> scalings.

     pure subroutine la_cpbequ(uplo,n,kd,ab,ldab,s,scond,amax,info)
        use la_constants_sp
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: uplo
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: kd,ldab,n
           real(sp),intent(out) :: amax,scond
           ! Array Arguments
           real(sp),intent(out) :: s(*)
           complex(sp),intent(in) :: ab(ldab,*)
        ! =====================================================================

           ! Local Scalars
           logical(lk) :: upper
           integer(ilp) :: i,j
           real(sp) :: smin
           ! Intrinsic Functions
           intrinsic :: max,min,real,sqrt
           ! Executable Statements
           ! test the input parameters.
           info = 0
           upper = la_lsame(uplo,'U')
           if (.not. upper .and. .not. la_lsame(uplo,'L')) then
              info = -1
           else if (n < 0) then
              info = -2
           else if (kd < 0) then
              info = -3
           else if (ldab < kd + 1) then
              info = -5
           end if
           if (info /= 0) then
              call la_xerbla('CPBEQU',-info)
              return
           end if
           ! quick return if possible
           if (n == 0) then
              scond = one
              amax = zero
              return
           end if
           if (upper) then
              j = kd + 1
           else
              j = 1
           end if
           ! initialize smin and amax.
           s(1) = real(ab(j,1),KIND=sp)
           smin = s(1)
           amax = s(1)
           ! find the minimum and maximum diagonal elements.
           do i = 2,n
              s(i) = real(ab(j,i),KIND=sp)
              smin = min(smin,s(i))
              amax = max(amax,s(i))
           end do
           if (smin <= zero) then
              ! find the first non-positive diagonal element and return.
              do i = 1,n
                 if (s(i) <= zero) then
                    info = i
                    return
                 end if
              end do
           else
              ! set the scale factors to the reciprocals
              ! of the diagonal elements.
              do i = 1,n
                 s(i) = one/sqrt(s(i))
              end do
              ! compute scond = min(s(i)) / max(s(i))
              scond = sqrt(smin)/sqrt(amax)
           end if
           return
     end subroutine la_cpbequ
