                 ajj = real(ab(kd + 1,j),KIND=xdp)
                 if (ajj <= zero) then
                    ab(kd + 1,j) = ajj
                    go to 30
                 end if
                 ajj = sqrt(ajj)
                 ab(kd + 1,j) = ajj
                 ! compute elements j+1:j+kn of row j and update the
                 ! trailing submatrix within the band.
                 kn = min(kd,n - j)
                 if (kn > 0) then
                    call la_yxscal(kn,one/ajj,ab(kd,j + 1),kld)
                    call la_ylacgv(kn,ab(kd,j + 1),kld)
                    call la_yher('UPPER',kn,-one,ab(kd,j + 1),kld,ab(kd + 1,j + 1),kld)

                    call la_ylacgv(kn,ab(kd,j + 1),kld)
                 end if
              end do
           else
              ! compute the cholesky factorization a = l*l**h.
              do j = 1,n
                 ! compute l(j,j) and test for non-positive-definiteness.
                 ajj = real(ab(1,j),KIND=xdp)
                 if (ajj <= zero) then
                    ab(1,j) = ajj
                    go to 30
                 end if
                 ajj = sqrt(ajj)
                 ab(1,j) = ajj
                 ! compute elements j+1:j+kn of column j and update the
                 ! trailing submatrix within the band.
                 kn = min(kd,n - j)
                 if (kn > 0) then
                    call la_yxscal(kn,one/ajj,ab(2,j),1)
                    call la_yher('LOWER',kn,-one,ab(2,j),1,ab(1,j + 1),kld)
                 end if
              end do
           end if
           return
           30 continue
           info = j
           return
     end subroutine la_ypbtf2
#endif
#ifdef LA_WITH_QP
     !> WPBTF2: computes the Cholesky factorization of a complex Hermitian
     !> positive definite band matrix A.
     !> The factorization has the form
     !> A = U**H * U ,  if UPLO = 'U', or
     !> A = L  * L**H,  if UPLO = 'L',
     !> where U is an upper triangular matrix, U**H is the conjugate transpose
     !> of U, and L is lower triangular.
     !> This is the unblocked version of the algorithm, calling Level 2 BLAS.

     pure subroutine la_wpbtf2(uplo,n,kd,ab,ldab,info)
        use la_constants_qp
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: uplo
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: kd,ldab,n
           ! Array Arguments
           complex(qp),intent(inout) :: ab(ldab,*)
        ! =====================================================================

           ! Local Scalars
           logical(lk) :: upper
           integer(ilp) :: j,kld,kn
           real(qp) :: ajj
           ! Intrinsic Functions
           intrinsic :: real,max,min,sqrt
           ! Executable Statements
           ! test the input parameters.
           info = 0
           upper = la_lsame(uplo,'U')
           if (.not. upper .and. .not. la_lsame(uplo,'L')) then
              info = -1
           else if (n < 0) then
              info = -2
           else if (kd < 0) then
              info = -3
           else if (ldab < kd + 1) then
              info = -5
           end if
           if (info /= 0) then
              call la_xerbla('WPBTF2',-info)
              return
           end if
           ! quick return if possible
           if (n == 0) return
           kld = max(1,ldab - 1)
           if (upper) then
              ! compute the cholesky factorization a = u**h * u.
              do j = 1,n
                 ! compute u(j,j) and test for non-positive-definiteness.
                 ajj = real(ab(kd + 1,j),KIND=qp)
                 if (ajj <= zero) then
                    ab(kd + 1,j) = ajj
                    go to 30
                 end if
                 ajj = sqrt(ajj)
                 ab(kd + 1,j) = ajj
                 ! compute elements j+1:j+kn of row j and update the
                 ! trailing submatrix within the band.
                 kn = min(kd,n - j)
                 if (kn > 0) then
                    call la_wqscal(kn,one/ajj,ab(kd,j + 1),kld)
                    call la_wlacgv(kn,ab(kd,j + 1),kld)
                    call la_wher('UPPER',kn,-one,ab(kd,j + 1),kld,ab(kd + 1,j + 1),kld)

                    call la_wlacgv(kn,ab(kd,j + 1),kld)
                 end if
              end do
           else
              ! compute the cholesky factorization a = l*l**h.
              do j = 1,n
                 ! compute l(j,j) and test for non-positive-definiteness.
                 ajj = real(ab(1,j),KIND=qp)
                 if (ajj <= zero) then
                    ab(1,j) = ajj
                    go to 30
                 end if
                 ajj = sqrt(ajj)
                 ab(1,j) = ajj
                 ! compute elements j+1:j+kn of column j and update the
                 ! trailing submatrix within the band.
                 kn = min(kd,n - j)
                 if (kn > 0) then
                    call la_wqscal(kn,one/ajj,ab(2,j),1)
                    call la_wher('LOWER',kn,-one,ab(2,j),1,ab(1,j + 1),kld)
                 end if
              end do
           end if
           return
           30 continue
           info = j
           return
     end subroutine la_wpbtf2
#endif

     !> CPBTRS: solves a system of linear equations A*X = B with a Hermitian
     !> positive definite band matrix A using the Cholesky factorization
     !> A = U**H*U or A = L*L**H computed by CPBTRF.

     pure subroutine la_cpbtrs(uplo,n,kd,nrhs,ab,ldab,b,ldb,info)
        ! -- lapack computational routine --
