           ! Array Arguments
           complex(sp),intent(in) :: ab(ldab,*)
           complex(sp),intent(inout) :: b(ldb,*)
        ! =====================================================================
           ! Local Scalars
           logical(lk) :: upper
           integer(ilp) :: j
           ! Intrinsic Functions
