                 call la_ctbsv('LOWER','NO TRANSPOSE','NON-UNIT',n,kd,ab,ldab,b(1,j) &
                           ,1)
                 ! solve l**h *x = b, overwriting b with x.
                 call la_ctbsv('LOWER','CONJUGATE TRANSPOSE','NON-UNIT',n,kd,ab,ldab,b( &
                            1,j),1)
              end do
           end if
           return
