     !> CPOCON: estimates the reciprocal of the condition number (in the
     !> 1-norm) of a complex Hermitian positive definite matrix using the
     !> Cholesky factorization A = U**H*U or A = L*L**H computed by CPOTRF.
     !> An estimate is obtained for norm(inv(A)), and the reciprocal of the
     !> condition number is computed as RCOND = 1 / (ANORM * norm(inv(A))).

     pure subroutine la_cpocon(uplo,n,a,lda,anorm,rcond,work,rwork,info)
        use la_constants_sp,only:zero,one
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: uplo
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: lda,n
           real(sp),intent(in) :: anorm
           real(sp),intent(out) :: rcond
           ! Array Arguments
           real(sp),intent(out) :: rwork(*)
           complex(sp),intent(inout) :: a(lda,*)
           complex(sp),intent(out) :: work(*)
        ! =====================================================================

           ! Local Scalars
           logical(lk) :: upper
           character :: normin
           integer(ilp) :: ix,kase
           real(sp) :: ainvnm,scale,scalel,scaleu,smlnum
           complex(sp) :: zdum
           ! Local Arrays
           integer(ilp) :: isave(3)
           ! Intrinsic Functions
           intrinsic :: abs,aimag,max,real
           ! Statement Functions
           real(sp) :: cabs1
           ! Statement Function Definitions
           cabs1(zdum) = abs(real(zdum,KIND=sp)) + abs(aimag(zdum))
           ! Executable Statements
           ! test the input parameters.
           info = 0
           upper = la_lsame(uplo,'U')
           if (.not. upper .and. .not. la_lsame(uplo,'L')) then
              info = -1
           else if (n < 0) then
              info = -2
           else if (lda < max(1,n)) then
              info = -4
           else if (anorm < zero) then
              info = -5
           end if
           if (info /= 0) then
              call la_xerbla('CPOCON',-info)
              return
           end if
           ! quick return if possible
           rcond = zero
           if (n == 0) then
              rcond = one
              return
           else if (anorm == zero) then
              return
           end if
           smlnum = la_slamch('SAFE MINIMUM')
           ! estimate the 1-norm of inv(a).
           kase = 0
           normin = 'N'
           10 continue
           call la_clacn2(n,work(n + 1),work,ainvnm,kase,isave)
           if (kase /= 0) then
              if (upper) then
                 ! multiply by inv(u**h).
                 call la_clatrs('UPPER','CONJUGATE TRANSPOSE','NON-UNIT',normin,n,a,lda, &
                            work,scalel,rwork,info)
                 normin = 'Y'
                 ! multiply by inv(u).
                 call la_clatrs('UPPER','NO TRANSPOSE','NON-UNIT',normin,n,a,lda,work, &
                           scaleu,rwork,info)
              else
                 ! multiply by inv(l).
                 call la_clatrs('LOWER','NO TRANSPOSE','NON-UNIT',normin,n,a,lda,work, &
                           scalel,rwork,info)
                 normin = 'Y'
                 ! multiply by inv(l**h).
                 call la_clatrs('LOWER','CONJUGATE TRANSPOSE','NON-UNIT',normin,n,a,lda, &
                            work,scaleu,rwork,info)
              end if
              ! multiply by 1/scale if doing so will not cause overflow.
              scale = scalel*scaleu
              if (scale /= one) then
                 ix = la_icamax(n,work,1)
                 if (scale < cabs1(work(ix))*smlnum .or. scale == zero) go to 20
                 call la_csrscl(n,scale,work,1)
              end if
              go to 10
           end if
           ! compute the estimate of the reciprocal condition number.
           if (ainvnm /= zero) rcond = (one/ainvnm)/anorm
           20 continue
           return
     end subroutine la_cpocon
     !> ZPOCON: estimates the reciprocal of the condition number (in the
     !> 1-norm) of a complex Hermitian positive definite matrix using the
     !> Cholesky factorization A = U**H*U or A = L*L**H computed by ZPOTRF.
     !> An estimate is obtained for norm(inv(A)), and the reciprocal of the
     !> condition number is computed as RCOND = 1 / (ANORM * norm(inv(A))).

     pure subroutine la_zpocon(uplo,n,a,lda,anorm,rcond,work,rwork,info)
