           call la_zlacn2(n,work(n + 1),work,ainvnm,kase,isave)
           if (kase /= 0) then
              if (upper) then
                 ! multiply by inv(u**h).
                 call la_zlatrs('UPPER','CONJUGATE TRANSPOSE','NON-UNIT',normin,n,a,lda, &
