     !> condition number is computed as RCOND = 1 / (ANORM * norm(inv(A))).

     pure subroutine la_ypocon(uplo,n,a,lda,anorm,rcond,work,rwork,info)
        use la_constants_xdp,only:zero,one
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: uplo
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: lda,n
           real(xdp),intent(in) :: anorm
           real(xdp),intent(out) :: rcond
           ! Array Arguments
           real(xdp),intent(out) :: rwork(*)
           complex(xdp),intent(inout) :: a(lda,*)
           complex(xdp),intent(out) :: work(*)
        ! =====================================================================

           ! Local Scalars
           logical(lk) :: upper
           character :: normin
           integer(ilp) :: ix,kase
           real(xdp) :: ainvnm,scale,scalel,scaleu,smlnum
           complex(xdp) :: zdum
           ! Local Arrays
           integer(ilp) :: isave(3)
           ! Intrinsic Functions
           intrinsic :: abs,real,aimag,max
           ! Statement Functions
           real(xdp) :: cabs1
           ! Statement Function Definitions
           cabs1(zdum) = abs(real(zdum,KIND=xdp)) + abs(aimag(zdum))
           ! Executable Statements
           ! test the input parameters.
           info = 0
           upper = la_lsame(uplo,'U')
           if (.not. upper .and. .not. la_lsame(uplo,'L')) then
              info = -1
           else if (n < 0) then
              info = -2
           else if (lda < max(1,n)) then
              info = -4
           else if (anorm < zero) then
              info = -5
           end if
           if (info /= 0) then
              call la_xerbla('YPOCON',-info)
              return
           end if
           ! quick return if possible
           rcond = zero
           if (n == 0) then
              rcond = one
              return
           else if (anorm == zero) then
              return
           end if
           smlnum = la_xlamch('SAFE MINIMUM')
           ! estimate the 1-norm of inv(a).
           kase = 0
           normin = 'N'
           10 continue
           call la_ylacn2(n,work(n + 1),work,ainvnm,kase,isave)
           if (kase /= 0) then
              if (upper) then
                 ! multiply by inv(u**h).
                 call la_ylatrs('UPPER','CONJUGATE TRANSPOSE','NON-UNIT',normin,n,a,lda, &
