           real(xdp),intent(out) :: s(*)
        ! =====================================================================

           ! Local Scalars
           integer(ilp) :: i
           real(xdp) :: smin,base,tmp
           ! Intrinsic Functions
           intrinsic :: max,min,sqrt,log,int,real,aimag
           ! Executable Statements
           ! test the input parameters.
