     !> CPOTF2: computes the Cholesky factorization of a complex Hermitian
     !> positive definite matrix A.
     !> The factorization has the form
     !> A = U**H * U ,  if UPLO = 'U', or
     !> A = L  * L**H,  if UPLO = 'L',
     !> where U is an upper triangular matrix and L is lower triangular.
     !> This is the unblocked version of the algorithm, calling Level 2 BLAS.

     pure subroutine la_cpotf2(uplo,n,a,lda,info)
        use la_constants_sp
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: uplo
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: lda,n
           ! Array Arguments
           complex(sp),intent(inout) :: a(lda,*)
        ! =====================================================================

           ! Local Scalars
           logical(lk) :: upper
           integer(ilp) :: j
           real(sp) :: ajj
           ! Intrinsic Functions
           intrinsic :: max,real,sqrt
           ! Executable Statements
           ! test the input parameters.
           info = 0
           upper = la_lsame(uplo,'U')
           if (.not. upper .and. .not. la_lsame(uplo,'L')) then
              info = -1
           else if (n < 0) then
              info = -2
           else if (lda < max(1,n)) then
              info = -4
           end if
           if (info /= 0) then
              call la_xerbla('CPOTF2',-info)
              return
           end if
           ! quick return if possible
           if (n == 0) return
           if (upper) then
              ! compute the cholesky factorization a = u**h *u.
              do j = 1,n
                 ! compute u(j,j) and test for non-positive-definiteness.
                 ajj = real(real(a(j,j),KIND=sp) - la_cdotc(j - 1,a(1,j),1,a(1,j), &
                            1),KIND=sp)
                 if (ajj <= zero .or. la_sisnan(ajj)) then
                    a(j,j) = ajj
                    go to 30
                 end if
                 ajj = sqrt(ajj)
                 a(j,j) = ajj
                 ! compute elements j+1:n of row j.
                 if (j < n) then
                    call la_clacgv(j - 1,a(1,j),1)
                    call la_cgemv('TRANSPOSE',j - 1,n - j,-cone,a(1,j + 1),lda,a(1,j), &
                              1,cone,a(j,j + 1),lda)
                    call la_clacgv(j - 1,a(1,j),1)
                    call la_csscal(n - j,one/ajj,a(j,j + 1),lda)
                 end if
              end do
           else
              ! compute the cholesky factorization a = l*l**h.
              do j = 1,n
                 ! compute l(j,j) and test for non-positive-definiteness.
                 ajj = real(real(a(j,j),KIND=sp) - la_cdotc(j - 1,a(j,1),lda,a(j,1 &
                           ),lda),KIND=sp)
                 if (ajj <= zero .or. la_sisnan(ajj)) then
                    a(j,j) = ajj
                    go to 30
                 end if
                 ajj = sqrt(ajj)
                 a(j,j) = ajj
                 ! compute elements j+1:n of column j.
                 if (j < n) then
                    call la_clacgv(j - 1,a(j,1),lda)
                    call la_cgemv('NO TRANSPOSE',n - j,j - 1,-cone,a(j + 1,1),lda,a(j,1) &
                              ,lda,cone,a(j + 1,j),1)
                    call la_clacgv(j - 1,a(j,1),lda)
                    call la_csscal(n - j,one/ajj,a(j + 1,j),1)
                 end if
              end do
           end if
           go to 40
           30 continue
           info = j
           40 continue
           return
     end subroutine la_cpotf2
