     !> CPOTRS: solves a system of linear equations A*X = B with a Hermitian
     !> positive definite matrix A using the Cholesky factorization
     !> A = U**H*U or A = L*L**H computed by CPOTRF.

     pure subroutine la_cpotrs(uplo,n,nrhs,a,lda,b,ldb,info)
        use la_constants_sp
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: uplo
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: lda,ldb,n,nrhs
           ! Array Arguments
           complex(sp),intent(in) :: a(lda,*)
           complex(sp),intent(inout) :: b(ldb,*)
        ! =====================================================================

           ! Local Scalars
           logical(lk) :: upper
           ! Intrinsic Functions
           intrinsic :: max
           ! Executable Statements
           ! test the input parameters.
           info = 0
           upper = la_lsame(uplo,'U')
           if (.not. upper .and. .not. la_lsame(uplo,'L')) then
              info = -1
           else if (n < 0) then
              info = -2
           else if (nrhs < 0) then
              info = -3
           else if (lda < max(1,n)) then
              info = -5
           else if (ldb < max(1,n)) then
              info = -7
           end if
           if (info /= 0) then
              call la_xerbla('CPOTRS',-info)
              return
           end if
           ! quick return if possible
           if (n == 0 .or. nrhs == 0) return
           if (upper) then
              ! solve a*x = b where a = u**h *u.
              ! solve u**h *x = b, overwriting b with x.
              call la_ctrsm('LEFT','UPPER','CONJUGATE TRANSPOSE','NON-UNIT',n,nrhs,cone, &
                         a,lda,b,ldb)
              ! solve u*x = b, overwriting b with x.
              call la_ctrsm('LEFT','UPPER','NO TRANSPOSE','NON-UNIT',n,nrhs,cone,a, &
                        lda,b,ldb)
           else
              ! solve a*x = b where a = l*l**h.
              ! solve l*x = b, overwriting b with x.
              call la_ctrsm('LEFT','LOWER','NO TRANSPOSE','NON-UNIT',n,nrhs,cone,a, &
                        lda,b,ldb)
              ! solve l**h *x = b, overwriting b with x.
              call la_ctrsm('LEFT','LOWER','CONJUGATE TRANSPOSE','NON-UNIT',n,nrhs,cone, &
                         a,lda,b,ldb)
           end if
           return
     end subroutine la_cpotrs
