#ifdef LA_WITH_QP
     !> WPPEQU: computes row and column scalings intended to equilibrate a
     !> Hermitian positive definite matrix A in packed storage and reduce
     !> its condition number (with respect to the two-norm).  S contains the
     !> scale factors, S(i)=1/sqrt(A(i,i)), chosen so that the scaled matrix
     !> B with elements B(i,j)=S(i)*A(i,j)*S(j) has ones on the diagonal.
     !> This choice of S puts the condition number of B within a factor N of
     !> the smallest possible condition number over all possible diagonal
     !> scalings.

     pure subroutine la_wppequ(uplo,n,ap,s,scond,amax,info)
        use la_constants_qp
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: uplo
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: n
           real(qp),intent(out) :: amax,scond
           ! Array Arguments
           real(qp),intent(out) :: s(*)
           complex(qp),intent(in) :: ap(*)
        ! =====================================================================

           ! Local Scalars
           logical(lk) :: upper
           integer(ilp) :: i,jj
           real(qp) :: smin
           ! Intrinsic Functions
           intrinsic :: real,max,min,sqrt
           ! Executable Statements
           ! test the input parameters.
           info = 0
           upper = la_lsame(uplo,'U')
           if (.not. upper .and. .not. la_lsame(uplo,'L')) then
              info = -1
           else if (n < 0) then
              info = -2
           end if
           if (info /= 0) then
              call la_xerbla('WPPEQU',-info)
              return
           end if
           ! quick return if possible
           if (n == 0) then
              scond = one
              amax = zero
              return
           end if
           ! initialize smin and amax.
           s(1) = real(ap(1),KIND=qp)
           smin = s(1)
           amax = s(1)
           if (upper) then
              ! uplo = 'u':  upper triangle of a is stored.
              ! find the minimum and maximum diagonal elements.
              jj = 1
              do i = 2,n
                 jj = jj + i
                 s(i) = real(ap(jj),KIND=qp)
                 smin = min(smin,s(i))
                 amax = max(amax,s(i))
              end do
           else
              ! uplo = 'l':  lower triangle of a is stored.
              ! find the minimum and maximum diagonal elements.
              jj = 1
              do i = 2,n
                 jj = jj + n - i + 2
                 s(i) = real(ap(jj),KIND=qp)
                 smin = min(smin,s(i))
                 amax = max(amax,s(i))
              end do
           end if
           if (smin <= zero) then
              ! find the first non-positive diagonal element and return.
              do i = 1,n
                 if (s(i) <= zero) then
                    info = i
                    return
                 end if
              end do
           else
              ! set the scale factors to the reciprocals
              ! of the diagonal elements.
              do i = 1,n
                 s(i) = one/sqrt(s(i))
              end do
              ! compute scond = min(s(i)) / max(s(i))
              scond = sqrt(smin)/sqrt(amax)
           end if
           return
     end subroutine la_wppequ
#endif

     !> CPPTRF: computes the Cholesky factorization of a complex Hermitian
     !> positive definite matrix A stored in packed format.
     !> The factorization has the form
     !> A = U**H * U,  if UPLO = 'U', or
     !> A = L  * L**H,  if UPLO = 'L',
     !> where U is an upper triangular matrix and L is lower triangular.

     pure subroutine la_cpptrf(uplo,n,ap,info)
        use la_constants_sp
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: uplo
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: n
           ! Array Arguments
           complex(sp),intent(inout) :: ap(*)
        ! =====================================================================

           ! Local Scalars
           logical(lk) :: upper
           integer(ilp) :: j,jc,jj
           real(sp) :: ajj
           ! Intrinsic Functions
           intrinsic :: real,sqrt
           ! Executable Statements
           ! test the input parameters.
           info = 0
           upper = la_lsame(uplo,'U')
           if (.not. upper .and. .not. la_lsame(uplo,'L')) then
              info = -1
           else if (n < 0) then
              info = -2
           end if
           if (info /= 0) then
              call la_xerbla('CPPTRF',-info)
              return
           end if
           ! quick return if possible
           if (n == 0) return
           if (upper) then
              ! compute the cholesky factorization a = u**h * u.
              jj = 0
              do j = 1,n
                 jc = jj + 1
                 jj = jj + j
                 ! compute elements 1:j-1 of column j.
                 if (j > 1) call la_ctpsv('UPPER','CONJUGATE TRANSPOSE','NON-UNIT',j - 1,ap, &
                           ap(jc),1)
                 ! compute u(j,j) and test for non-positive-definiteness.
                 ajj = real(real(ap(jj),KIND=sp) - la_cdotc(j - 1,ap(jc),1,ap(jc),1 &
                           ),KIND=sp)
                 if (ajj <= zero) then
                    ap(jj) = ajj
                    go to 30
                 end if
                 ap(jj) = sqrt(ajj)
              end do
           else
              ! compute the cholesky factorization a = l * l**h.
              jj = 1
              do j = 1,n
                 ! compute l(j,j) and test for non-positive-definiteness.
                 ajj = real(ap(jj),KIND=sp)
                 if (ajj <= zero) then
                    ap(jj) = ajj
                    go to 30
                 end if
                 ajj = sqrt(ajj)
                 ap(jj) = ajj
                 ! compute elements j+1:n of column j and update the trailing
                 ! submatrix.
                 if (j < n) then
                    call la_csscal(n - j,one/ajj,ap(jj + 1),1)
                    call la_chpr('LOWER',n - j,-one,ap(jj + 1),1,ap(jj + n - j + 1))
                    jj = jj + n - j + 1
                 end if
              end do
           end if
           go to 40
           30 continue
           info = j
           40 continue
           return
     end subroutine la_cpptrf
