     !> CPPTRS: solves a system of linear equations A*X = B with a Hermitian
     !> positive definite matrix A in packed storage using the Cholesky
     !> factorization A = U**H*U or A = L*L**H computed by CPPTRF.

     pure subroutine la_cpptrs(uplo,n,nrhs,ap,b,ldb,info)
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: uplo
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: ldb,n,nrhs
           ! Array Arguments
           complex(sp),intent(in) :: ap(*)
           complex(sp),intent(inout) :: b(ldb,*)
        ! =====================================================================
           ! Local Scalars
           logical(lk) :: upper
           integer(ilp) :: i
           ! Intrinsic Functions
           intrinsic :: max
           ! Executable Statements
           ! test the input parameters.
           info = 0
           upper = la_lsame(uplo,'U')
           if (.not. upper .and. .not. la_lsame(uplo,'L')) then
              info = -1
           else if (n < 0) then
              info = -2
           else if (nrhs < 0) then
              info = -3
           else if (ldb < max(1,n)) then
              info = -6
           end if
           if (info /= 0) then
              call la_xerbla('CPPTRS',-info)
              return
           end if
           ! quick return if possible
           if (n == 0 .or. nrhs == 0) return
           if (upper) then
              ! solve a*x = b where a = u**h * u.
              do i = 1,nrhs
                 ! solve u**h *x = b, overwriting b with x.
                 call la_ctpsv('UPPER','CONJUGATE TRANSPOSE','NON-UNIT',n,ap,b(1,i), &
                           1)
                 ! solve u*x = b, overwriting b with x.
                 call la_ctpsv('UPPER','NO TRANSPOSE','NON-UNIT',n,ap,b(1,i),1)

              end do
           else
              ! solve a*x = b where a = l * l**h.
              do i = 1,nrhs
                 ! solve l*y = b, overwriting b with x.
                 call la_ctpsv('LOWER','NO TRANSPOSE','NON-UNIT',n,ap,b(1,i),1)

                 ! solve l**h *x = y, overwriting b with x.
                 call la_ctpsv('LOWER','CONJUGATE TRANSPOSE','NON-UNIT',n,ap,b(1,i), &
                           1)
              end do
           end if
           return
     end subroutine la_cpptrs
