           ! Array Arguments
           complex(qp),intent(in) :: ap(*)
           complex(qp),intent(inout) :: b(ldb,*)
        ! =====================================================================
           ! Local Scalars
           logical(lk) :: upper
           integer(ilp) :: i
           ! Intrinsic Functions
           intrinsic :: max
           ! Executable Statements
           ! test the input parameters.
           info = 0
           upper = la_lsame(uplo,'U')
           if (.not. upper .and. .not. la_lsame(uplo,'L')) then
              info = -1
           else if (n < 0) then
              info = -2
           else if (nrhs < 0) then
              info = -3
           else if (ldb < max(1,n)) then
              info = -6
           end if
           if (info /= 0) then
              call la_xerbla('WPPTRS',-info)
              return
           end if
           ! quick return if possible
           if (n == 0 .or. nrhs == 0) return
           if (upper) then
              ! solve a*x = b where a = u**h * u.
              do i = 1,nrhs
                 ! solve u**h *x = b, overwriting b with x.
                 call la_wtpsv('UPPER','CONJUGATE TRANSPOSE','NON-UNIT',n,ap,b(1,i), &
                           1)
                 ! solve u*x = b, overwriting b with x.
                 call la_wtpsv('UPPER','NO TRANSPOSE','NON-UNIT',n,ap,b(1,i),1)

              end do
           else
              ! solve a*x = b where a = l * l**h.
              do i = 1,nrhs
                 ! solve l*y = b, overwriting b with x.
                 call la_wtpsv('LOWER','NO TRANSPOSE','NON-UNIT',n,ap,b(1,i),1)

                 ! solve l**h *x = y, overwriting b with x.
                 call la_wtpsv('LOWER','CONJUGATE TRANSPOSE','NON-UNIT',n,ap,b(1,i), &
                           1)
              end do
           end if
           return
     end subroutine la_wpptrs
#endif

     !> CPSTF2: computes the Cholesky factorization with complete
     !> pivoting of a complex Hermitian positive semidefinite matrix A.
     !> The factorization has the form
     !> P**T * A * P = U**H * U ,  if UPLO = 'U',
     !> P**T * A * P = L  * L**H,  if UPLO = 'L',
     !> where U is an upper triangular matrix and L is lower triangular, and
     !> P is stored as vector PIV.
     !> This algorithm does not attempt to check that A is positive
     !> semidefinite. This version of the algorithm calls level 2 BLAS.

     pure subroutine la_cpstf2(uplo,n,a,lda,piv,rank,tol,work,info)
        use la_constants_sp
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           real(sp),intent(in) :: tol
           integer(ilp),intent(out) :: info,rank
           integer(ilp),intent(in) :: lda,n
           character,intent(in) :: uplo
           ! Array Arguments
           complex(sp),intent(inout) :: a(lda,*)
           real(sp),intent(out) :: work(2*n)
           integer(ilp),intent(out) :: piv(n)
        ! =====================================================================

           ! Local Scalars
           complex(sp) :: ctemp
           real(sp) :: ajj,sstop,stemp
           integer(ilp) :: i,itemp,j,pvt
           logical(lk) :: upper
           ! Intrinsic Functions
           intrinsic :: conjg,max,real,sqrt
           ! Executable Statements
           ! test the input parameters
           info = 0
           upper = la_lsame(uplo,'U')
           if (.not. upper .and. .not. la_lsame(uplo,'L')) then
              info = -1
           else if (n < 0) then
              info = -2
           else if (lda < max(1,n)) then
              info = -4
           end if
           if (info /= 0) then
              call la_xerbla('CPSTF2',-info)
              return
           end if
           ! quick return if possible
           if (n == 0) return
           ! initialize piv
           do i = 1,n
              piv(i) = i
           end do
           ! compute stopping value
           do i = 1,n
              work(i) = real(a(i,i),KIND=sp)
           end do
           pvt = maxloc(work(1:n),1)
           ajj = real(a(pvt,pvt),KIND=sp)
           if (ajj <= zero .or. la_sisnan(ajj)) then
              rank = 0
              info = 1
              go to 200
           end if
           ! compute stopping value if not supplied
           if (tol < zero) then
              sstop = n*la_slamch('EPSILON')*ajj
           else
              sstop = tol
           end if
           ! set first chalf of work to zero, holds dot products
           do i = 1,n
              work(i) = 0
           end do
           if (upper) then
              ! compute the cholesky factorization p**t * a * p = u**h * u
              loop_150: do j = 1,n
              ! find pivot, test for exit, else swap rows and columns
              ! update dot products, compute possible pivots which are
              ! stored in the second chalf of work
                 do i = j,n
                    if (j > 1) then
                       work(i) = work(i) + real(conjg(a(j - 1,i))*a(j - 1,i),KIND=sp)

                    end if
                    work(n + i) = real(a(i,i),KIND=sp) - work(i)
                 end do
                 if (j > 1) then
                    itemp = maxloc(work((n + j):(2*n)),1)
                    pvt = itemp + j - 1
                    ajj = work(n + pvt)
                    if (ajj <= sstop .or. la_sisnan(ajj)) then
                       a(j,j) = ajj
                       go to 190
                    end if
                 end if
                 if (j /= pvt) then
                    ! pivot ok, so can now swap pivot rows and columns
                    a(pvt,pvt) = a(j,j)
                    call la_cswap(j - 1,a(1,j),1,a(1,pvt),1)
                    if (pvt < n) call la_cswap(n - pvt,a(j,pvt + 1),lda,a(pvt,pvt + 1),lda)

                    do i = j + 1,pvt - 1
                       ctemp = conjg(a(j,i))
                       a(j,i) = conjg(a(i,pvt))
                       a(i,pvt) = ctemp
                    end do
                    a(j,pvt) = conjg(a(j,pvt))
                    ! swap dot products and piv
                    stemp = work(j)
                    work(j) = work(pvt)
                    work(pvt) = stemp
                    itemp = piv(pvt)
                    piv(pvt) = piv(j)
                    piv(j) = itemp
                 end if
                 ajj = sqrt(ajj)
                 a(j,j) = ajj
                 ! compute elements j+1:n of row j
                 if (j < n) then
                    call la_clacgv(j - 1,a(1,j),1)
                    call la_cgemv('TRANS',j - 1,n - j,-cone,a(1,j + 1),lda,a(1,j),1, &
                              cone,a(j,j + 1),lda)
                    call la_clacgv(j - 1,a(1,j),1)
                    call la_csscal(n - j,one/ajj,a(j,j + 1),lda)
                 end if
              end do loop_150
           else
              ! compute the cholesky factorization p**t * a * p = l * l**h
              loop_180: do j = 1,n
              ! find pivot, test for exit, else swap rows and columns
              ! update dot products, compute possible pivots which are
              ! stored in the second chalf of work
                 do i = j,n
                    if (j > 1) then
                       work(i) = work(i) + real(conjg(a(i,j - 1))*a(i,j - 1),KIND=sp)

                    end if
                    work(n + i) = real(a(i,i),KIND=sp) - work(i)
                 end do
                 if (j > 1) then
                    itemp = maxloc(work((n + j):(2*n)),1)
                    pvt = itemp + j - 1
                    ajj = work(n + pvt)
                    if (ajj <= sstop .or. la_sisnan(ajj)) then
                       a(j,j) = ajj
                       go to 190
                    end if
                 end if
                 if (j /= pvt) then
                    ! pivot ok, so can now swap pivot rows and columns
                    a(pvt,pvt) = a(j,j)
                    call la_cswap(j - 1,a(j,1),lda,a(pvt,1),lda)
                    if (pvt < n) call la_cswap(n - pvt,a(pvt + 1,j),1,a(pvt + 1,pvt),1)

                    do i = j + 1,pvt - 1
                       ctemp = conjg(a(i,j))
                       a(i,j) = conjg(a(pvt,i))
                       a(pvt,i) = ctemp
                    end do
                    a(pvt,j) = conjg(a(pvt,j))
                    ! swap dot products and piv
                    stemp = work(j)
                    work(j) = work(pvt)
                    work(pvt) = stemp
                    itemp = piv(pvt)
                    piv(pvt) = piv(j)
                    piv(j) = itemp
                 end if
                 ajj = sqrt(ajj)
                 a(j,j) = ajj
                 ! compute elements j+1:n of column j
                 if (j < n) then
                    call la_clacgv(j - 1,a(j,1),lda)
                    call la_cgemv('NO TRANS',n - j,j - 1,-cone,a(j + 1,1),lda,a(j,1), &
                              lda,cone,a(j + 1,j),1)
                    call la_clacgv(j - 1,a(j,1),lda)
                    call la_csscal(n - j,one/ajj,a(j + 1,j),1)
                 end if
              end do loop_180
           end if
           ! ran to completion, a has full rank
           rank = n
           go to 200
           190 continue
           ! rank is number of steps completed.  set info = 1 to signal
           ! that the factorization cannot be used to solve a system.
           rank = j - 1
           info = 1
           200 continue
           return
     end subroutine la_cpstf2
