                    call la_ylacgv(j - 1,a(j,1),lda)
                    call la_ygemv('NO TRANS',n - j,j - 1,-cone,a(j + 1,1),lda,a(j,1), &
                              lda,cone,a(j + 1,j),1)
                    call la_ylacgv(j - 1,a(j,1),lda)
                    call la_yxscal(n - j,one/ajj,a(j + 1,j),1)
                 end if
              end do loop_180
           end if
           ! ran to completion, a has full rank
           rank = n
           go to 200
           190 continue
           ! rank is number of steps completed.  set info = 1 to signal
           ! that the factorization cannot be used to solve a system.
           rank = j - 1
           info = 1
           200 continue
           return
