#ifdef LA_WITH_QP
     !> WPSTF2: computes the Cholesky factorization with complete
     !> pivoting of a complex Hermitian positive semidefinite matrix A.
     !> The factorization has the form
     !> P**T * A * P = U**H * U ,  if UPLO = 'U',
     !> P**T * A * P = L  * L**H,  if UPLO = 'L',
     !> where U is an upper triangular matrix and L is lower triangular, and
     !> P is stored as vector PIV.
     !> This algorithm does not attempt to check that A is positive
     !> semidefinite. This version of the algorithm calls level 2 BLAS.

     pure subroutine la_wpstf2(uplo,n,a,lda,piv,rank,tol,work,info)
        use la_constants_qp
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           real(qp),intent(in) :: tol
           integer(ilp),intent(out) :: info,rank
           integer(ilp),intent(in) :: lda,n
           character,intent(in) :: uplo
           ! Array Arguments
           complex(qp),intent(inout) :: a(lda,*)
           real(qp),intent(out) :: work(2*n)
           integer(ilp),intent(out) :: piv(n)
        ! =====================================================================

           ! Local Scalars
           complex(qp) :: wtemp
           real(qp) :: ajj,qstop,qtemp
           integer(ilp) :: i,itemp,j,pvt
           logical(lk) :: upper
           ! Intrinsic Functions
           intrinsic :: real,conjg,max,sqrt
           ! Executable Statements
           ! test the input parameters
           info = 0
           upper = la_lsame(uplo,'U')
           if (.not. upper .and. .not. la_lsame(uplo,'L')) then
              info = -1
           else if (n < 0) then
              info = -2
           else if (lda < max(1,n)) then
              info = -4
           end if
           if (info /= 0) then
              call la_xerbla('WPSTF2',-info)
              return
           end if
           ! quick return if possible
           if (n == 0) return
           ! initialize piv
           do i = 1,n
              piv(i) = i
           end do
           ! compute stopping value
           do i = 1,n
              work(i) = real(a(i,i),KIND=qp)
           end do
           pvt = maxloc(work(1:n),1)
           ajj = real(a(pvt,pvt),KIND=qp)
           if (ajj <= zero .or. la_qisnan(ajj)) then
              rank = 0
              info = 1
              go to 200
           end if
           ! compute stopping value if not supplied
           if (tol < zero) then
              qstop = n*la_qlamch('EPSILON')*ajj
           else
              qstop = tol
           end if
           ! set first chalf of work to zero, holds dot products
           do i = 1,n
              work(i) = 0
           end do
           if (upper) then
              ! compute the cholesky factorization p**t * a * p = u**h* u
              loop_150: do j = 1,n
              ! find pivot, test for exit, else swap rows and columns
              ! update dot products, compute possible pivots which are
              ! stored in the second chalf of work
                 do i = j,n
                    if (j > 1) then
                       work(i) = work(i) + real(conjg(a(j - 1,i))*a(j - 1,i),KIND=qp)

                    end if
                    work(n + i) = real(a(i,i),KIND=qp) - work(i)
                 end do
                 if (j > 1) then
                    itemp = maxloc(work((n + j):(2*n)),1)
                    pvt = itemp + j - 1
                    ajj = work(n + pvt)
                    if (ajj <= qstop .or. la_qisnan(ajj)) then
                       a(j,j) = ajj
                       go to 190
                    end if
                 end if
                 if (j /= pvt) then
                    ! pivot ok, so can now swap pivot rows and columns
                    a(pvt,pvt) = a(j,j)
                    call la_wswap(j - 1,a(1,j),1,a(1,pvt),1)
                    if (pvt < n) call la_wswap(n - pvt,a(j,pvt + 1),lda,a(pvt,pvt + 1),lda)

                    do i = j + 1,pvt - 1
                       wtemp = conjg(a(j,i))
                       a(j,i) = conjg(a(i,pvt))
                       a(i,pvt) = wtemp
                    end do
                    a(j,pvt) = conjg(a(j,pvt))
                    ! swap dot products and piv
                    qtemp = work(j)
                    work(j) = work(pvt)
                    work(pvt) = qtemp
                    itemp = piv(pvt)
                    piv(pvt) = piv(j)
                    piv(j) = itemp
                 end if
                 ajj = sqrt(ajj)
                 a(j,j) = ajj
                 ! compute elements j+1:n of row j
                 if (j < n) then
                    call la_wlacgv(j - 1,a(1,j),1)
                    call la_wgemv('TRANS',j - 1,n - j,-cone,a(1,j + 1),lda,a(1,j),1, &
                              cone,a(j,j + 1),lda)
                    call la_wlacgv(j - 1,a(1,j),1)
                    call la_wqscal(n - j,one/ajj,a(j,j + 1),lda)
                 end if
              end do loop_150
           else
              ! compute the cholesky factorization p**t * a * p = l * l**h
              loop_180: do j = 1,n
              ! find pivot, test for exit, else swap rows and columns
              ! update dot products, compute possible pivots which are
              ! stored in the second chalf of work
                 do i = j,n
                    if (j > 1) then
                       work(i) = work(i) + real(conjg(a(i,j - 1))*a(i,j - 1),KIND=qp)

                    end if
                    work(n + i) = real(a(i,i),KIND=qp) - work(i)
                 end do
                 if (j > 1) then
                    itemp = maxloc(work((n + j):(2*n)),1)
                    pvt = itemp + j - 1
                    ajj = work(n + pvt)
                    if (ajj <= qstop .or. la_qisnan(ajj)) then
                       a(j,j) = ajj
                       go to 190
                    end if
                 end if
                 if (j /= pvt) then
                    ! pivot ok, so can now swap pivot rows and columns
                    a(pvt,pvt) = a(j,j)
                    call la_wswap(j - 1,a(j,1),lda,a(pvt,1),lda)
                    if (pvt < n) call la_wswap(n - pvt,a(pvt + 1,j),1,a(pvt + 1,pvt),1)

                    do i = j + 1,pvt - 1
                       wtemp = conjg(a(i,j))
                       a(i,j) = conjg(a(pvt,i))
                       a(pvt,i) = wtemp
                    end do
                    a(pvt,j) = conjg(a(pvt,j))
                    ! swap dot products and piv
                    qtemp = work(j)
                    work(j) = work(pvt)
                    work(pvt) = qtemp
                    itemp = piv(pvt)
                    piv(pvt) = piv(j)
                    piv(j) = itemp
                 end if
                 ajj = sqrt(ajj)
                 a(j,j) = ajj
                 ! compute elements j+1:n of column j
                 if (j < n) then
                    call la_wlacgv(j - 1,a(j,1),lda)
                    call la_wgemv('NO TRANS',n - j,j - 1,-cone,a(j + 1,1),lda,a(j,1), &
                              lda,cone,a(j + 1,j),1)
                    call la_wlacgv(j - 1,a(j,1),lda)
                    call la_wqscal(n - j,one/ajj,a(j + 1,j),1)
                 end if
              end do loop_180
           end if
           ! ran to completion, a has full rank
           rank = n
           go to 200
           190 continue
           ! rank is number of steps completed.  set info = 1 to signal
           ! that the factorization cannot be used to solve a system.
           rank = j - 1
           info = 1
           200 continue
           return
     end subroutine la_wpstf2
