           integer(ilp),intent(in) :: lda,n
           character,intent(in) :: uplo
           ! Array Arguments
           complex(sp),intent(inout) :: a(lda,*)
           real(sp),intent(out) :: work(2*n)
           integer(ilp),intent(out) :: piv(n)
        ! =====================================================================

           ! Local Scalars
           complex(sp) :: ctemp
           real(sp) :: ajj,sstop,stemp
           integer(ilp) :: i,itemp,j,jb,k,nb,pvt
           logical(lk) :: upper
           ! Intrinsic Functions
           intrinsic :: conjg,max,min,real,sqrt,maxloc
           ! Executable Statements
           ! test the input parameters.
           info = 0
           upper = la_lsame(uplo,'U')
           if (.not. upper .and. .not. la_lsame(uplo,'L')) then
              info = -1
           else if (n < 0) then
              info = -2
           else if (lda < max(1,n)) then
              info = -4
           end if
           if (info /= 0) then
              call la_xerbla('CPSTRF',-info)
              return
           end if
           ! quick return if possible
           if (n == 0) return
           ! get block size
           nb = la_ilaenv(1,'CPOTRF',uplo,n,-1,-1,-1)
           if (nb <= 1 .or. nb >= n) then
              ! use unblocked code
              call la_cpstf2(uplo,n,a(1,1),lda,piv,rank,tol,work,info)
              go to 230
           else
           ! initialize piv
              do i = 1,n
                 piv(i) = i
              end do
           ! compute stopping value
              do i = 1,n
                 work(i) = real(a(i,i),KIND=sp)
              end do
              pvt = maxloc(work(1:n),1)
              ajj = real(a(pvt,pvt),KIND=sp)
              if (ajj <= zero .or. la_sisnan(ajj)) then
                 rank = 0
                 info = 1
                 go to 230
              end if
           ! compute stopping value if not supplied
              if (tol < zero) then
                 sstop = n*la_slamch('EPSILON')*ajj
              else
                 sstop = tol
              end if
              if (upper) then
                 ! compute the cholesky factorization p**t * a * p = u**h * u
                 loop_160: do k = 1,n,nb
                    ! account for last block not being nb wide
                    jb = min(nb,n - k + 1)
                    ! set relevant part of first chalf of work to zero,
                    ! holds dot products
                    do i = k,n
                       work(i) = 0
                    end do
                    loop_150: do j = k,k + jb - 1
                    ! find pivot, test for exit, else swap rows and columns
                    ! update dot products, compute possible pivots which are
                    ! stored in the second chalf of work
                       do i = j,n
                          if (j > k) then
                             work(i) = work(i) + real(conjg(a(j - 1,i))*a(j - 1,i), &
                                       KIND=sp)
                          end if
                          work(n + i) = real(a(i,i),KIND=sp) - work(i)
                       end do
                       if (j > 1) then
                          itemp = maxloc(work((n + j):(2*n)),1)
                          pvt = itemp + j - 1
                          ajj = work(n + pvt)
                          if (ajj <= sstop .or. la_sisnan(ajj)) then
