                          a(pvt,pvt) = a(j,j)
                          call la_cswap(j - 1,a(1,j),1,a(1,pvt),1)
                          if (pvt < n) call la_cswap(n - pvt,a(j,pvt + 1),lda,a(pvt,pvt + 1), &
                                     lda)
                          do i = j + 1,pvt - 1
                             ctemp = conjg(a(j,i))
                             a(j,i) = conjg(a(i,pvt))
                             a(i,pvt) = ctemp
                          end do
                          a(j,pvt) = conjg(a(j,pvt))
                          ! swap dot products and piv
                          stemp = work(j)
                          work(j) = work(pvt)
                          work(pvt) = stemp
                          itemp = piv(pvt)
                          piv(pvt) = piv(j)
                          piv(j) = itemp
                       end if
                       ajj = sqrt(ajj)
                       a(j,j) = ajj
                       ! compute elements j+1:n of row j.
                       if (j < n) then
                          call la_clacgv(j - 1,a(1,j),1)
                          call la_cgemv('TRANS',j - k,n - j,-cone,a(k,j + 1),lda,a(k,j), &
                                     1,cone,a(j,j + 1),lda)
                          call la_clacgv(j - 1,a(1,j),1)
                          call la_csscal(n - j,one/ajj,a(j,j + 1),lda)
                       end if
                    end do loop_150
                    ! update trailing matrix, j already incremented
                    if (k + jb <= n) then
                       call la_cherk('UPPER','CONJ TRANS',n - j + 1,jb,-one,a(k,j),lda, &
                                 one,a(j,j),lda)
                    end if
                 end do loop_160
              else
              ! compute the cholesky factorization p**t * a * p = l * l**h
                 loop_210: do k = 1,n,nb
                    ! account for last block not being nb wide
                    jb = min(nb,n - k + 1)
                    ! set relevant part of first chalf of work to zero,
                    ! holds dot products
                    do i = k,n
                       work(i) = 0
                    end do
                    loop_200: do j = k,k + jb - 1
                    ! find pivot, test for exit, else swap rows and columns
                    ! update dot products, compute possible pivots which are
                    ! stored in the second chalf of work
                       do i = j,n
                          if (j > k) then
                             work(i) = work(i) + real(conjg(a(i,j - 1))*a(i,j - 1), &
                                       KIND=sp)
                          end if
                          work(n + i) = real(a(i,i),KIND=sp) - work(i)
                       end do
                       if (j > 1) then
                          itemp = maxloc(work((n + j):(2*n)),1)
                          pvt = itemp + j - 1
                          ajj = work(n + pvt)
                          if (ajj <= sstop .or. la_sisnan(ajj)) then
                             a(j,j) = ajj
                             go to 220
                          end if
                       end if
                       if (j /= pvt) then
                          ! pivot ok, so can now swap pivot rows and columns
                          a(pvt,pvt) = a(j,j)
                          call la_cswap(j - 1,a(j,1),lda,a(pvt,1),lda)
                          if (pvt < n) call la_cswap(n - pvt,a(pvt + 1,j),1,a(pvt + 1,pvt), &
                                    1)
                          do i = j + 1,pvt - 1
                             ctemp = conjg(a(i,j))
                             a(i,j) = conjg(a(pvt,i))
                             a(pvt,i) = ctemp
                          end do
                          a(pvt,j) = conjg(a(pvt,j))
                          ! swap dot products and piv
                          stemp = work(j)
                          work(j) = work(pvt)
                          work(pvt) = stemp
                          itemp = piv(pvt)
                          piv(pvt) = piv(j)
                          piv(j) = itemp
                       end if
                       ajj = sqrt(ajj)
                       a(j,j) = ajj
                       ! compute elements j+1:n of column j.
                       if (j < n) then
                          call la_clacgv(j - 1,a(j,1),lda)
                          call la_cgemv('NO TRANS',n - j,j - k,-cone,a(j + 1,k),lda,a(j, &
                                    k),lda,cone,a(j + 1,j),1)
                          call la_clacgv(j - 1,a(j,1),lda)
                          call la_csscal(n - j,one/ajj,a(j + 1,j),1)
                       end if
                    end do loop_200
                    ! update trailing matrix, j already incremented
                    if (k + jb <= n) then
                       call la_cherk('LOWER','NO TRANS',n - j + 1,jb,-one,a(j,k),lda, &
                                 one,a(j,j),lda)
                    end if
                 end do loop_210
              end if
           end if
           ! ran to completion, a has full rank
           rank = n
           go to 230
           220 continue
           ! rank is the number of steps completed.  set info = 1 to signal
           ! that the factorization cannot be used to solve a system.
           rank = j - 1
           info = 1
           230 continue
           return
     end subroutine la_cpstrf
