                    ! stored in the second chalf of work
                       do i = j,n
                          if (j > k) then
                             work(i) = work(i) + real(conjg(a(i,j - 1))*a(i,j - 1), &
                                       KIND=dp)
                          end if
                          work(n + i) = real(a(i,i),KIND=dp) - work(i)
                       end do
                       if (j > 1) then
                          itemp = maxloc(work((n + j):(2*n)),1)
                          pvt = itemp + j - 1
                          ajj = work(n + pvt)
                          if (ajj <= dstop .or. la_disnan(ajj)) then
                             a(j,j) = ajj
                             go to 220
                          end if
                       end if
                       if (j /= pvt) then
                          ! pivot ok, so can now swap pivot rows and columns
                          a(pvt,pvt) = a(j,j)
                          call la_zswap(j - 1,a(j,1),lda,a(pvt,1),lda)
                          if (pvt < n) call la_zswap(n - pvt,a(pvt + 1,j),1,a(pvt + 1,pvt), &
                                    1)
                          do i = j + 1,pvt - 1
                             ztemp = conjg(a(i,j))
                             a(i,j) = conjg(a(pvt,i))
                             a(pvt,i) = ztemp
                          end do
                          a(pvt,j) = conjg(a(pvt,j))
                          ! swap dot products and piv
                          dtemp = work(j)
                          work(j) = work(pvt)
                          work(pvt) = dtemp
                          itemp = piv(pvt)
                          piv(pvt) = piv(j)
                          piv(j) = itemp
                       end if
                       ajj = sqrt(ajj)
                       a(j,j) = ajj
                       ! compute elements j+1:n of column j.
                       if (j < n) then
                          call la_zlacgv(j - 1,a(j,1),lda)
                          call la_zgemv('NO TRANS',n - j,j - k,-cone,a(j + 1,k),lda,a(j, &
                                    k),lda,cone,a(j + 1,j),1)
                          call la_zlacgv(j - 1,a(j,1),lda)
                          call la_zdscal(n - j,one/ajj,a(j + 1,j),1)
                       end if
                    end do loop_200
                    ! update trailing matrix, j already incremented
                    if (k + jb <= n) then
                       call la_zherk('LOWER','NO TRANS',n - j + 1,jb,-one,a(j,k),lda, &
                                 one,a(j,j),lda)
                    end if
                 end do loop_210
              end if
           end if
           ! ran to completion, a has full rank
           rank = n
           go to 230
           220 continue
           ! rank is the number of steps completed.  set info = 1 to signal
           ! that the factorization cannot be used to solve a system.
           rank = j - 1
           info = 1
           230 continue
           return
     end subroutine la_zpstrf
#ifdef LA_WITH_XDP
     !> YPSTRF: computes the Cholesky factorization with complete
     !> pivoting of a complex Hermitian positive semidefinite matrix A.
     !> The factorization has the form
     !> P**T * A * P = U**H * U ,  if UPLO = 'U',
     !> P**T * A * P = L  * L**H,  if UPLO = 'L',
     !> where U is an upper triangular matrix and L is lower triangular, and
     !> P is stored as vector PIV.
     !> This algorithm does not attempt to check that A is positive
     !> semidefinite. This version of the algorithm calls level 3 BLAS.

     pure subroutine la_ypstrf(uplo,n,a,lda,piv,rank,tol,work,info)
        use la_constants_xdp
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           real(xdp),intent(in) :: tol
           integer(ilp),intent(out) :: info,rank
           integer(ilp),intent(in) :: lda,n
           character,intent(in) :: uplo
           ! Array Arguments
           complex(xdp),intent(inout) :: a(lda,*)
           real(xdp),intent(out) :: work(2*n)
           integer(ilp),intent(out) :: piv(n)
        ! =====================================================================

           ! Local Scalars
           complex(xdp) :: ytemp
           real(xdp) :: ajj,xstop,xtemp
           integer(ilp) :: i,itemp,j,jb,k,nb,pvt
           logical(lk) :: upper
           ! Intrinsic Functions
           intrinsic :: real,conjg,max,min,sqrt,maxloc
           ! Executable Statements
           ! test the input parameters.
           info = 0
           upper = la_lsame(uplo,'U')
           if (.not. upper .and. .not. la_lsame(uplo,'L')) then
              info = -1
           else if (n < 0) then
              info = -2
           else if (lda < max(1,n)) then
              info = -4
           end if
           if (info /= 0) then
              call la_xerbla('YPSTRF',-info)
              return
           end if
           ! quick return if possible
           if (n == 0) return
           ! get block size
           nb = la_ilaenv(1,'YPOTRF',uplo,n,-1,-1,-1)
           if (nb <= 1 .or. nb >= n) then
              ! use unblocked code
              call la_ypstf2(uplo,n,a(1,1),lda,piv,rank,tol,work,info)
              go to 230
           else
           ! initialize piv
              do i = 1,n
                 piv(i) = i
              end do
           ! compute stopping value
              do i = 1,n
                 work(i) = real(a(i,i),KIND=xdp)
              end do
              pvt = maxloc(work(1:n),1)
              ajj = real(a(pvt,pvt),KIND=xdp)
              if (ajj <= zero .or. la_xisnan(ajj)) then
                 rank = 0
                 info = 1
                 go to 230
              end if
           ! compute stopping value if not supplied
              if (tol < zero) then
                 xstop = n*la_xlamch('EPSILON')*ajj
              else
                 xstop = tol
              end if
              if (upper) then
                 ! compute the cholesky factorization p**t * a * p = u**h * u
                 loop_160: do k = 1,n,nb
                    ! account for last block not being nb wide
                    jb = min(nb,n - k + 1)
                    ! set relevant part of first chalf of work to zero,
                    ! holds dot products
                    do i = k,n
                       work(i) = 0
                    end do
                    loop_150: do j = k,k + jb - 1
                    ! find pivot, test for exit, else swap rows and columns
                    ! update dot products, compute possible pivots which are
                    ! stored in the second chalf of work
                       do i = j,n
                          if (j > k) then
                             work(i) = work(i) + real(conjg(a(j - 1,i))*a(j - 1,i), &
                                       KIND=xdp)
                          end if
                          work(n + i) = real(a(i,i),KIND=xdp) - work(i)
                       end do
                       if (j > 1) then
                          itemp = maxloc(work((n + j):(2*n)),1)
                          pvt = itemp + j - 1
                          ajj = work(n + pvt)
                          if (ajj <= xstop .or. la_xisnan(ajj)) then
                             a(j,j) = ajj
                             go to 220
                          end if
                       end if
                       if (j /= pvt) then
                          ! pivot ok, so can now swap pivot rows and columns
                          a(pvt,pvt) = a(j,j)
                          call la_yswap(j - 1,a(1,j),1,a(1,pvt),1)
                          if (pvt < n) call la_yswap(n - pvt,a(j,pvt + 1),lda,a(pvt,pvt + 1), &
                                     lda)
                          do i = j + 1,pvt - 1
                             ytemp = conjg(a(j,i))
                             a(j,i) = conjg(a(i,pvt))
                             a(i,pvt) = ytemp
                          end do
                          a(j,pvt) = conjg(a(j,pvt))
                          ! swap dot products and piv
                          xtemp = work(j)
                          work(j) = work(pvt)
                          work(pvt) = xtemp
                          itemp = piv(pvt)
                          piv(pvt) = piv(j)
                          piv(j) = itemp
                       end if
                       ajj = sqrt(ajj)
                       a(j,j) = ajj
                       ! compute elements j+1:n of row j.
                       if (j < n) then
                          call la_ylacgv(j - 1,a(1,j),1)
                          call la_ygemv('TRANS',j - k,n - j,-cone,a(k,j + 1),lda,a(k,j), &
                                     1,cone,a(j,j + 1),lda)
                          call la_ylacgv(j - 1,a(1,j),1)
                          call la_yxscal(n - j,one/ajj,a(j,j + 1),lda)
                       end if
                    end do loop_150
                    ! update trailing matrix, j already incremented
                    if (k + jb <= n) then
                       call la_yherk('UPPER','CONJ TRANS',n - j + 1,jb,-one,a(k,j),lda, &
                                 one,a(j,j),lda)
                    end if
                 end do loop_160
              else
              ! compute the cholesky factorization p**t * a * p = l * l**h
                 loop_210: do k = 1,n,nb
                    ! account for last block not being nb wide
                    jb = min(nb,n - k + 1)
                    ! set relevant part of first chalf of work to zero,
                    ! holds dot products
                    do i = k,n
                       work(i) = 0
                    end do
                    loop_200: do j = k,k + jb - 1
                    ! find pivot, test for exit, else swap rows and columns
                    ! update dot products, compute possible pivots which are
                    ! stored in the second chalf of work
                       do i = j,n
                          if (j > k) then
                             work(i) = work(i) + real(conjg(a(i,j - 1))*a(i,j - 1), &
                                       KIND=xdp)
                          end if
                          work(n + i) = real(a(i,i),KIND=xdp) - work(i)
                       end do
                       if (j > 1) then
                          itemp = maxloc(work((n + j):(2*n)),1)
                          pvt = itemp + j - 1
                          ajj = work(n + pvt)
                          if (ajj <= xstop .or. la_xisnan(ajj)) then
                             a(j,j) = ajj
                             go to 220
                          end if
                       end if
                       if (j /= pvt) then
                          ! pivot ok, so can now swap pivot rows and columns
                          a(pvt,pvt) = a(j,j)
                          call la_yswap(j - 1,a(j,1),lda,a(pvt,1),lda)
                          if (pvt < n) call la_yswap(n - pvt,a(pvt + 1,j),1,a(pvt + 1,pvt), &
                                    1)
                          do i = j + 1,pvt - 1
                             ytemp = conjg(a(i,j))
                             a(i,j) = conjg(a(pvt,i))
                             a(pvt,i) = ytemp
                          end do
                          a(pvt,j) = conjg(a(pvt,j))
                          ! swap dot products and piv
                          xtemp = work(j)
                          work(j) = work(pvt)
                          work(pvt) = xtemp
                          itemp = piv(pvt)
                          piv(pvt) = piv(j)
                          piv(j) = itemp
                       end if
                       ajj = sqrt(ajj)
                       a(j,j) = ajj
                       ! compute elements j+1:n of column j.
                       if (j < n) then
                          call la_ylacgv(j - 1,a(j,1),lda)
                          call la_ygemv('NO TRANS',n - j,j - k,-cone,a(j + 1,k),lda,a(j, &
                                    k),lda,cone,a(j + 1,j),1)
                          call la_ylacgv(j - 1,a(j,1),lda)
                          call la_yxscal(n - j,one/ajj,a(j + 1,j),1)
                       end if
                    end do loop_200
                    ! update trailing matrix, j already incremented
                    if (k + jb <= n) then
                       call la_yherk('LOWER','NO TRANS',n - j + 1,jb,-one,a(j,k),lda, &
                                 one,a(j,j),lda)
                    end if
                 end do loop_210
              end if
           end if
           ! ran to completion, a has full rank
           rank = n
           go to 230
           220 continue
           ! rank is the number of steps completed.  set info = 1 to signal
           ! that the factorization cannot be used to solve a system.
           rank = j - 1
           info = 1
           230 continue
