     !> CPTTRF: computes the L*D*L**H factorization of a complex Hermitian
     !> positive definite tridiagonal matrix A.  The factorization may also
     !> be regarded as having the form A = U**H *D*U.

     pure subroutine la_cpttrf(n,d,e,info)
        use la_constants_sp
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: n
           ! Array Arguments
           real(sp),intent(inout) :: d(*)
           complex(sp),intent(inout) :: e(*)
        ! =====================================================================

           ! Local Scalars
           integer(ilp) :: i,i4
           real(sp) :: eii,eir,f,g
           ! Intrinsic Functions
           intrinsic :: aimag,cmplx,mod,real
           ! Executable Statements
           ! test the input parameters.
           info = 0
           if (n < 0) then
              info = -1
              call la_xerbla('CPTTRF',-info)
              return
           end if
           ! quick return if possible
           if (n == 0) return
           ! compute the l*d*l**h (or u**h *d*u) factorization of a.
           i4 = mod(n - 1,4)
           do i = 1,i4
              if (d(i) <= zero) then
                 info = i
                 go to 20
              end if
              eir = real(e(i),KIND=sp)
              eii = aimag(e(i))
              f = eir/d(i)
              g = eii/d(i)
              e(i) = cmplx(f,g,KIND=sp)
              d(i + 1) = d(i + 1) - f*eir - g*eii
           end do
           loop_110: do i = i4 + 1,n - 4,4
              ! drop out of the loop if d(i) <= 0: the matrix is not positive
              ! definite.
              if (d(i) <= zero) then
                 info = i
                 go to 20
              end if
              ! solve for e(i) and d(i+1).
              eir = real(e(i),KIND=sp)
              eii = aimag(e(i))
              f = eir/d(i)
              g = eii/d(i)
              e(i) = cmplx(f,g,KIND=sp)
              d(i + 1) = d(i + 1) - f*eir - g*eii
              if (d(i + 1) <= zero) then
                 info = i + 1
                 go to 20
              end if
              ! solve for e(i+1) and d(i+2).
              eir = real(e(i + 1),KIND=sp)
              eii = aimag(e(i + 1))
              f = eir/d(i + 1)
              g = eii/d(i + 1)
              e(i + 1) = cmplx(f,g,KIND=sp)
              d(i + 2) = d(i + 2) - f*eir - g*eii
              if (d(i + 2) <= zero) then
                 info = i + 2
                 go to 20
              end if
              ! solve for e(i+2) and d(i+3).
              eir = real(e(i + 2),KIND=sp)
              eii = aimag(e(i + 2))
              f = eir/d(i + 2)
              g = eii/d(i + 2)
              e(i + 2) = cmplx(f,g,KIND=sp)
              d(i + 3) = d(i + 3) - f*eir - g*eii
              if (d(i + 3) <= zero) then
                 info = i + 3
                 go to 20
              end if
              ! solve for e(i+3) and d(i+4).
              eir = real(e(i + 3),KIND=sp)
              eii = aimag(e(i + 3))
              f = eir/d(i + 3)
              g = eii/d(i + 3)
              e(i + 3) = cmplx(f,g,KIND=sp)
              d(i + 4) = d(i + 4) - f*eir - g*eii
           end do loop_110
           ! check d(n) for positive definiteness.
           if (d(n) <= zero) info = n
           20 continue
           return
     end subroutine la_cpttrf
