              f = eir/d(i + 3)
              g = eii/d(i + 3)
              e(i + 3) = cmplx(f,g,KIND=qp)
              d(i + 4) = d(i + 4) - f*eir - g*eii
           end do loop_20
           ! check d(n) for positive definiteness.
           if (d(n) <= zero) info = n
           30 continue
           return
     end subroutine la_wpttrf
#endif

     !> CPTTS2: solves a tridiagonal system of the form
     !> A * X = B
     !> using the factorization A = U**H*D*U or A = L*D*L**H computed by CPTTRF.
     !> D is a diagonal matrix specified in the vector D, U (or L) is a unit
     !> bidiagonal matrix whose superdiagonal (subdiagonal) is specified in
     !> the vector E, and X and B are N by NRHS matrices.

     pure subroutine la_cptts2(iuplo,n,nrhs,d,e,b,ldb)
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           integer(ilp),intent(in) :: iuplo,ldb,n,nrhs
           ! Array Arguments
           real(sp),intent(in) :: d(*)
           complex(sp),intent(inout) :: b(ldb,*)
           complex(sp),intent(in) :: e(*)
        ! =====================================================================
           ! Local Scalars
           integer(ilp) :: i,j
           ! Intrinsic Functions
           intrinsic :: conjg
           ! Executable Statements
           ! quick return if possible
           if (n <= 1) then
              if (n == 1) call la_csscal(nrhs,1./d(1),b,ldb)
              return
           end if
           if (iuplo == 1) then
              ! solve a * x = b using the factorization a = u**h *d*u,
              ! overwriting each right hand side vector with its solution.
              if (nrhs <= 2) then
                 j = 1
                 5 continue
                 ! solve u**h * x = b.
                 do i = 2,n
                    b(i,j) = b(i,j) - b(i - 1,j)*conjg(e(i - 1))
                 end do
                 ! solve d * u * x = b.
                 do i = 1,n
                    b(i,j) = b(i,j)/d(i)
                 end do
                 do i = n - 1,1,-1
                    b(i,j) = b(i,j) - b(i + 1,j)*e(i)
                 end do
                 if (j < nrhs) then
                    j = j + 1
                    go to 5
                 end if
              else
                 do j = 1,nrhs
                    ! solve u**h * x = b.
                    do i = 2,n
                       b(i,j) = b(i,j) - b(i - 1,j)*conjg(e(i - 1))
                    end do
                    ! solve d * u * x = b.
                    b(n,j) = b(n,j)/d(n)
                    do i = n - 1,1,-1
                       b(i,j) = b(i,j)/d(i) - b(i + 1,j)*e(i)
                    end do
                 end do
              end if
           else
              ! solve a * x = b using the factorization a = l*d*l**h,
              ! overwriting each right hand side vector with its solution.
              if (nrhs <= 2) then
                 j = 1
                 65 continue
                 ! solve l * x = b.
                 do i = 2,n
                    b(i,j) = b(i,j) - b(i - 1,j)*e(i - 1)
                 end do
                 ! solve d * l**h * x = b.
                 do i = 1,n
                    b(i,j) = b(i,j)/d(i)
                 end do
                 do i = n - 1,1,-1
                    b(i,j) = b(i,j) - b(i + 1,j)*conjg(e(i))
                 end do
                 if (j < nrhs) then
                    j = j + 1
                    go to 65
                 end if
              else
                 do j = 1,nrhs
                    ! solve l * x = b.
                    do i = 2,n
                       b(i,j) = b(i,j) - b(i - 1,j)*e(i - 1)
                    end do
                    ! solve d * l**h * x = b.
                    b(n,j) = b(n,j)/d(n)
                    do i = n - 1,1,-1
                       b(i,j) = b(i,j)/d(i) - b(i + 1,j)*conjg(e(i))
                    end do
                 end do
              end if
           end if
           return
     end subroutine la_cptts2
