              ! where w = abs(r) + nz*eps*( abs(a)*abs(x)+abs(b) )))
              do i = 1,n
                 if (rwork(i) > safe2) then
                    rwork(i) = cabs1(work(i)) + nz*eps*rwork(i)
                 else
                    rwork(i) = cabs1(work(i)) + nz*eps*rwork(i) + safe1
                 end if
              end do
              kase = 0
              100 continue
              call la_wlacn2(n,work(n + 1),work,ferr(j),kase,isave)
              if (kase /= 0) then
                 if (kase == 1) then
                    ! multiply by diag(w)*inv(a**h).
                    call la_wpotrs(uplo,n,1,af,ldaf,work,n,info)
                    do i = 1,n
                       work(i) = rwork(i)*work(i)
                    end do
                 else if (kase == 2) then
                    ! multiply by inv(a)*diag(w).
                    do i = 1,n
                       work(i) = rwork(i)*work(i)
                    end do
                    call la_wpotrs(uplo,n,1,af,ldaf,work,n,info)
                 end if
                 go to 100
              end if
              ! normalize error.
              lstres = zero
              do i = 1,n
                 lstres = max(lstres,cabs1(x(i,j)))
              end do
              if (lstres /= zero) ferr(j) = ferr(j)/lstres
           end do loop_140
           return
     end subroutine la_wporfs
#endif

     !> CPOTRF: computes the Cholesky factorization of a complex Hermitian
     !> positive definite matrix A.
     !> The factorization has the form
     !> A = U**H * U,  if UPLO = 'U', or
     !> A = L  * L**H,  if UPLO = 'L',
     !> where U is an upper triangular matrix and L is lower triangular.
     !> This is the block version of the algorithm, calling Level 3 BLAS.

     pure subroutine la_cpotrf(uplo,n,a,lda,info)
        use la_constants_sp
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: uplo
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: lda,n
           ! Array Arguments
           complex(sp),intent(inout) :: a(lda,*)
        ! =====================================================================

           ! Local Scalars
           logical(lk) :: upper
           integer(ilp) :: j,jb,nb
           ! Intrinsic Functions
           intrinsic :: max,min
           ! Executable Statements
           ! test the input parameters.
           info = 0
           upper = la_lsame(uplo,'U')
           if (.not. upper .and. .not. la_lsame(uplo,'L')) then
              info = -1
           else if (n < 0) then
              info = -2
           else if (lda < max(1,n)) then
              info = -4
           end if
           if (info /= 0) then
              call la_xerbla('CPOTRF',-info)
              return
           end if
           ! quick return if possible
           if (n == 0) return
           ! determine the block size for this environment.
           nb = la_ilaenv(1,'CPOTRF',uplo,n,-1,-1,-1)
           if (nb <= 1 .or. nb >= n) then
              ! use unblocked code.
              call la_cpotrf2(uplo,n,a,lda,info)
           else
              ! use blocked code.
              if (upper) then
                 ! compute the cholesky factorization a = u**h *u.
                 do j = 1,n,nb
                    ! update and factorize the current diagonal block and test
                    ! for non-positive-definiteness.
                    jb = min(nb,n - j + 1)
                    call la_cherk('UPPER','CONJUGATE TRANSPOSE',jb,j - 1,-one,a(1,j), &
                              lda,one,a(j,j),lda)
                    call la_cpotrf2('UPPER',jb,a(j,j),lda,info)
                    if (info /= 0) go to 30
                    if (j + jb <= n) then
                       ! compute the current block row.
                       call la_cgemm('CONJUGATE TRANSPOSE','NO TRANSPOSE',jb,n - j - jb + 1,j - 1, &
                                  -cone,a(1,j),lda,a(1,j + jb),lda,cone,a(j,j + jb),lda)
                       call la_ctrsm('LEFT','UPPER','CONJUGATE TRANSPOSE','NON-UNIT',jb, &
                                 n - j - jb + 1,cone,a(j,j),lda,a(j,j + jb),lda)
                    end if
                 end do
              else
                 ! compute the cholesky factorization a = l*l**h.
                 do j = 1,n,nb
                    ! update and factorize the current diagonal block and test
                    ! for non-positive-definiteness.
                    jb = min(nb,n - j + 1)
                    call la_cherk('LOWER','NO TRANSPOSE',jb,j - 1,-one,a(j,1),lda,one, &
                               a(j,j),lda)
                    call la_cpotrf2('LOWER',jb,a(j,j),lda,info)
                    if (info /= 0) go to 30
                    if (j + jb <= n) then
                       ! compute the current block column.
                       call la_cgemm('NO TRANSPOSE','CONJUGATE TRANSPOSE',n - j - jb + 1,jb,j - 1, &
                                  -cone,a(j + jb,1),lda,a(j,1),lda,cone,a(j + jb,j),lda)
                       call la_ctrsm('RIGHT','LOWER','CONJUGATE TRANSPOSE','NON-UNIT',n - j - &
                                 jb + 1,jb,cone,a(j,j),lda,a(j + jb,j),lda)
                    end if
                 end do
              end if
           end if
           go to 40
           30 continue
           info = info + j - 1
           40 continue
           return
     end subroutine la_cpotrf
