     !> CPTTRS: solves a tridiagonal system of the form
     !> A * X = B
     !> using the factorization A = U**H*D*U or A = L*D*L**H computed by CPTTRF.
     !> D is a diagonal matrix specified in the vector D, U (or L) is a unit
     !> bidiagonal matrix whose superdiagonal (subdiagonal) is specified in
     !> the vector E, and X and B are N by NRHS matrices.

     pure subroutine la_cpttrs(uplo,n,nrhs,d,e,b,ldb,info)
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: uplo
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: ldb,n,nrhs
           ! Array Arguments
           real(sp),intent(in) :: d(*)
           complex(sp),intent(inout) :: b(ldb,*)
           complex(sp),intent(in) :: e(*)
        ! =====================================================================
           ! Local Scalars
           logical(lk) :: upper
           integer(ilp) :: iuplo,j,jb,nb
           ! Intrinsic Functions
           intrinsic :: max,min
           ! Executable Statements
           ! test the input arguments.
           info = 0
           upper = (uplo == 'U' .or. uplo == 'U')
           if (.not. upper .and. .not. (uplo == 'L' .or. uplo == 'L')) then
              info = -1
           else if (n < 0) then
              info = -2
           else if (nrhs < 0) then
              info = -3
           else if (ldb < max(1,n)) then
              info = -7
           end if
           if (info /= 0) then
              call la_xerbla('CPTTRS',-info)
              return
           end if
           ! quick return if possible
           if (n == 0 .or. nrhs == 0) return
           ! determine the number of right-hand sides to solve at a time.
           if (nrhs == 1) then
              nb = 1
           else
              nb = max(1,la_ilaenv(1,'CPTTRS',uplo,n,nrhs,-1,-1))
           end if
           ! decode uplo
           if (upper) then
              iuplo = 1
           else
              iuplo = 0
           end if
           if (nb >= nrhs) then
              call la_cptts2(iuplo,n,nrhs,d,e,b,ldb)
           else
              do j = 1,nrhs,nb
                 jb = min(nrhs - j + 1,nb)
                 call la_cptts2(iuplo,n,jb,d,e,b(1,j),ldb)
              end do
           end if
           return
     end subroutine la_cpttrs
