#ifdef LA_WITH_QP
     !> WPTTRS: solves a tridiagonal system of the form
     !> A * X = B
     !> using the factorization A = U**H *D* U or A = L*D*L**H computed by WPTTRF.
     !> D is a diagonal matrix specified in the vector D, U (or L) is a unit
     !> bidiagonal matrix whose superdiagonal (subdiagonal) is specified in
     !> the vector E, and X and B are N by NRHS matrices.

     pure subroutine la_wpttrs(uplo,n,nrhs,d,e,b,ldb,info)
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: uplo
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: ldb,n,nrhs
           ! Array Arguments
           real(qp),intent(in) :: d(*)
           complex(qp),intent(inout) :: b(ldb,*)
           complex(qp),intent(in) :: e(*)
        ! =====================================================================
           ! Local Scalars
           logical(lk) :: upper
           integer(ilp) :: iuplo,j,jb,nb
           ! Intrinsic Functions
           intrinsic :: max,min
           ! Executable Statements
           ! test the input arguments.
           info = 0
           upper = (uplo == 'U' .or. uplo == 'U')
           if (.not. upper .and. .not. (uplo == 'L' .or. uplo == 'L')) then
              info = -1
           else if (n < 0) then
              info = -2
           else if (nrhs < 0) then
              info = -3
           else if (ldb < max(1,n)) then
              info = -7
           end if
           if (info /= 0) then
              call la_xerbla('WPTTRS',-info)
              return
           end if
           ! quick return if possible
           if (n == 0 .or. nrhs == 0) return
           ! determine the number of right-hand sides to solve at a time.
           if (nrhs == 1) then
              nb = 1
           else
              nb = max(1,la_ilaenv(1,'WPTTRS',uplo,n,nrhs,-1,-1))
           end if
           ! decode uplo
           if (upper) then
              iuplo = 1
           else
              iuplo = 0
           end if
           if (nb >= nrhs) then
              call la_wptts2(iuplo,n,nrhs,d,e,b,ldb)
           else
              do j = 1,nrhs,nb
                 jb = min(nrhs - j + 1,nb)
                 call la_wptts2(iuplo,n,jb,d,e,b(1,j),ldb)
              end do
           end if
           return
     end subroutine la_wpttrs
#endif

     !> CPFTRF: computes the Cholesky factorization of a complex Hermitian
     !> positive definite matrix A.
     !> The factorization has the form
     !> A = U**H * U,  if UPLO = 'U', or
     !> A = L  * L**H,  if UPLO = 'L',
     !> where U is an upper triangular matrix and L is lower triangular.
     !> This is the block version of the algorithm, calling Level 3 BLAS.

     pure subroutine la_cpftrf(transr,uplo,n,a,info)
        use la_constants_sp
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: transr,uplo
           integer(ilp),intent(in) :: n
           integer(ilp),intent(out) :: info
           ! Array Arguments
           complex(sp),intent(inout) :: a(0:*)
        ! =====================================================================

           ! Local Scalars
           logical(lk) :: lower,nisodd,normaltransr
           integer(ilp) :: n1,n2,k
           ! Intrinsic Functions
           intrinsic :: mod
           ! Executable Statements
           ! test the input parameters.
           info = 0
           normaltransr = la_lsame(transr,'N')
           lower = la_lsame(uplo,'L')
           if (.not. normaltransr .and. .not. la_lsame(transr,'C')) then
              info = -1
           else if (.not. lower .and. .not. la_lsame(uplo,'U')) then
              info = -2
           else if (n < 0) then
              info = -3
           end if
           if (info /= 0) then
              call la_xerbla('CPFTRF',-info)
              return
           end if
           ! quick return if possible
           if (n == 0) return
           ! if n is odd, set nisodd = .true.
           ! if n is even, set k = n/2 and nisodd = .false.
           if (mod(n,2) == 0) then
              k = n/2
              nisodd = .false.
           else
              nisodd = .true.
           end if
           ! set n1 and n2 depending on lower
           if (lower) then
              n2 = n/2
              n1 = n - n2
           else
              n1 = n/2
              n2 = n - n1
           end if
           ! start execution: there are eight cases
           if (nisodd) then
              ! n is odd
              if (normaltransr) then
                 ! n is odd and transr = 'n'
                 if (lower) then
                   ! srpa for lower, normal and n is odd ( a(0:n-1,0:n1-1) )
                   ! t1 -> a(0,0), t2 -> a(0,1), s -> a(n1,0)
                   ! t1 -> a(0), t2 -> a(n), s -> a(n1)
                    call la_cpotrf('L',n1,a(0),n,info)
                    if (info > 0) return
                    call la_ctrsm('R','L','C','N',n2,n1,cone,a(0),n,a(n1),n)

                    call la_cherk('U','N',n2,n1,-one,a(n1),n,one,a(n),n)
                    call la_cpotrf('U',n2,a(n),n,info)
                    if (info > 0) info = info + n1
                 else
                   ! srpa for upper, normal and n is odd ( a(0:n-1,0:n2-1)
                   ! t1 -> a(n1+1,0), t2 -> a(n1,0), s -> a(0,0)
                   ! t1 -> a(n2), t2 -> a(n1), s -> a(0)
                    call la_cpotrf('L',n1,a(n2),n,info)
                    if (info > 0) return
                    call la_ctrsm('L','L','N','N',n1,n2,cone,a(n2),n,a(0),n)

                    call la_cherk('U','C',n2,n1,-one,a(0),n,one,a(n1),n)
                    call la_cpotrf('U',n2,a(n1),n,info)
                    if (info > 0) info = info + n1
                 end if
              else
                 ! n is odd and transr = 'c'
                 if (lower) then
                    ! srpa for lower, transpose and n is odd
                    ! t1 -> a(0,0) , t2 -> a(1,0) , s -> a(0,n1)
                    ! t1 -> a(0+0) , t2 -> a(1+0) , s -> a(0+n1*n1); lda=n1
                    call la_cpotrf('U',n1,a(0),n1,info)
                    if (info > 0) return
                    call la_ctrsm('L','U','C','N',n1,n2,cone,a(0),n1,a(n1*n1), &
                              n1)
                    call la_cherk('L','C',n2,n1,-one,a(n1*n1),n1,one,a(1),n1)

                    call la_cpotrf('L',n2,a(1),n1,info)
                    if (info > 0) info = info + n1
                 else
                    ! srpa for upper, transpose and n is odd
                    ! t1 -> a(0,n1+1), t2 -> a(0,n1), s -> a(0,0)
                    ! t1 -> a(n2*n2), t2 -> a(n1*n2), s -> a(0); lda = n2
                    call la_cpotrf('U',n1,a(n2*n2),n2,info)
                    if (info > 0) return
                    call la_ctrsm('R','U','N','N',n2,n1,cone,a(n2*n2),n2,a(0), &
                              n2)
                    call la_cherk('L','N',n2,n1,-one,a(0),n2,one,a(n1*n2),n2)

                    call la_cpotrf('L',n2,a(n1*n2),n2,info)
                    if (info > 0) info = info + n1
                 end if
              end if
           else
              ! n is even
              if (normaltransr) then
                 ! n is even and transr = 'n'
                 if (lower) then
                    ! srpa for lower, normal, and n is even ( a(0:n,0:k-1) )
                    ! t1 -> a(1,0), t2 -> a(0,0), s -> a(k+1,0)
                    ! t1 -> a(1), t2 -> a(0), s -> a(k+1)
                    call la_cpotrf('L',k,a(1),n + 1,info)
                    if (info > 0) return
                    call la_ctrsm('R','L','C','N',k,k,cone,a(1),n + 1,a(k + 1),n + 1)

                    call la_cherk('U','N',k,k,-one,a(k + 1),n + 1,one,a(0),n + 1)

                    call la_cpotrf('U',k,a(0),n + 1,info)
                    if (info > 0) info = info + k
                 else
                    ! srpa for upper, normal, and n is even ( a(0:n,0:k-1) )
                    ! t1 -> a(k+1,0) ,  t2 -> a(k,0),   s -> a(0,0)
                    ! t1 -> a(k+1), t2 -> a(k), s -> a(0)
                    call la_cpotrf('L',k,a(k + 1),n + 1,info)
                    if (info > 0) return
                    call la_ctrsm('L','L','N','N',k,k,cone,a(k + 1),n + 1,a(0),n + 1)

                    call la_cherk('U','C',k,k,-one,a(0),n + 1,one,a(k),n + 1)

                    call la_cpotrf('U',k,a(k),n + 1,info)
                    if (info > 0) info = info + k
                 end if
              else
                 ! n is even and transr = 'c'
                 if (lower) then
                    ! srpa for lower, transpose and n is even (see paper)
                    ! t1 -> b(0,1), t2 -> b(0,0), s -> b(0,k+1)
                    ! t1 -> a(0+k), t2 -> a(0+0), s -> a(0+k*(k+1)); lda=k
                    call la_cpotrf('U',k,a(0 + k),k,info)
                    if (info > 0) return
                    call la_ctrsm('L','U','C','N',k,k,cone,a(k),n1,a(k*(k + 1)), &
                              k)
                    call la_cherk('L','C',k,k,-one,a(k*(k + 1)),k,one,a(0),k)

                    call la_cpotrf('L',k,a(0),k,info)
                    if (info > 0) info = info + k
                 else
                    ! srpa for upper, transpose and n is even (see paper)
                    ! t1 -> b(0,k+1),     t2 -> b(0,k),   s -> b(0,0)
                    ! t1 -> a(0+k*(k+1)), t2 -> a(0+k*k), s -> a(0+0)); lda=k
                    call la_cpotrf('U',k,a(k*(k + 1)),k,info)
                    if (info > 0) return
                    call la_ctrsm('R','U','N','N',k,k,cone,a(k*(k + 1)),k,a(0), &
                              k)
                    call la_cherk('L','N',k,k,-one,a(0),k,one,a(k*k),k)
                    call la_cpotrf('L',k,a(k*k),k,info)
                    if (info > 0) info = info + k
                 end if
              end if
           end if
           return
     end subroutine la_cpftrf
     !> ZPFTRF: computes the Cholesky factorization of a complex Hermitian
     !> positive definite matrix A.
     !> The factorization has the form
     !> A = U**H * U,  if UPLO = 'U', or
     !> A = L  * L**H,  if UPLO = 'L',
     !> where U is an upper triangular matrix and L is lower triangular.
     !> This is the block version of the algorithm, calling Level 3 BLAS.

     pure subroutine la_zpftrf(transr,uplo,n,a,info)
        use la_constants_dp
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: transr,uplo
           integer(ilp),intent(in) :: n
           integer(ilp),intent(out) :: info
           ! Array Arguments
           complex(dp),intent(inout) :: a(0:*)
        ! =====================================================================

           ! Local Scalars
           logical(lk) :: lower,nisodd,normaltransr
           integer(ilp) :: n1,n2,k
           ! Intrinsic Functions
           intrinsic :: mod
           ! Executable Statements
           ! test the input parameters.
           info = 0
           normaltransr = la_lsame(transr,'N')
           lower = la_lsame(uplo,'L')
           if (.not. normaltransr .and. .not. la_lsame(transr,'C')) then
              info = -1
           else if (.not. lower .and. .not. la_lsame(uplo,'U')) then
              info = -2
           else if (n < 0) then
              info = -3
           end if
           if (info /= 0) then
              call la_xerbla('ZPFTRF',-info)
              return
           end if
           ! quick return if possible
           if (n == 0) return
           ! if n is odd, set nisodd = .true.
           ! if n is even, set k = n/2 and nisodd = .false.
           if (mod(n,2) == 0) then
              k = n/2
              nisodd = .false.
           else
              nisodd = .true.
           end if
           ! set n1 and n2 depending on lower
           if (lower) then
              n2 = n/2
              n1 = n - n2
           else
              n1 = n/2
              n2 = n - n1
           end if
           ! start execution: there are eight cases
           if (nisodd) then
              ! n is odd
              if (normaltransr) then
                 ! n is odd and transr = 'n'
                 if (lower) then
                   ! srpa for lower, normal and n is odd ( a(0:n-1,0:n1-1) )
                   ! t1 -> a(0,0), t2 -> a(0,1), s -> a(n1,0)
                   ! t1 -> a(0), t2 -> a(n), s -> a(n1)
                    call la_zpotrf('L',n1,a(0),n,info)
                    if (info > 0) return
                    call la_ztrsm('R','L','C','N',n2,n1,cone,a(0),n,a(n1),n)

                    call la_zherk('U','N',n2,n1,-one,a(n1),n,one,a(n),n)
                    call la_zpotrf('U',n2,a(n),n,info)
                    if (info > 0) info = info + n1
                 else
                   ! srpa for upper, normal and n is odd ( a(0:n-1,0:n2-1)
                   ! t1 -> a(n1+1,0), t2 -> a(n1,0), s -> a(0,0)
                   ! t1 -> a(n2), t2 -> a(n1), s -> a(0)
                    call la_zpotrf('L',n1,a(n2),n,info)
                    if (info > 0) return
                    call la_ztrsm('L','L','N','N',n1,n2,cone,a(n2),n,a(0),n)

                    call la_zherk('U','C',n2,n1,-one,a(0),n,one,a(n1),n)
                    call la_zpotrf('U',n2,a(n1),n,info)
                    if (info > 0) info = info + n1
                 end if
              else
                 ! n is odd and transr = 'c'
                 if (lower) then
                    ! srpa for lower, transpose and n is odd
                    ! t1 -> a(0,0) , t2 -> a(1,0) , s -> a(0,n1)
                    ! t1 -> a(0+0) , t2 -> a(1+0) , s -> a(0+n1*n1); lda=n1
                    call la_zpotrf('U',n1,a(0),n1,info)
                    if (info > 0) return
                    call la_ztrsm('L','U','C','N',n1,n2,cone,a(0),n1,a(n1*n1), &
                              n1)
                    call la_zherk('L','C',n2,n1,-one,a(n1*n1),n1,one,a(1),n1)

                    call la_zpotrf('L',n2,a(1),n1,info)
                    if (info > 0) info = info + n1
                 else
                    ! srpa for upper, transpose and n is odd
                    ! t1 -> a(0,n1+1), t2 -> a(0,n1), s -> a(0,0)
                    ! t1 -> a(n2*n2), t2 -> a(n1*n2), s -> a(0); lda = n2
                    call la_zpotrf('U',n1,a(n2*n2),n2,info)
                    if (info > 0) return
                    call la_ztrsm('R','U','N','N',n2,n1,cone,a(n2*n2),n2,a(0), &
                              n2)
                    call la_zherk('L','N',n2,n1,-one,a(0),n2,one,a(n1*n2),n2)

                    call la_zpotrf('L',n2,a(n1*n2),n2,info)
                    if (info > 0) info = info + n1
                 end if
              end if
           else
              ! n is even
              if (normaltransr) then
                 ! n is even and transr = 'n'
                 if (lower) then
                    ! srpa for lower, normal, and n is even ( a(0:n,0:k-1) )
                    ! t1 -> a(1,0), t2 -> a(0,0), s -> a(k+1,0)
                    ! t1 -> a(1), t2 -> a(0), s -> a(k+1)
                    call la_zpotrf('L',k,a(1),n + 1,info)
                    if (info > 0) return
                    call la_ztrsm('R','L','C','N',k,k,cone,a(1),n + 1,a(k + 1),n + 1)

                    call la_zherk('U','N',k,k,-one,a(k + 1),n + 1,one,a(0),n + 1)

                    call la_zpotrf('U',k,a(0),n + 1,info)
                    if (info > 0) info = info + k
                 else
                    ! srpa for upper, normal, and n is even ( a(0:n,0:k-1) )
                    ! t1 -> a(k+1,0) ,  t2 -> a(k,0),   s -> a(0,0)
                    ! t1 -> a(k+1), t2 -> a(k), s -> a(0)
                    call la_zpotrf('L',k,a(k + 1),n + 1,info)
                    if (info > 0) return
                    call la_ztrsm('L','L','N','N',k,k,cone,a(k + 1),n + 1,a(0),n + 1)

                    call la_zherk('U','C',k,k,-one,a(0),n + 1,one,a(k),n + 1)

                    call la_zpotrf('U',k,a(k),n + 1,info)
                    if (info > 0) info = info + k
                 end if
              else
                 ! n is even and transr = 'c'
                 if (lower) then
                    ! srpa for lower, transpose and n is even (see paper)
                    ! t1 -> b(0,1), t2 -> b(0,0), s -> b(0,k+1)
                    ! t1 -> a(0+k), t2 -> a(0+0), s -> a(0+k*(k+1)); lda=k
                    call la_zpotrf('U',k,a(0 + k),k,info)
                    if (info > 0) return
                    call la_ztrsm('L','U','C','N',k,k,cone,a(k),n1,a(k*(k + 1)), &
                              k)
                    call la_zherk('L','C',k,k,-one,a(k*(k + 1)),k,one,a(0),k)

                    call la_zpotrf('L',k,a(0),k,info)
                    if (info > 0) info = info + k
                 else
                    ! srpa for upper, transpose and n is even (see paper)
                    ! t1 -> b(0,k+1),     t2 -> b(0,k),   s -> b(0,0)
                    ! t1 -> a(0+k*(k+1)), t2 -> a(0+k*k), s -> a(0+0)); lda=k
                    call la_zpotrf('U',k,a(k*(k + 1)),k,info)
                    if (info > 0) return
                    call la_ztrsm('R','U','N','N',k,k,cone,a(k*(k + 1)),k,a(0), &
                              k)
                    call la_zherk('L','N',k,k,-one,a(0),k,one,a(k*k),k)
                    call la_zpotrf('L',k,a(k*k),k,info)
                    if (info > 0) info = info + k
                 end if
              end if
           end if
           return
     end subroutine la_zpftrf
#ifdef LA_WITH_XDP
     !> YPFTRF: computes the Cholesky factorization of a complex Hermitian
     !> positive definite matrix A.
     !> The factorization has the form
     !> A = U**H * U,  if UPLO = 'U', or
     !> A = L  * L**H,  if UPLO = 'L',
     !> where U is an upper triangular matrix and L is lower triangular.
     !> This is the block version of the algorithm, calling Level 3 BLAS.

     pure subroutine la_ypftrf(transr,uplo,n,a,info)
        use la_constants_xdp
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: transr,uplo
           integer(ilp),intent(in) :: n
           integer(ilp),intent(out) :: info
           ! Array Arguments
           complex(xdp),intent(inout) :: a(0:*)
        ! =====================================================================

           ! Local Scalars
           logical(lk) :: lower,nisodd,normaltransr
           integer(ilp) :: n1,n2,k
           ! Intrinsic Functions
           intrinsic :: mod
           ! Executable Statements
           ! test the input parameters.
           info = 0
           normaltransr = la_lsame(transr,'N')
           lower = la_lsame(uplo,'L')
           if (.not. normaltransr .and. .not. la_lsame(transr,'C')) then
              info = -1
           else if (.not. lower .and. .not. la_lsame(uplo,'U')) then
              info = -2
           else if (n < 0) then
              info = -3
           end if
           if (info /= 0) then
              call la_xerbla('YPFTRF',-info)
              return
           end if
           ! quick return if possible
           if (n == 0) return
           ! if n is odd, set nisodd = .true.
           ! if n is even, set k = n/2 and nisodd = .false.
           if (mod(n,2) == 0) then
              k = n/2
              nisodd = .false.
           else
              nisodd = .true.
           end if
           ! set n1 and n2 depending on lower
           if (lower) then
              n2 = n/2
              n1 = n - n2
           else
              n1 = n/2
              n2 = n - n1
           end if
           ! start execution: there are eight cases
           if (nisodd) then
              ! n is odd
              if (normaltransr) then
                 ! n is odd and transr = 'n'
                 if (lower) then
                   ! srpa for lower, normal and n is odd ( a(0:n-1,0:n1-1) )
                   ! t1 -> a(0,0), t2 -> a(0,1), s -> a(n1,0)
                   ! t1 -> a(0), t2 -> a(n), s -> a(n1)
                    call la_ypotrf('L',n1,a(0),n,info)
                    if (info > 0) return
                    call la_ytrsm('R','L','C','N',n2,n1,cone,a(0),n,a(n1),n)

                    call la_yherk('U','N',n2,n1,-one,a(n1),n,one,a(n),n)
                    call la_ypotrf('U',n2,a(n),n,info)
                    if (info > 0) info = info + n1
                 else
                   ! srpa for upper, normal and n is odd ( a(0:n-1,0:n2-1)
                   ! t1 -> a(n1+1,0), t2 -> a(n1,0), s -> a(0,0)
                   ! t1 -> a(n2), t2 -> a(n1), s -> a(0)
                    call la_ypotrf('L',n1,a(n2),n,info)
                    if (info > 0) return
                    call la_ytrsm('L','L','N','N',n1,n2,cone,a(n2),n,a(0),n)

                    call la_yherk('U','C',n2,n1,-one,a(0),n,one,a(n1),n)
                    call la_ypotrf('U',n2,a(n1),n,info)
                    if (info > 0) info = info + n1
                 end if
              else
                 ! n is odd and transr = 'c'
                 if (lower) then
                    ! srpa for lower, transpose and n is odd
                    ! t1 -> a(0,0) , t2 -> a(1,0) , s -> a(0,n1)
                    ! t1 -> a(0+0) , t2 -> a(1+0) , s -> a(0+n1*n1); lda=n1
                    call la_ypotrf('U',n1,a(0),n1,info)
                    if (info > 0) return
                    call la_ytrsm('L','U','C','N',n1,n2,cone,a(0),n1,a(n1*n1), &
                              n1)
                    call la_yherk('L','C',n2,n1,-one,a(n1*n1),n1,one,a(1),n1)

                    call la_ypotrf('L',n2,a(1),n1,info)
                    if (info > 0) info = info + n1
                 else
                    ! srpa for upper, transpose and n is odd
                    ! t1 -> a(0,n1+1), t2 -> a(0,n1), s -> a(0,0)
                    ! t1 -> a(n2*n2), t2 -> a(n1*n2), s -> a(0); lda = n2
                    call la_ypotrf('U',n1,a(n2*n2),n2,info)
                    if (info > 0) return
                    call la_ytrsm('R','U','N','N',n2,n1,cone,a(n2*n2),n2,a(0), &
                              n2)
                    call la_yherk('L','N',n2,n1,-one,a(0),n2,one,a(n1*n2),n2)

                    call la_ypotrf('L',n2,a(n1*n2),n2,info)
                    if (info > 0) info = info + n1
                 end if
              end if
           else
              ! n is even
              if (normaltransr) then
                 ! n is even and transr = 'n'
                 if (lower) then
                    ! srpa for lower, normal, and n is even ( a(0:n,0:k-1) )
                    ! t1 -> a(1,0), t2 -> a(0,0), s -> a(k+1,0)
                    ! t1 -> a(1), t2 -> a(0), s -> a(k+1)
                    call la_ypotrf('L',k,a(1),n + 1,info)
                    if (info > 0) return
                    call la_ytrsm('R','L','C','N',k,k,cone,a(1),n + 1,a(k + 1),n + 1)

                    call la_yherk('U','N',k,k,-one,a(k + 1),n + 1,one,a(0),n + 1)

                    call la_ypotrf('U',k,a(0),n + 1,info)
                    if (info > 0) info = info + k
                 else
                    ! srpa for upper, normal, and n is even ( a(0:n,0:k-1) )
                    ! t1 -> a(k+1,0) ,  t2 -> a(k,0),   s -> a(0,0)
                    ! t1 -> a(k+1), t2 -> a(k), s -> a(0)
                    call la_ypotrf('L',k,a(k + 1),n + 1,info)
                    if (info > 0) return
                    call la_ytrsm('L','L','N','N',k,k,cone,a(k + 1),n + 1,a(0),n + 1)

                    call la_yherk('U','C',k,k,-one,a(0),n + 1,one,a(k),n + 1)

                    call la_ypotrf('U',k,a(k),n + 1,info)
                    if (info > 0) info = info + k
                 end if
              else
                 ! n is even and transr = 'c'
                 if (lower) then
                    ! srpa for lower, transpose and n is even (see paper)
                    ! t1 -> b(0,1), t2 -> b(0,0), s -> b(0,k+1)
                    ! t1 -> a(0+k), t2 -> a(0+0), s -> a(0+k*(k+1)); lda=k
                    call la_ypotrf('U',k,a(0 + k),k,info)
                    if (info > 0) return
                    call la_ytrsm('L','U','C','N',k,k,cone,a(k),n1,a(k*(k + 1)), &
                              k)
                    call la_yherk('L','C',k,k,-one,a(k*(k + 1)),k,one,a(0),k)

                    call la_ypotrf('L',k,a(0),k,info)
                    if (info > 0) info = info + k
                 else
                    ! srpa for upper, transpose and n is even (see paper)
                    ! t1 -> b(0,k+1),     t2 -> b(0,k),   s -> b(0,0)
                    ! t1 -> a(0+k*(k+1)), t2 -> a(0+k*k), s -> a(0+0)); lda=k
                    call la_ypotrf('U',k,a(k*(k + 1)),k,info)
                    if (info > 0) return
                    call la_ytrsm('R','U','N','N',k,k,cone,a(k*(k + 1)),k,a(0), &
                              k)
                    call la_yherk('L','N',k,k,-one,a(0),k,one,a(k*k),k)
                    call la_ypotrf('L',k,a(k*k),k,info)
                    if (info > 0) info = info + k
                 end if
              end if
           end if
           return
     end subroutine la_ypftrf
#endif
#ifdef LA_WITH_QP
     !> WPFTRF: computes the Cholesky factorization of a complex Hermitian
     !> positive definite matrix A.
     !> The factorization has the form
     !> A = U**H * U,  if UPLO = 'U', or
     !> A = L  * L**H,  if UPLO = 'L',
     !> where U is an upper triangular matrix and L is lower triangular.
     !> This is the block version of the algorithm, calling Level 3 BLAS.

     pure subroutine la_wpftrf(transr,uplo,n,a,info)
        use la_constants_qp
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: transr,uplo
           integer(ilp),intent(in) :: n
           integer(ilp),intent(out) :: info
           ! Array Arguments
           complex(qp),intent(inout) :: a(0:*)
        ! =====================================================================

           ! Local Scalars
           logical(lk) :: lower,nisodd,normaltransr
           integer(ilp) :: n1,n2,k
           ! Intrinsic Functions
           intrinsic :: mod
           ! Executable Statements
           ! test the input parameters.
           info = 0
           normaltransr = la_lsame(transr,'N')
           lower = la_lsame(uplo,'L')
           if (.not. normaltransr .and. .not. la_lsame(transr,'C')) then
              info = -1
           else if (.not. lower .and. .not. la_lsame(uplo,'U')) then
              info = -2
           else if (n < 0) then
              info = -3
           end if
           if (info /= 0) then
              call la_xerbla('WPFTRF',-info)
              return
           end if
           ! quick return if possible
           if (n == 0) return
           ! if n is odd, set nisodd = .true.
           ! if n is even, set k = n/2 and nisodd = .false.
           if (mod(n,2) == 0) then
              k = n/2
              nisodd = .false.
           else
              nisodd = .true.
           end if
           ! set n1 and n2 depending on lower
           if (lower) then
              n2 = n/2
              n1 = n - n2
           else
              n1 = n/2
              n2 = n - n1
           end if
           ! start execution: there are eight cases
           if (nisodd) then
              ! n is odd
              if (normaltransr) then
                 ! n is odd and transr = 'n'
                 if (lower) then
                   ! srpa for lower, normal and n is odd ( a(0:n-1,0:n1-1) )
                   ! t1 -> a(0,0), t2 -> a(0,1), s -> a(n1,0)
                   ! t1 -> a(0), t2 -> a(n), s -> a(n1)
                    call la_wpotrf('L',n1,a(0),n,info)
                    if (info > 0) return
                    call la_wtrsm('R','L','C','N',n2,n1,cone,a(0),n,a(n1),n)

                    call la_wherk('U','N',n2,n1,-one,a(n1),n,one,a(n),n)
                    call la_wpotrf('U',n2,a(n),n,info)
                    if (info > 0) info = info + n1
                 else
                   ! srpa for upper, normal and n is odd ( a(0:n-1,0:n2-1)
                   ! t1 -> a(n1+1,0), t2 -> a(n1,0), s -> a(0,0)
                   ! t1 -> a(n2), t2 -> a(n1), s -> a(0)
                    call la_wpotrf('L',n1,a(n2),n,info)
                    if (info > 0) return
                    call la_wtrsm('L','L','N','N',n1,n2,cone,a(n2),n,a(0),n)

                    call la_wherk('U','C',n2,n1,-one,a(0),n,one,a(n1),n)
                    call la_wpotrf('U',n2,a(n1),n,info)
                    if (info > 0) info = info + n1
                 end if
              else
                 ! n is odd and transr = 'c'
                 if (lower) then
                    ! srpa for lower, transpose and n is odd
                    ! t1 -> a(0,0) , t2 -> a(1,0) , s -> a(0,n1)
                    ! t1 -> a(0+0) , t2 -> a(1+0) , s -> a(0+n1*n1); lda=n1
                    call la_wpotrf('U',n1,a(0),n1,info)
                    if (info > 0) return
                    call la_wtrsm('L','U','C','N',n1,n2,cone,a(0),n1,a(n1*n1), &
                              n1)
                    call la_wherk('L','C',n2,n1,-one,a(n1*n1),n1,one,a(1),n1)

                    call la_wpotrf('L',n2,a(1),n1,info)
                    if (info > 0) info = info + n1
                 else
                    ! srpa for upper, transpose and n is odd
                    ! t1 -> a(0,n1+1), t2 -> a(0,n1), s -> a(0,0)
                    ! t1 -> a(n2*n2), t2 -> a(n1*n2), s -> a(0); lda = n2
                    call la_wpotrf('U',n1,a(n2*n2),n2,info)
                    if (info > 0) return
                    call la_wtrsm('R','U','N','N',n2,n1,cone,a(n2*n2),n2,a(0), &
                              n2)
                    call la_wherk('L','N',n2,n1,-one,a(0),n2,one,a(n1*n2),n2)

                    call la_wpotrf('L',n2,a(n1*n2),n2,info)
                    if (info > 0) info = info + n1
                 end if
              end if
           else
              ! n is even
              if (normaltransr) then
                 ! n is even and transr = 'n'
                 if (lower) then
                    ! srpa for lower, normal, and n is even ( a(0:n,0:k-1) )
                    ! t1 -> a(1,0), t2 -> a(0,0), s -> a(k+1,0)
                    ! t1 -> a(1), t2 -> a(0), s -> a(k+1)
                    call la_wpotrf('L',k,a(1),n + 1,info)
                    if (info > 0) return
                    call la_wtrsm('R','L','C','N',k,k,cone,a(1),n + 1,a(k + 1),n + 1)

                    call la_wherk('U','N',k,k,-one,a(k + 1),n + 1,one,a(0),n + 1)

                    call la_wpotrf('U',k,a(0),n + 1,info)
                    if (info > 0) info = info + k
                 else
                    ! srpa for upper, normal, and n is even ( a(0:n,0:k-1) )
                    ! t1 -> a(k+1,0) ,  t2 -> a(k,0),   s -> a(0,0)
                    ! t1 -> a(k+1), t2 -> a(k), s -> a(0)
                    call la_wpotrf('L',k,a(k + 1),n + 1,info)
                    if (info > 0) return
                    call la_wtrsm('L','L','N','N',k,k,cone,a(k + 1),n + 1,a(0),n + 1)

                    call la_wherk('U','C',k,k,-one,a(0),n + 1,one,a(k),n + 1)

                    call la_wpotrf('U',k,a(k),n + 1,info)
                    if (info > 0) info = info + k
                 end if
              else
                 ! n is even and transr = 'c'
                 if (lower) then
                    ! srpa for lower, transpose and n is even (see paper)
                    ! t1 -> b(0,1), t2 -> b(0,0), s -> b(0,k+1)
                    ! t1 -> a(0+k), t2 -> a(0+0), s -> a(0+k*(k+1)); lda=k
                    call la_wpotrf('U',k,a(0 + k),k,info)
                    if (info > 0) return
                    call la_wtrsm('L','U','C','N',k,k,cone,a(k),n1,a(k*(k + 1)), &
                              k)
                    call la_wherk('L','C',k,k,-one,a(k*(k + 1)),k,one,a(0),k)

                    call la_wpotrf('L',k,a(0),k,info)
                    if (info > 0) info = info + k
                 else
                    ! srpa for upper, transpose and n is even (see paper)
                    ! t1 -> b(0,k+1),     t2 -> b(0,k),   s -> b(0,0)
                    ! t1 -> a(0+k*(k+1)), t2 -> a(0+k*k), s -> a(0+0)); lda=k
                    call la_wpotrf('U',k,a(k*(k + 1)),k,info)
                    if (info > 0) return
                    call la_wtrsm('R','U','N','N',k,k,cone,a(k*(k + 1)),k,a(0), &
                              k)
                    call la_wherk('L','N',k,k,-one,a(0),k,one,a(k*k),k)
                    call la_wpotrf('L',k,a(k*k),k,info)
                    if (info > 0) info = info + k
                 end if
              end if
           end if
           return
     end subroutine la_wpftrf
#endif

     !> CPFTRI: computes the inverse of a complex Hermitian positive definite
     !> matrix A using the Cholesky factorization A = U**H*U or A = L*L**H
     !> computed by CPFTRF.

     pure subroutine la_cpftri(transr,uplo,n,a,info)
        use la_constants_sp
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: transr,uplo
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: n
           ! Array Arguments
           complex(sp),intent(inout) :: a(0:*)
        ! =====================================================================

           ! Local Scalars
           logical(lk) :: lower,nisodd,normaltransr
           integer(ilp) :: n1,n2,k
           ! Intrinsic Functions
           intrinsic :: mod
           ! Executable Statements
           ! test the input parameters.
           info = 0
           normaltransr = la_lsame(transr,'N')
           lower = la_lsame(uplo,'L')
           if (.not. normaltransr .and. .not. la_lsame(transr,'C')) then
              info = -1
           else if (.not. lower .and. .not. la_lsame(uplo,'U')) then
              info = -2
           else if (n < 0) then
              info = -3
           end if
           if (info /= 0) then
              call la_xerbla('CPFTRI',-info)
              return
           end if
           ! quick return if possible
           if (n == 0) return
           ! invert the triangular cholesky factor u or l.
           call la_ctftri(transr,uplo,'N',n,a,info)
           if (info > 0) return
           ! if n is odd, set nisodd = .true.
           ! if n is even, set k = n/2 and nisodd = .false.
           if (mod(n,2) == 0) then
              k = n/2
              nisodd = .false.
           else
              nisodd = .true.
           end if
           ! set n1 and n2 depending on lower
           if (lower) then
              n2 = n/2
              n1 = n - n2
           else
              n1 = n/2
              n2 = n - n1
           end if
           ! start execution of triangular matrix multiply: inv(u)*inv(u)^c or
           ! inv(l)^c*inv(l). there are eight cases.
           if (nisodd) then
              ! n is odd
              if (normaltransr) then
                 ! n is odd and transr = 'n'
                 if (lower) then
                    ! srpa for lower, normal and n is odd ( a(0:n-1,0:n1-1) )
                    ! t1 -> a(0,0), t2 -> a(0,1), s -> a(n1,0)
                    ! t1 -> a(0), t2 -> a(n), s -> a(n1)
                    call la_clauum('L',n1,a(0),n,info)
                    call la_cherk('L','C',n1,n2,one,a(n1),n,one,a(0),n)
                    call la_ctrmm('L','U','N','N',n2,n1,cone,a(n),n,a(n1),n)

                    call la_clauum('U',n2,a(n),n,info)
                 else
                    ! srpa for upper, normal and n is odd ( a(0:n-1,0:n2-1)
                    ! t1 -> a(n1+1,0), t2 -> a(n1,0), s -> a(0,0)
                    ! t1 -> a(n2), t2 -> a(n1), s -> a(0)
                    call la_clauum('L',n1,a(n2),n,info)
                    call la_cherk('L','N',n1,n2,one,a(0),n,one,a(n2),n)
                    call la_ctrmm('R','U','C','N',n1,n2,cone,a(n1),n,a(0),n)

                    call la_clauum('U',n2,a(n1),n,info)
                 end if
              else
                 ! n is odd and transr = 'c'
                 if (lower) then
                    ! srpa for lower, transpose, and n is odd
                    ! t1 -> a(0), t2 -> a(1), s -> a(0+n1*n1)
                    call la_clauum('U',n1,a(0),n1,info)
                    call la_cherk('U','N',n1,n2,one,a(n1*n1),n1,one,a(0),n1)

                    call la_ctrmm('R','L','N','N',n1,n2,cone,a(1),n1,a(n1*n1), &
                              n1)
                    call la_clauum('L',n2,a(1),n1,info)
                 else
                    ! srpa for upper, transpose, and n is odd
                    ! t1 -> a(0+n2*n2), t2 -> a(0+n1*n2), s -> a(0)
                    call la_clauum('U',n1,a(n2*n2),n2,info)
                    call la_cherk('U','C',n1,n2,one,a(0),n2,one,a(n2*n2),n2)

                    call la_ctrmm('L','L','C','N',n2,n1,cone,a(n1*n2),n2,a(0), &
                              n2)
                    call la_clauum('L',n2,a(n1*n2),n2,info)
                 end if
              end if
           else
              ! n is even
              if (normaltransr) then
                 ! n is even and transr = 'n'
                 if (lower) then
                    ! srpa for lower, normal, and n is even ( a(0:n,0:k-1) )
                    ! t1 -> a(1,0), t2 -> a(0,0), s -> a(k+1,0)
                    ! t1 -> a(1), t2 -> a(0), s -> a(k+1)
                    call la_clauum('L',k,a(1),n + 1,info)
                    call la_cherk('L','C',k,k,one,a(k + 1),n + 1,one,a(1),n + 1)

                    call la_ctrmm('L','U','N','N',k,k,cone,a(0),n + 1,a(k + 1),n + 1)

                    call la_clauum('U',k,a(0),n + 1,info)
                 else
                    ! srpa for upper, normal, and n is even ( a(0:n,0:k-1) )
                    ! t1 -> a(k+1,0) ,  t2 -> a(k,0),   s -> a(0,0)
                    ! t1 -> a(k+1), t2 -> a(k), s -> a(0)
                    call la_clauum('L',k,a(k + 1),n + 1,info)
                    call la_cherk('L','N',k,k,one,a(0),n + 1,one,a(k + 1),n + 1)

                    call la_ctrmm('R','U','C','N',k,k,cone,a(k),n + 1,a(0),n + 1)

                    call la_clauum('U',k,a(k),n + 1,info)
                 end if
              else
                 ! n is even and transr = 'c'
                 if (lower) then
                    ! srpa for lower, transpose, and n is even (see paper)
                    ! t1 -> b(0,1), t2 -> b(0,0), s -> b(0,k+1),
                    ! t1 -> a(0+k), t2 -> a(0+0), s -> a(0+k*(k+1)); lda=k
                    call la_clauum('U',k,a(k),k,info)
                    call la_cherk('U','N',k,k,one,a(k*(k + 1)),k,one,a(k),k)

                    call la_ctrmm('R','L','N','N',k,k,cone,a(0),k,a(k*(k + 1)), &
                              k)
                    call la_clauum('L',k,a(0),k,info)
                 else
                    ! srpa for upper, transpose, and n is even (see paper)
                    ! t1 -> b(0,k+1),     t2 -> b(0,k),   s -> b(0,0),
                    ! t1 -> a(0+k*(k+1)), t2 -> a(0+k*k), s -> a(0+0)); lda=k
                    call la_clauum('U',k,a(k*(k + 1)),k,info)
                    call la_cherk('U','C',k,k,one,a(0),k,one,a(k*(k + 1)),k)

                    call la_ctrmm('L','L','C','N',k,k,cone,a(k*k),k,a(0),k)

                    call la_clauum('L',k,a(k*k),k,info)
                 end if
              end if
           end if
           return
     end subroutine la_cpftri
     !> ZPFTRI: computes the inverse of a complex Hermitian positive definite
     !> matrix A using the Cholesky factorization A = U**H*U or A = L*L**H
     !> computed by ZPFTRF.

     pure subroutine la_zpftri(transr,uplo,n,a,info)
        use la_constants_dp
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: transr,uplo
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: n
           ! Array Arguments
           complex(dp),intent(inout) :: a(0:*)
        ! =====================================================================

           ! Local Scalars
           logical(lk) :: lower,nisodd,normaltransr
           integer(ilp) :: n1,n2,k
           ! Intrinsic Functions
           intrinsic :: mod
           ! Executable Statements
           ! test the input parameters.
           info = 0
           normaltransr = la_lsame(transr,'N')
           lower = la_lsame(uplo,'L')
           if (.not. normaltransr .and. .not. la_lsame(transr,'C')) then
              info = -1
           else if (.not. lower .and. .not. la_lsame(uplo,'U')) then
              info = -2
           else if (n < 0) then
              info = -3
           end if
           if (info /= 0) then
              call la_xerbla('ZPFTRI',-info)
              return
           end if
           ! quick return if possible
           if (n == 0) return
           ! invert the triangular cholesky factor u or l.
           call la_ztftri(transr,uplo,'N',n,a,info)
           if (info > 0) return
           ! if n is odd, set nisodd = .true.
           ! if n is even, set k = n/2 and nisodd = .false.
           if (mod(n,2) == 0) then
              k = n/2
              nisodd = .false.
           else
              nisodd = .true.
           end if
           ! set n1 and n2 depending on lower
           if (lower) then
              n2 = n/2
              n1 = n - n2
           else
              n1 = n/2
              n2 = n - n1
           end if
           ! start execution of triangular matrix multiply: inv(u)*inv(u)^c or
           ! inv(l)^c*inv(l). there are eight cases.
           if (nisodd) then
              ! n is odd
              if (normaltransr) then
                 ! n is odd and transr = 'n'
                 if (lower) then
                    ! srpa for lower, normal and n is odd ( a(0:n-1,0:n1-1) )
                    ! t1 -> a(0,0), t2 -> a(0,1), s -> a(n1,0)
                    ! t1 -> a(0), t2 -> a(n), s -> a(n1)
                    call la_zlauum('L',n1,a(0),n,info)
                    call la_zherk('L','C',n1,n2,one,a(n1),n,one,a(0),n)
                    call la_ztrmm('L','U','N','N',n2,n1,cone,a(n),n,a(n1),n)

                    call la_zlauum('U',n2,a(n),n,info)
                 else
                    ! srpa for upper, normal and n is odd ( a(0:n-1,0:n2-1)
                    ! t1 -> a(n1+1,0), t2 -> a(n1,0), s -> a(0,0)
                    ! t1 -> a(n2), t2 -> a(n1), s -> a(0)
                    call la_zlauum('L',n1,a(n2),n,info)
                    call la_zherk('L','N',n1,n2,one,a(0),n,one,a(n2),n)
                    call la_ztrmm('R','U','C','N',n1,n2,cone,a(n1),n,a(0),n)

                    call la_zlauum('U',n2,a(n1),n,info)
                 end if
              else
                 ! n is odd and transr = 'c'
                 if (lower) then
                    ! srpa for lower, transpose, and n is odd
                    ! t1 -> a(0), t2 -> a(1), s -> a(0+n1*n1)
                    call la_zlauum('U',n1,a(0),n1,info)
                    call la_zherk('U','N',n1,n2,one,a(n1*n1),n1,one,a(0),n1)

                    call la_ztrmm('R','L','N','N',n1,n2,cone,a(1),n1,a(n1*n1), &
                              n1)
                    call la_zlauum('L',n2,a(1),n1,info)
                 else
                    ! srpa for upper, transpose, and n is odd
                    ! t1 -> a(0+n2*n2), t2 -> a(0+n1*n2), s -> a(0)
                    call la_zlauum('U',n1,a(n2*n2),n2,info)
                    call la_zherk('U','C',n1,n2,one,a(0),n2,one,a(n2*n2),n2)

                    call la_ztrmm('L','L','C','N',n2,n1,cone,a(n1*n2),n2,a(0), &
                              n2)
                    call la_zlauum('L',n2,a(n1*n2),n2,info)
                 end if
              end if
           else
              ! n is even
              if (normaltransr) then
                 ! n is even and transr = 'n'
                 if (lower) then
                    ! srpa for lower, normal, and n is even ( a(0:n,0:k-1) )
                    ! t1 -> a(1,0), t2 -> a(0,0), s -> a(k+1,0)
                    ! t1 -> a(1), t2 -> a(0), s -> a(k+1)
                    call la_zlauum('L',k,a(1),n + 1,info)
                    call la_zherk('L','C',k,k,one,a(k + 1),n + 1,one,a(1),n + 1)

                    call la_ztrmm('L','U','N','N',k,k,cone,a(0),n + 1,a(k + 1),n + 1)

                    call la_zlauum('U',k,a(0),n + 1,info)
                 else
                    ! srpa for upper, normal, and n is even ( a(0:n,0:k-1) )
                    ! t1 -> a(k+1,0) ,  t2 -> a(k,0),   s -> a(0,0)
                    ! t1 -> a(k+1), t2 -> a(k), s -> a(0)
                    call la_zlauum('L',k,a(k + 1),n + 1,info)
                    call la_zherk('L','N',k,k,one,a(0),n + 1,one,a(k + 1),n + 1)

                    call la_ztrmm('R','U','C','N',k,k,cone,a(k),n + 1,a(0),n + 1)

                    call la_zlauum('U',k,a(k),n + 1,info)
                 end if
              else
                 ! n is even and transr = 'c'
                 if (lower) then
                    ! srpa for lower, transpose, and n is even (see paper)
                    ! t1 -> b(0,1), t2 -> b(0,0), s -> b(0,k+1),
                    ! t1 -> a(0+k), t2 -> a(0+0), s -> a(0+k*(k+1)); lda=k
                    call la_zlauum('U',k,a(k),k,info)
                    call la_zherk('U','N',k,k,one,a(k*(k + 1)),k,one,a(k),k)

                    call la_ztrmm('R','L','N','N',k,k,cone,a(0),k,a(k*(k + 1)), &
                              k)
                    call la_zlauum('L',k,a(0),k,info)
                 else
                    ! srpa for upper, transpose, and n is even (see paper)
                    ! t1 -> b(0,k+1),     t2 -> b(0,k),   s -> b(0,0),
                    ! t1 -> a(0+k*(k+1)), t2 -> a(0+k*k), s -> a(0+0)); lda=k
                    call la_zlauum('U',k,a(k*(k + 1)),k,info)
                    call la_zherk('U','C',k,k,one,a(0),k,one,a(k*(k + 1)),k)

                    call la_ztrmm('L','L','C','N',k,k,cone,a(k*k),k,a(0),k)

                    call la_zlauum('L',k,a(k*k),k,info)
                 end if
              end if
           end if
           return
     end subroutine la_zpftri
#ifdef LA_WITH_XDP
     !> YPFTRI: computes the inverse of a complex Hermitian positive definite
     !> matrix A using the Cholesky factorization A = U**H*U or A = L*L**H
     !> computed by YPFTRF.

     pure subroutine la_ypftri(transr,uplo,n,a,info)
        use la_constants_xdp
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: transr,uplo
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: n
           ! Array Arguments
           complex(xdp),intent(inout) :: a(0:*)
        ! =====================================================================

           ! Local Scalars
           logical(lk) :: lower,nisodd,normaltransr
           integer(ilp) :: n1,n2,k
           ! Intrinsic Functions
           intrinsic :: mod
           ! Executable Statements
           ! test the input parameters.
           info = 0
           normaltransr = la_lsame(transr,'N')
           lower = la_lsame(uplo,'L')
           if (.not. normaltransr .and. .not. la_lsame(transr,'C')) then
              info = -1
           else if (.not. lower .and. .not. la_lsame(uplo,'U')) then
              info = -2
           else if (n < 0) then
              info = -3
           end if
           if (info /= 0) then
              call la_xerbla('YPFTRI',-info)
              return
           end if
           ! quick return if possible
           if (n == 0) return
           ! invert the triangular cholesky factor u or l.
           call la_ytftri(transr,uplo,'N',n,a,info)
           if (info > 0) return
           ! if n is odd, set nisodd = .true.
           ! if n is even, set k = n/2 and nisodd = .false.
           if (mod(n,2) == 0) then
              k = n/2
              nisodd = .false.
           else
              nisodd = .true.
           end if
           ! set n1 and n2 depending on lower
           if (lower) then
              n2 = n/2
              n1 = n - n2
           else
              n1 = n/2
              n2 = n - n1
           end if
           ! start execution of triangular matrix multiply: inv(u)*inv(u)^c or
           ! inv(l)^c*inv(l). there are eight cases.
           if (nisodd) then
              ! n is odd
              if (normaltransr) then
                 ! n is odd and transr = 'n'
                 if (lower) then
                    ! srpa for lower, normal and n is odd ( a(0:n-1,0:n1-1) )
                    ! t1 -> a(0,0), t2 -> a(0,1), s -> a(n1,0)
                    ! t1 -> a(0), t2 -> a(n), s -> a(n1)
                    call la_ylauum('L',n1,a(0),n,info)
                    call la_yherk('L','C',n1,n2,one,a(n1),n,one,a(0),n)
                    call la_ytrmm('L','U','N','N',n2,n1,cone,a(n),n,a(n1),n)

                    call la_ylauum('U',n2,a(n),n,info)
                 else
                    ! srpa for upper, normal and n is odd ( a(0:n-1,0:n2-1)
                    ! t1 -> a(n1+1,0), t2 -> a(n1,0), s -> a(0,0)
                    ! t1 -> a(n2), t2 -> a(n1), s -> a(0)
                    call la_ylauum('L',n1,a(n2),n,info)
                    call la_yherk('L','N',n1,n2,one,a(0),n,one,a(n2),n)
                    call la_ytrmm('R','U','C','N',n1,n2,cone,a(n1),n,a(0),n)

                    call la_ylauum('U',n2,a(n1),n,info)
                 end if
              else
                 ! n is odd and transr = 'c'
                 if (lower) then
                    ! srpa for lower, transpose, and n is odd
                    ! t1 -> a(0), t2 -> a(1), s -> a(0+n1*n1)
                    call la_ylauum('U',n1,a(0),n1,info)
                    call la_yherk('U','N',n1,n2,one,a(n1*n1),n1,one,a(0),n1)

                    call la_ytrmm('R','L','N','N',n1,n2,cone,a(1),n1,a(n1*n1), &
                              n1)
                    call la_ylauum('L',n2,a(1),n1,info)
                 else
                    ! srpa for upper, transpose, and n is odd
                    ! t1 -> a(0+n2*n2), t2 -> a(0+n1*n2), s -> a(0)
                    call la_ylauum('U',n1,a(n2*n2),n2,info)
                    call la_yherk('U','C',n1,n2,one,a(0),n2,one,a(n2*n2),n2)

                    call la_ytrmm('L','L','C','N',n2,n1,cone,a(n1*n2),n2,a(0), &
                              n2)
                    call la_ylauum('L',n2,a(n1*n2),n2,info)
                 end if
              end if
           else
              ! n is even
              if (normaltransr) then
                 ! n is even and transr = 'n'
                 if (lower) then
                    ! srpa for lower, normal, and n is even ( a(0:n,0:k-1) )
                    ! t1 -> a(1,0), t2 -> a(0,0), s -> a(k+1,0)
                    ! t1 -> a(1), t2 -> a(0), s -> a(k+1)
                    call la_ylauum('L',k,a(1),n + 1,info)
                    call la_yherk('L','C',k,k,one,a(k + 1),n + 1,one,a(1),n + 1)

                    call la_ytrmm('L','U','N','N',k,k,cone,a(0),n + 1,a(k + 1),n + 1)

                    call la_ylauum('U',k,a(0),n + 1,info)
                 else
                    ! srpa for upper, normal, and n is even ( a(0:n,0:k-1) )
                    ! t1 -> a(k+1,0) ,  t2 -> a(k,0),   s -> a(0,0)
                    ! t1 -> a(k+1), t2 -> a(k), s -> a(0)
                    call la_ylauum('L',k,a(k + 1),n + 1,info)
                    call la_yherk('L','N',k,k,one,a(0),n + 1,one,a(k + 1),n + 1)

                    call la_ytrmm('R','U','C','N',k,k,cone,a(k),n + 1,a(0),n + 1)

                    call la_ylauum('U',k,a(k),n + 1,info)
                 end if
              else
                 ! n is even and transr = 'c'
                 if (lower) then
                    ! srpa for lower, transpose, and n is even (see paper)
                    ! t1 -> b(0,1), t2 -> b(0,0), s -> b(0,k+1),
                    ! t1 -> a(0+k), t2 -> a(0+0), s -> a(0+k*(k+1)); lda=k
                    call la_ylauum('U',k,a(k),k,info)
                    call la_yherk('U','N',k,k,one,a(k*(k + 1)),k,one,a(k),k)

                    call la_ytrmm('R','L','N','N',k,k,cone,a(0),k,a(k*(k + 1)), &
                              k)
                    call la_ylauum('L',k,a(0),k,info)
                 else
                    ! srpa for upper, transpose, and n is even (see paper)
                    ! t1 -> b(0,k+1),     t2 -> b(0,k),   s -> b(0,0),
                    ! t1 -> a(0+k*(k+1)), t2 -> a(0+k*k), s -> a(0+0)); lda=k
                    call la_ylauum('U',k,a(k*(k + 1)),k,info)
                    call la_yherk('U','C',k,k,one,a(0),k,one,a(k*(k + 1)),k)

                    call la_ytrmm('L','L','C','N',k,k,cone,a(k*k),k,a(0),k)

                    call la_ylauum('L',k,a(k*k),k,info)
                 end if
              end if
           end if
           return
     end subroutine la_ypftri
#endif
#ifdef LA_WITH_QP
     !> WPFTRI: computes the inverse of a complex Hermitian positive definite
     !> matrix A using the Cholesky factorization A = U**H*U or A = L*L**H
     !> computed by WPFTRF.

     pure subroutine la_wpftri(transr,uplo,n,a,info)
        use la_constants_qp
        ! -- lapack computational routine --
        ! -- lapack is a software package provided by univ. of tennessee,    --
        ! -- univ. of california berkeley, univ. of colorado denver and nag ltd..--
           ! Scalar Arguments
           character,intent(in) :: transr,uplo
           integer(ilp),intent(out) :: info
           integer(ilp),intent(in) :: n
           ! Array Arguments
