        ! =====================================================================

           ! Local Scalars
           logical(lk) :: lower,nisodd,normaltransr
           integer(ilp) :: n1,n2,k
           ! Intrinsic Functions
           intrinsic :: mod
           ! Executable Statements
           ! test the input parameters.
           info = 0
           normaltransr = la_lsame(transr,'N')
           lower = la_lsame(uplo,'L')
           if (.not. normaltransr .and. .not. la_lsame(transr,'C')) then
              info = -1
           else if (.not. lower .and. .not. la_lsame(uplo,'U')) then
              info = -2
           else if (n < 0) then
              info = -3
           end if
           if (info /= 0) then
              call la_xerbla('WPFTRI',-info)
              return
           end if
           ! quick return if possible
           if (n == 0) return
           ! invert the triangular cholesky factor u or l.
           call la_wtftri(transr,uplo,'N',n,a,info)
           if (info > 0) return
           ! if n is odd, set nisodd = .true.
           ! if n is even, set k = n/2 and nisodd = .false.
           if (mod(n,2) == 0) then
              k = n/2
              nisodd = .false.
           else
              nisodd = .true.
           end if
           ! set n1 and n2 depending on lower
           if (lower) then
              n2 = n/2
              n1 = n - n2
           else
              n1 = n/2
              n2 = n - n1
           end if
           ! start execution of triangular matrix multiply: inv(u)*inv(u)^c or
           ! inv(l)^c*inv(l). there are eight cases.
           if (nisodd) then
              ! n is odd
              if (normaltransr) then
                 ! n is odd and transr = 'n'
                 if (lower) then
                    ! srpa for lower, normal and n is odd ( a(0:n-1,0:n1-1) )
                    ! t1 -> a(0,0), t2 -> a(0,1), s -> a(n1,0)
                    ! t1 -> a(0), t2 -> a(n), s -> a(n1)
                    call la_wlauum('L',n1,a(0),n,info)
                    call la_wherk('L','C',n1,n2,one,a(n1),n,one,a(0),n)
                    call la_wtrmm('L','U','N','N',n2,n1,cone,a(n),n,a(n1),n)

                    call la_wlauum('U',n2,a(n),n,info)
                 else
                    ! srpa for upper, normal and n is odd ( a(0:n-1,0:n2-1)
                    ! t1 -> a(n1+1,0), t2 -> a(n1,0), s -> a(0,0)
                    ! t1 -> a(n2), t2 -> a(n1), s -> a(0)
                    call la_wlauum('L',n1,a(n2),n,info)
                    call la_wherk('L','N',n1,n2,one,a(0),n,one,a(n2),n)
                    call la_wtrmm('R','U','C','N',n1,n2,cone,a(n1),n,a(0),n)

                    call la_wlauum('U',n2,a(n1),n,info)
                 end if
              else
                 ! n is odd and transr = 'c'
                 if (lower) then
                    ! srpa for lower, transpose, and n is odd
                    ! t1 -> a(0), t2 -> a(1), s -> a(0+n1*n1)
                    call la_wlauum('U',n1,a(0),n1,info)
                    call la_wherk('U','N',n1,n2,one,a(n1*n1),n1,one,a(0),n1)

                    call la_wtrmm('R','L','N','N',n1,n2,cone,a(1),n1,a(n1*n1), &
                              n1)
                    call la_wlauum('L',n2,a(1),n1,info)
                 else
                    ! srpa for upper, transpose, and n is odd
                    ! t1 -> a(0+n2*n2), t2 -> a(0+n1*n2), s -> a(0)
                    call la_wlauum('U',n1,a(n2*n2),n2,info)
                    call la_wherk('U','C',n1,n2,one,a(0),n2,one,a(n2*n2),n2)

                    call la_wtrmm('L','L','C','N',n2,n1,cone,a(n1*n2),n2,a(0), &
                              n2)
                    call la_wlauum('L',n2,a(n1*n2),n2,info)
                 end if
              end if
           else
              ! n is even
              if (normaltransr) then
                 ! n is even and transr = 'n'
                 if (lower) then
                    ! srpa for lower, normal, and n is even ( a(0:n,0:k-1) )
                    ! t1 -> a(1,0), t2 -> a(0,0), s -> a(k+1,0)
                    ! t1 -> a(1), t2 -> a(0), s -> a(k+1)
                    call la_wlauum('L',k,a(1),n + 1,info)
                    call la_wherk('L','C',k,k,one,a(k + 1),n + 1,one,a(1),n + 1)

                    call la_wtrmm('L','U','N','N',k,k,cone,a(0),n + 1,a(k + 1),n + 1)

                    call la_wlauum('U',k,a(0),n + 1,info)
                 else
                    ! srpa for upper, normal, and n is even ( a(0:n,0:k-1) )
                    ! t1 -> a(k+1,0) ,  t2 -> a(k,0),   s -> a(0,0)
                    ! t1 -> a(k+1), t2 -> a(k), s -> a(0)
                    call la_wlauum('L',k,a(k + 1),n + 1,info)
                    call la_wherk('L','N',k,k,one,a(0),n + 1,one,a(k + 1),n + 1)

                    call la_wtrmm('R','U','C','N',k,k,cone,a(k),n + 1,a(0),n + 1)

                    call la_wlauum('U',k,a(k),n + 1,info)
                 end if
              else
                 ! n is even and transr = 'c'
                 if (lower) then
                    ! srpa for lower, transpose, and n is even (see paper)
                    ! t1 -> b(0,1), t2 -> b(0,0), s -> b(0,k+1),
                    ! t1 -> a(0+k), t2 -> a(0+0), s -> a(0+k*(k+1)); lda=k
                    call la_wlauum('U',k,a(k),k,info)
                    call la_wherk('U','N',k,k,one,a(k*(k + 1)),k,one,a(k),k)

                    call la_wtrmm('R','L','N','N',k,k,cone,a(0),k,a(k*(k + 1)), &
                              k)
                    call la_wlauum('L',k,a(0),k,info)
                 else
                    ! srpa for upper, transpose, and n is even (see paper)
                    ! t1 -> b(0,k+1),     t2 -> b(0,k),   s -> b(0,0),
                    ! t1 -> a(0+k*(k+1)), t2 -> a(0+k*k), s -> a(0+0)); lda=k
                    call la_wlauum('U',k,a(k*(k + 1)),k,info)
                    call la_wherk('U','C',k,k,one,a(0),k,one,a(k*(k + 1)),k)

                    call la_wtrmm('L','L','C','N',k,k,cone,a(k*k),k,a(0),k)

                    call la_wlauum('L',k,a(k*k),k,info)
                 end if
              end if
           end if
           return
     end subroutine la_wpftri
